window.GLYPH_STORIES = {
  安: { headline: '屋檐之下，安居的想象。' },
  宇: { headline: '从房檐，到宇宙。' },
  光: { headline: '把光亮，举过头顶。' },
  包: { headline: '一个字，藏着包裹的形状。' },
  窗: { headline: '透过一个字，看见一扇窗。' },
  先: { headline: '走在前面，就成了「先」。' },
  男: { headline: '田与力，写进同一个字。' },
  "06592_一_Z_說文‧一部": {"headline": "一就是一横，简单又直接。", "original_meaning": "一，是万物的起点。古人认为天地刚开始形成时，大道就立在'一'上，由一分化出天地，再化育出万物。", "structure_desc": "在甲骨文和金文里，'一'就是一横，用一横来表示数字'一'。古人后来还造过一个繁写体'弌'，在'一'上加了'弋'当声符，但因为'弋'的笔画容易和'戈'混在一起，最后还是用回了最简单的一横。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「一」條；香港中文大學《漢語多功能字庫》「一」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%80（2026-11-03 查閱）"},
  "06601_三_Z_說文‧三部": {"headline": "三横排排坐，就是三。", "original_meaning": "三，代表天、地、人三者。", "structure_desc": "甲骨文和金文里，'三'就是三横。古人把一到四都用横画来表示：一横是一，两横是二，三横是三，四横是四。学者徐中舒认为这些横画其实是古代计数用的小木棍（算筹）。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「三」條；香港中文大學《漢語多功能字庫》「三」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%89（2026-11-03 查閱）"},
  "06602_上_Z_小篆": {"headline": "短横画在长横上，就是「上」。", "original_meaning": "上，指位置在高处。古人用一个符号来指明「上面」这个方位。", "structure_desc": "最早的「上」字，是在一条弧线（后来刻成直线）上面加一短横，用短横所在的位置来表示「上面」的意思。早期甲骨文和金文里，「上」写作两横的样子，和「二」很像，容易和数字「二」以及「下」搞混。所以到了春秋晚期，人们多加了一竖笔，写成了现在的「上」字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「丄」條（今字作「上」）；香港中文大學《漢語多功能字庫》「上」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%8A（2026-11-03 查閱）"},
  "06603_下_Z_小篆": {"headline": "短横画在长横下，就是「下」。", "original_meaning": "下，指位置在低处，和「上」相对。", "structure_desc": "最早的「下」字，是在一条弧线（后来刻成直线）下面加一短横，用短横所在的位置来表示「下面」的意思。早期甲骨文和金文里，「下」写作两横的样子，容易和「上」以及数字「二」搞混。所以到了春秋晚期，人们多加了一竖笔，写成了现在的「下」字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「丅」條（今字作「下」）；香港中文大學《漢語多功能字庫》「下」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%8B（2026-11-03 查閱）"},
  "06605_不_Z_說文‧不部": {"headline": "「不」本来画的是植物的根须。", "original_meaning": "「不」本来指植物的根须，后来被借来表示否定的意思。", "structure_desc": "关于「不」字的来历有两种说法。一种认为上面的横画代表地面，下面的笔画像植物扎在土里的根须，所以「不」原本就是草根的意思。另一种说法认为「不」像花朵底部的花萼。不管哪种说法，「不」原本是个表示具体事物的字，后来被借来专门表示否定的意思，一直用到现在。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「不」條；香港中文大學《漢語多功能字庫》「不」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%8D（2026-11-03 查閱）"},
  "06606_与_Z_說文‧勺部": {"headline": "两只手互相递东西，就是「与」。", "original_meaning": "「与」的本义是给予、赐予，就是把东西交给别人。", "structure_desc": "金文的「与」字，画的是两个人（上面两只手和下面两只手）互相交付牙齿的样子。古人有赠送牙齿的习俗，所以用「递牙齿」来表示「给予」的意思。直到今天，一些少数民族还保留着类似的风俗。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「與」條；香港中文大學《漢語多功能字庫》「與」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%88%87（2026-11-03 查閱）"},
  "06618_业_Z_小篆": {"headline": "「业」原来是挂钟磬的木架子。", "original_meaning": "「业」指古代悬挂钟和磬的架子上面那块带锯齿的大木板。", "structure_desc": "「业」字的形状，像两个并排站立的铜人举着一根横木，横木上挂着钟和磬。所以「业」本来指的是古代悬挂乐器的架子，架子上的木板边缘刻成锯齿状，用来挂钟和磬。后来「业」引申出事业、学业等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「業」條；香港中文大學《漢語多功能字庫》「業」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A5%AD（2026-11-03 查閱）"},
  "06628_两_Z_小篆": {"headline": "「两」本来画的是车前套牲口的两根直木。", "original_meaning": "「两」本来指古代马车前面套牲口的两根直木（车轭），后来表示成双成对的意思。", "structure_desc": "「两」字是从古代「车」字里截取一部分造出来的，画的是马车辕木前端横杠上系着的两根套牲口的直木。因为这两根直木是成对出现的，所以「两」就有了「成双」「两个」的意思。后来又用作重量单位。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「兩」條；香港中文大學《漢語多功能字庫》「兩」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%A9（2026-11-03 查閱）"},
  "06637_中_Z_說文‧丨部": {"headline": "「中」画的是古代测风向的旗杆。", "original_meaning": "「中」指中央、中间，就是方位上不偏不倚的位置。", "structure_desc": "甲骨文的「中」字，画的是一根长杆子，杆子的上部、下部或上中下都挂着飘带。这其实是古代测量风向的工具。因为测风向的杆子要立在中心位置，所以「中」就有了「中央」「中间」的意思。后来又引申出「中等」「适中」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「中」條；香港中文大學《漢語多功能字庫》「中」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%AD（2026-11-03 查閱）"},
  "06650_为_Z_小篆": {"headline": "一只手牵着大象干活，就是「为」。", "original_meaning": "「为」的本义是做事、作为。古人驯养大象来干活，所以用「手牵大象」来表示做事。", "structure_desc": "甲骨文和金文的「为」字，画的是一只手牵着一头大象。商朝的时候，人们驯养大象来帮忙干活，所以用「手牵大象」这个形象来表示「做事」的意思。后来「为」又引申出「作为」「成为」等意思，还经常用作虚词。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「爲」條（今字作「為」）；香港中文大學《漢語多功能字庫》「為」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%82%BA（2026-11-03 查閱）"},
  "06651_主_Z_說文‧丶部": {"headline": "「主」原来画的是祭祀用的牌位。", "original_meaning": "「主」指古代祭祀时供奉的牌位，也指灯盏里的火芯。", "structure_desc": "甲骨文的「主」字，画的是祭祀用的牌位形状。「主」和「示」本来是同一个字，后来才分开。「主」本来指祭祀的牌位，牌位代表祖先，所以引申出「主人」「主要」的意思。另外，「主」也指灯盏里的火芯，就是灯炷，后来另造了「炷」字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「主」條；香港中文大學《漢語多功能字庫》「主」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%BB（2026-11-03 查閱）"},
  "06664_么_Z_小篆": {"headline": "「么」就是细小、微小的意思。", "original_meaning": "「么」（麽）的本义是细小、微小。", "structure_desc": "「么」是「麽」的简写，本义是细小、微小。比如古书里说的「麽虫」，就是指很小的虫子。后来「么」多用作词尾，比如「什么」「这么」「那么」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「麼」條；香港中文大學《漢語多功能字庫》「麼」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%BA%BC（2026-11-03 查閱）"},
  "06667_之_Z_說文‧之部": {"headline": "一只脚离开地面往前走，就是「之」。", "original_meaning": "「之」的本义是前往、到……去。", "structure_desc": "甲骨文的「之」字，上面是一只脚（「止」），下面一横代表地面。合起来表示脚从地面上迈出去，前往某个地方。后来「之」多用作虚词，比如「之间」「之后」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「之」條；香港中文大學《漢語多功能字庫》「之」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B9%8B（2026-11-03 查閱）"},
  "06687_也_Z_說文‧𠂆部": {"headline": "「也」字画的是嘴里呼出的气。", "original_meaning": "「也」是语气词，表示停顿或肯定的语气。", "structure_desc": "金文的「也」字，上面是「口」，下面是一弯弯曲曲的竖画，像从嘴里呼出来的气。「也」本来就是用来表示语气停顿的，相当于现在说的「啊」「呢」。后来经常用在句末，表示肯定或感叹的语气。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「也」條；香港中文大學《漢語多功能字庫》「也」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B9%9F（2026-11-03 查閱）"},
  "06726_了_Z_說文‧了部": {"headline": "「了」字画的是手腿弯曲的样子。", "original_meaning": "「了」的本义是弯曲，引申为完结、结束。", "structure_desc": "「了」字画的是一个孩子没有手臂、手脚弯曲的样子，本义是弯曲。因为做事做到最后手脚都弯下来了，所以引申出「完结」「结束」的意思，比如「完了」「了结」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「了」條；香港中文大學《漢語多功能字庫》「了」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%86（2026-11-03 查閱）"},
  "06731_事_Z_說文‧史部": {"headline": "「事」画的是手里拿着打猎的工具。", "original_meaning": "「事」指职务、工作，就是要做的事情。", "structure_desc": "甲骨文的「事」字，是一只手拿着一个打猎用的工具。后来这个字形分化出了「史」「吏」「事」「使」四个字，它们原本是同一个字。其中「事」专门用来表示「职务」「事情」的意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「事」條；香港中文大學《漢語多功能字庫》「事」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%8B（2026-11-03 查閱）"},
  "06734_于_Z_說文‧于部": {"headline": "「于」本来画的是古代的乐器竽。", "original_meaning": "「于」本来指古代的管乐器竽，后来借用作虚词，表示在、到、对的意思。", "structure_desc": "「于」字的来历有两种说法。一种认为甲骨文画的是管状乐器竽的形状，竽是把很多根竹管并在一起做成的乐器。后来为了书写方便，简化成了「于」字。再后来「于」被借用作虚词，表示「在」「到」「对」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「亏」條（今字作「于」）；香港中文大學《漢語多功能字庫》「于」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%8E（2026-11-03 查閱）"},
  "06747_些_Z_說文‧此部": {"headline": "「些」表示少量、一点点。", "original_meaning": "「些」的本义是少量、少许。", "structure_desc": "「些」字从「此」从「二」，本义是少量、少许。比如「一些」「些许」，都是表示数量不多的意思。在古代楚辞里，「些」还用作句末的语气词。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「些」條；香港中文大學《漢語多功能字庫》「些」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%9B（2026-11-03 查閱）"},
  "06759_产_Z_小篆": {"headline": "「产」就是生出来、造出来的意思。", "original_meaning": "「产」的本义是出生、生产。", "structure_desc": "「产」的繁体字是「產」，从「生」，表示出生的意思。「产」本来指生孩子，后来引申为生产、制造、出产等意思，比如「产物」「产量」「特产」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「産」條（今字作「產」）；香港中文大學《漢語多功能字庫》「產」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%A2（2026-11-03 查閱）"},
  "06778_人_Z_說文‧人部": {"headline": "「人」画的是一个人侧身站着的样子。", "original_meaning": "「人」指人类，是天地间最尊贵的生物。", "structure_desc": "古文字的「人」字，画的是一个人侧身站立、双手下垂的样子，上面是头和手臂，下面是腿。古人认为人是天地间最尊贵的生物，所以用一个简单的人形来表示。「人」和「千」本来是同一个字，后来才分开。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「人」條；香港中文大學《漢語多功能字庫》「人」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%BA（2026-11-03 查閱）"},
  "06784_什_Z_說文‧人部": {"headline": "「什」就是以十个人为一组。", "original_meaning": "「什」指以十为单位，古代十家或十人为一「什」。", "structure_desc": "「什」从「人」从「十」，本义是以十为单位。古代十家组成一「什」，互相担保；军队里十个人也组成一「什」。后来「什」引申为各种杂样的意思，比如「什物」就是各种日用物品，「什锦」就是多种花样的。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「什」條；香港中文大學《漢語多功能字庫》「什」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%80（2026-11-03 查閱）"},
  "06798_从_Z_說文‧从部": {"headline": "两个人一前一后跟着走，就是「从」。", "original_meaning": "「从」的本义是跟随、跟从。", "structure_desc": "甲骨文和金文的「从」字，是两个人一前一后跟着走的样子，本义是跟随。后来人们在「从」的基础上加了表示行走的「辵」旁，造出了「從」字。现在的简化字又把它简化回了「从」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「从」條；香港中文大學《漢語多功能字庫》「从」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%8E（2026-11-03 查閱）"},
  "06806_他_Z_小篆": {"headline": "「他」指别的人或事物。", "original_meaning": "「他」是代词，指别的、其他的，也用来指第三方。", "structure_desc": "「他」在甲骨文和金文里都没有出现，是个比较晚才有的字。它本来是个代词，指「别的」「其他的」，比如「其他」「他乡」。后来也用来指代第三方的人或事物。在古代，「他」可以指代男、女和一切东西，专门用来指男性是现代汉语才有的用法。", "source": "香港中文大學《漢語多功能字庫》「他」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%96（2026-11-03 查閱）；《說文解字》未收此字"},
  "06821_以_Z_說文‧巳部": {"headline": "「以」画的是用手提着东西。", "original_meaning": "「以」的本义是用手拿着、提着，后来多用作虚词。", "structure_desc": "甲骨文的「以」字，画的是一个人用手提着一样东西，本义是拿、用。后来「以」多借用作虚词，表示「用」「凭借」「因为」等意思，比如「以一当十」「以理服人」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「㠯」條（今字作「以」）；香港中文大學《漢語多功能字庫》「以」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%A5（2026-11-03 查閱）"},
  "06874_会_Z_小篆": {"headline": "「会」画的是用盖子把器皿盖起来。", "original_meaning": "「会」的本义是相合、合拢，引申为聚会、会合。", "structure_desc": "甲骨文和金文的「会」字，上面是盖子，下面是器皿，中间装着东西，合起来表示用盖子把器皿盖好，本义是相合。后来引申出「聚会」「会合」「会议」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「會」條；香港中文大學《漢語多功能字庫》「會」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%83（2026-11-03 查閱）"},
  "06918_但_Z_說文‧人部": {"headline": "「但」本来指脱掉上衣露出身体。", "original_meaning": "「但」的本义是脱去上衣、露出身体，后来多用作转折连词。", "structure_desc": "「但」从「人」，「旦」声。本义是指人没有穿上衣，露出身体，这个意思后来多写作「袒」。再后来「但」被借用作转折连词，相当于「不过」「但是」，比如「他很累，但还是坚持工作」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「但」條；香港中文大學《漢語多功能字庫》「但」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%86（2026-11-03 查閱）"},
  "06931_体_Z_小篆": {"headline": "「体」指人的身体。", "original_meaning": "「体」（體）的本义是人的身体。", "structure_desc": "「体」的繁体字是「體」，从「骨」，本义是人的身体。「體」字出现得比较晚，早期有的从「身」，有的从「肉」，后来才统一成从「骨」的写法。现在简化为「体」，从「人」从「本」，表示身体是人的根本。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「體」條；香港中文大學《漢語多功能字庫》「體」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%AB%94（2026-11-03 查閱）"},
  "06940_作_Z_說文‧人部": {"headline": "「作」就是开始做、站起来干。", "original_meaning": "「作」的本义是起来、开始做。", "structure_desc": "「作」从「人」从「乍」，本义是起来、开始做事。古代一般写作「乍」，后来加了「人」旁变成「作」。「作」有做、制作、兴起等意思，比如「工作」「创作」「振作」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「作」條；香港中文大學《漢語多功能字庫》「作」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%9C（2026-11-03 查閱）"},
  "07464_全_Z_說文‧入部": {"headline": "「全」本来指没有瑕疵的纯玉。", "original_meaning": "「全」指纯粹、完整、没有缺陷，最早用来形容纯色的玉。", "structure_desc": "「全」字从「入」从「玉」，本义是指没有瑕疵的、纯色的玉。古人认为纯色的玉最完美，所以「全」引申出「完整」「全部」「保全」的意思，比如「完全」「齐全」「两全其美」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「㒰」條（今字作「全」）；香港中文大學《漢語多功能字庫》「全」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%A8（2026-11-03 查閱）"},
  "07468_公_Z_說文‧八部": {"headline": "「公」就是和「私」对着干。", "original_meaning": "「公」指公平、公共，和「私」相对。", "structure_desc": "关于「公」字的来历，古人认为是和「私」相对的。「厶」就是「私」，画的是一个人只顾自己绕圈圈；而「公」在「厶」上面加了「八」（表示分开、相背），意思是和自私对着干，所以「公」就是公平、公共的意思。也有学者认为「公」本来是瓮（一种大肚子的陶器）的象形字，后来被借来表示公私的公。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「公」條；香港中文大學《漢語多功能字庫》「公」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%AC（2026-11-03 查閱）"},
  "07475_关_Z_小篆": {"headline": "「关」就是给门上门闩。", "original_meaning": "「关」的本义是用木棍把门闩上，后来引申为关闭、关口等意思。", "structure_desc": "金文的「关」字，外面是两扇门，里面是用来闩门的木棍和锁环，本义就是把门关上。后来引申出「关闭」「关口」「机关」「关心」等意思。繁体字写作「關」，现在简化为「关」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「關」條；香港中文大學《漢語多功能字庫》「關」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%97%9C（2026-11-03 查閱）"},
  "07478_其_Z_說文‧箕部": {"headline": "「其」本来画的是簸箕。", "original_meaning": "「其」本来指簸箕（扬米去糠的工具），后来多借用作代词。", "structure_desc": "甲骨文的「其」字，画的就是一个簸箕的形状，是「箕」的本字。后来「其」被借用作代词，表示「他的」「那个」「难道」等意思，比如「其他」「其实」。簸箕的意思则另造了「箕」字来表示。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「箕」條（今字作「其」）；香港中文大學《漢語多功能字庫》「其」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%B6（2026-11-03 查閱）"},
  "07610_出_Z_說文‧出部": {"headline": "「出」就是一只脚从山洞里迈出来。", "original_meaning": "「出」的本义是外出、从里面到外面。", "structure_desc": "甲骨文的「出」字，上面是一只脚（「止」），下面是一个洞穴（「凵」）。古人住在山洞里，所以用「脚从洞穴里走出来」来表示「外出」的意思。后来引申出「出现」「出产」「出去」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「出」條；香港中文大學《漢語多功能字庫》「出」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%87%BA（2026-11-03 查閱）"},
  "07622_分_Z_說文‧八部": {"headline": "「分」就是拿刀把东西切成两半。", "original_meaning": "「分」的本义是分开、切分。", "structure_desc": "甲骨文的「分」字，上面是「八」（表示分开的两样东西），下面是「刀」，合起来就是用刀把东西切开的意思。「分」和「八」读音相近，意思也差不多，有些学者认为它们本来是同一个字。后来「分」引申出「区分」「分配」「分数」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「分」條；香港中文大學《漢語多功能字庫》「分」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%86（2026-11-03 查閱）"},
  "07659_别_Z_小篆": {"headline": "「别」就是用刀把骨肉分开。", "original_meaning": "「别」的本义是分解、分割，后来引申为分别、离别。", "structure_desc": "甲骨文的「别」字，是一把刀和一块骨头的组合，表示用刀把骨肉分割开。本义是分解、分割。后来引申出「分别」「区别」「离别」等意思，比如「告别」「久别重逢」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𠛰」條（今字作「別」）；香港中文大學《漢語多功能字庫》「別」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%A5（2026-11-03 查閱）"},
  "07664_到_Z_說文‧至部": {"headline": "「到」就是到达、来到目的地。", "original_meaning": "「到」的本义是来到、到达。", "structure_desc": "「到」从「至」（表示到达），「刀」表音，本义是来到、到达。比如「到达」「到站」「到时候」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「到」條；香港中文大學《漢語多功能字庫》「到」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%B0（2026-11-03 查閱）"},
  "07670_制_Z_說文‧刀部": {"headline": "「制」就是用刀砍断树木。", "original_meaning": "「制」的本义是裁剪、砍断，引申为制作、规定。", "structure_desc": "金文的「制」字，是一棵树（木或未）和一把刀的组合，表示用刀斧砍劈木材。本义是裁剪、砍断。后来引申出制作、规定、制度等意思，比如「制造」「制定」「制度」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「制」條；香港中文大學《漢語多功能字庫》「制」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%B6（2026-11-03 查閱）"},
  "07693_前_Z_說文‧止部": {"headline": "「前」就是穿上鞋子往前走。", "original_meaning": "「前」的本义是前进、向前走。", "structure_desc": "金文的「前」字，上面是一只脚（止），下面是一只鞋子（舟），合起来表示穿上鞋子向前走，本义是前进。后来引申出「前面」「以前」「前进」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「歬」條（今字作「前」）；香港中文大學《漢語多功能字庫》「前」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%89%8D（2026-11-03 查閱）"},
  "07771_力_Z_說文‧力部": {"headline": "「力」画的是古代翻土的农具。", "original_meaning": "「力」指力气、力量，因为干活要用力气。", "structure_desc": "甲骨文的「力」字，画的是一种古代农具，就是一根尖头木棒，中间的短横是踏脚的地方。用农具翻土耕作需要力气，所以「力」就引申出「力气」「力量」的意思，比如「力气」「动力」「能力」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「力」條；香港中文大學《漢語多功能字庫》「力」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%9B（2026-11-03 查閱）"},
  "07776_加_Z_說文‧力部": {"headline": "「加」就是干活时加把劲。", "original_meaning": "「加」的本义是增加、加上。", "structure_desc": "金文的「加」字，左边是「力」（农具），右边是「口」。有学者认为，「力」表示用农具掘地干活，「口」表示用力时嘴里的呼喝声，合起来就是干活时加把劲的意思。后来引申出「增加」「加上」「加入」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「加」條；香港中文大學《漢語多功能字庫》「加」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%A0（2026-11-03 查閱）"},
  "07784_动_Z_小篆": {"headline": "「动」就是行动、动起来。", "original_meaning": "「动」（動）的本义是行动、起动。", "structure_desc": "「动」的繁体字是「動」，从「力」，「重」表音，本义是行动、起动。比如「运动」「动手」「感动」。现在简化为「动」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「動」條；香港中文大學《漢語多功能字庫》「動」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8B%95（2026-11-03 查閱）"},
  "07894_化_Z_說文‧𠤎部": {"headline": "「化」就是一个人正、一个人倒，颠倒就是变化。", "original_meaning": "「化」的本义是变化、改变。", "structure_desc": "甲骨文和金文的「化」字，是一正一反两个人形，用一个人朝上、一个人朝下的样子，表示颠倒、变化的意思。本义是变化。后来引申出「教化」「化学」「文化」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「化」條；香港中文大學《漢語多功能字庫》「化」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8C%96（2026-11-03 查閱）"},
  "07937_十_Z_說文‧十部": {"headline": "「十」就是数字十，一竖加一横。", "original_meaning": "「十」是数字十。", "structure_desc": "甲骨文和早期金文里，「十」写作一竖「丨」。关于这一竖的来历有很多说法：有人认为像针，用针来代表数字十；有人认为数到十就进一位，为了和「一」（横）区分，所以写成竖；还有人认为是两只手合十竖起来的样子。后来在竖画中间加了一点（后来变成一横），才写成现在的「十」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「十」條；香港中文大學《漢語多功能字庫》「十」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%81（2026-11-03 查閱）"},
  "08059_去_Z_說文‧去部": {"headline": "「去」就是离开、往别处走。", "original_meaning": "「去」的本义是离开、前往别处。", "structure_desc": "「去」字由「大」和「口」组成。关于它的来历有不同看法，一种认为「大」「口」表示张大嘴巴，是「呿」（张口）的本字。但「去」在实际使用中多表示离开、前往的意思，比如「去年」「过去」「去到」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「去」條；香港中文大學《漢語多功能字庫》「去」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8E%BB（2026-11-03 查閱）"},
  "08072_又_Z_說文‧又部": {"headline": "「又」本来画的是一只右手。", "original_meaning": "「又」的本义是右手，后来借用作「再一次」的意思。", "structure_desc": "甲骨文和金文的「又」字，画的是一只右手的侧面形状，所以本义就是右手。后来「又」被借用来表示「再一次」「还」的意思，比如「又来一个」「又高又大」。表示右手的意思则另造了「右」字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「又」條；香港中文大學《漢語多功能字庫》「又」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%88（2026-11-03 查閱）"},
  "08081_发_Z_小篆": {"headline": "「发」就是拉开弓弦把箭射出去。", "original_meaning": "「发」（發）的本义是发射、射箭。", "structure_desc": "甲骨文的「发」字，画的是一张弓，弓弦那里有几个小点，表示箭射出去后弓弦还在颤动的样子，本义就是发射。后来引申出「发生」「发现」「发展」等意思。繁体字写作「發」，现在简化为「发」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「發」條；香港中文大學《漢語多功能字庫》「發」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%99%BC（2026-11-03 查閱）"},
  "08106_只_Z_說文‧只部": {"headline": "「只」是语气词，后来表示「仅仅」。", "original_meaning": "「只」本义是句末语气词，后来表示「仅仅」「只有」。", "structure_desc": "「只」从「口」，下面的笔画像气往下走的样子，本来是句末的语气词，相当于「啊」「呢」。后来「只」多用来表示「仅仅」「只有」的意思，比如「只此一家」「只管去做」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「只」條；香港中文大學《漢語多功能字庫》「只」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%AA（2026-11-03 查閱）"},
  "08111_可_Z_說文‧可部": {"headline": "「可」就是「行、能够」的意思。", "original_meaning": "「可」的本义是可以、能够。", "structure_desc": "「可」从「口」，「丂」表音。关于「丂」的形状，有人认为像树枝，有人认为像斧头的柄。「可」后来借用来表示「可以」「能够」的意思，比如「可以」「可爱」「许可」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「可」條；香港中文大學《漢語多功能字庫》「可」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%AF（2026-11-03 查閱）"},
  "08131_吃_Z_說文‧口部": {"headline": "「吃」本来指口吃，后来表示吃饭。", "original_meaning": "「吃」的本义是口吃（说话结巴），后来才表示吃东西。", "structure_desc": "「吃」从「口」，「气」表音，本义是口吃，就是说话不流利、结巴。后来「吃」被用来表示吃东西的意思，这个意思古代一般写作「喫」。比如「吃饭」「吃苦」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𠯏」條（今字作「吃」）；香港中文大學《漢語多功能字庫》「吃」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%83（2026-11-03 查閱）"},
  "08136_合_Z_說文‧亼部": {"headline": "「合」就是盖子和器皿扣在一起。", "original_meaning": "「合」的本义是相合、合拢，引申为聚合、会合。", "structure_desc": "甲骨文和金文的「合」字，上面是盖子，下面是器皿（口），合起来表示盖子和器皿扣在一起，本义是相合。后来引申出「会合」「聚合」「合作」等意思，比如「合力」「合二为一」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「合」條；香港中文大學《漢語多功能字庫》「合」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%88（2026-11-03 查閱）"},
  "08140_同_Z_說文‧𠔼部": {"headline": "「同」就是「一样、相同」的意思。", "original_meaning": "「同」的本义是会合、相同。", "structure_desc": "甲骨文的「同」字，有学者认为外面像桶、筒一类的器物，里面加「口」。「同」的本义是会合、相同，表示一样、没有差别。比如「同样」「相同」「共同」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「同」條；香港中文大學《漢語多功能字庫》「同」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%8C（2026-11-03 查閱）"},
  "08142_后_Z_說文‧后部": {"headline": "「后」本来指君主，后来指皇后。", "original_meaning": "「后」的本义是君主、君王。", "structure_desc": "「后」和「司」在甲骨文里其实是同一个字，只是方向相反。「后」在金文里才出现，本义是君主、君王。比如「后羿」就是古代的一位君主。后来「后」专指君王的妻子，也就是皇后、太后。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「后」條；香港中文大學《漢語多功能字庫》「后」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%8E（2026-11-03 查閱）"},
  "08268_和_Z_說文‧口部": {"headline": "「和」就是声音相应、和谐相处。", "original_meaning": "「和」的本义是声音相应、和谐，引申为和睦。", "structure_desc": "「和」从「口」，「禾」表音，本义是声音相应和，就是你唱我和、互相应答的意思。后来引申为和谐、和睦，比如「和平」「和气」「和和美美」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「和」條；香港中文大學《漢語多功能字庫》「和」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%92%8C（2026-11-03 查閱）"},
  "08862_回_Z_說文‧囗部": {"headline": "「回」就是水流旋转、打圈圈。", "original_meaning": "「回」的本义是旋转、回转。", "structure_desc": "「回」字画的是回环旋转的形状，像水流打圈圈的样子。本义是旋转、回转。后来引申出「回来」「回答」「回想」等意思，比如「回家」「回复」「回忆」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「回」條；香港中文大學《漢語多功能字庫》「回」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9B%9E（2026-11-03 查閱）"},
  "08864_因_Z_說文‧囗部": {"headline": "「因」就是人被衣服裹在里面。", "original_meaning": "「因」的本义是依靠、凭借，也表示原因。", "structure_desc": "甲骨文的「因」字，是一个人（大）被衣服包裹着的样子，本义是人在衣服里。后来「因」引申出「凭借」「沿袭」「原因」等意思，比如「因为」「原因」「因势利导」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「因」條；香港中文大學《漢語多功能字庫》「因」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9B%A0（2026-11-03 查閱）"},
  "08893_国_Z_小篆": {"headline": "「国」就是用围墙围起来的城邦。", "original_meaning": "「国」（國）的本义是国家、城邦。", "structure_desc": "金文的「国」字，外面是「囗」（表示围墙、边界），里面是「或」（表示武器和人口）。合起来就是用围墙保护起来的城邦，本义就是国家。繁体字写作「國」，现在简化为「国」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「國」條；香港中文大學《漢語多功能字庫》「國」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%8B（2026-11-03 查閱）"},
  "08936_在_Z_說文‧土部": {"headline": "「在」就是存在、待在某个地方。", "original_meaning": "「在」的本义是存在、处于某个位置。", "structure_desc": "「在」从「土」，「才」表音，本义是存在、处于某个位置。甲骨文和金文里常借用「才」字来表示「在」。后来「在」引申出「在于」「正在」等意思，比如「在家」「正在」「存在」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「在」條；香港中文大學《漢語多功能字庫》「在」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%A8（2026-11-03 查閱）"},
  "08944_地_Z_說文‧土部": {"headline": "「地」就是我们脚下的大地。", "original_meaning": "「地」指大地、土地，和「天」相对。", "structure_desc": "「地」从「土」，「也」表音，本义是大地，就是我们脚下踩着的土地，和天上的「天」相对。古人认为天是轻清的阳气上浮形成的，地是重浊的阴气下沉形成的。比如「土地」「地面」「天地」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「地」條；香港中文大學《漢語多功能字庫》「地」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%B0（2026-11-03 查閱）"},
  "09430_外_Z_說文‧夕部": {"headline": "「外」就是里面的对面。", "original_meaning": "「外」指外面、外部，和「内」相对。", "structure_desc": "古人用占卜时的裂纹来区分内外，竖画是中界，横向裂纹指向的是里面，另一面就是外面。所以甲骨文用「卜」字来表示「外」，金文又加了「月」来表音。后来「外」表示外面、外部，比如「外面」「里外」「外国」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「外」條；香港中文大學《漢語多功能字庫》「外」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%96（2026-11-03 查閱）"},
  "09434_多_Z_說文‧多部": {"headline": "「多」就是两块肉，古时候两块肉就算多了。", "original_meaning": "「多」的本义是数量多，和「少」相对。", "structure_desc": "甲骨文的「多」字，是两块肉叠在一起的样子。古时候物资匮乏，能有两块肉就算很多了，所以用两块肉来表示「多」的意思。后来「多」泛指数量大，比如「很多」「多少」「众多」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「多」條；香港中文大學《漢語多功能字庫》「多」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%9A（2026-11-03 查閱）"},
  "09447_大_Z_說文‧大部": {"headline": "「大」画的是一个张开双臂的大人。", "original_meaning": "「大」指体积、面积、数量等超过一般，和「小」相对。", "structure_desc": "甲骨文的「大」字，画的是一个人正面站立、双臂张开的样子。本义就是成年人（大人），和表示小孩的「子」相对。因为大人比小孩大，所以引申出「大小」的「大」。比如「大人」「大小」「巨大」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「大」條；香港中文大學《漢語多功能字庫》「大」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%A7（2026-11-03 查閱）"},
  "09449_天_Z_說文‧一部": {"headline": "「天」就是人头顶上的那一片空间。", "original_meaning": "「天」本义指人的头顶，后来指天空。", "structure_desc": "甲骨文的「天」字，下面是一个正面站立的人（大），上面突出头部（一个圆点或一横）。本义是人的头顶。因为头顶上方就是天空，而天空和头顶一样都是最高的地方，所以「天」就引申为天空的意思，比如「天空」「天地」「今天」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「天」條；香港中文大學《漢語多功能字庫》「天」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%A9（2026-11-03 查閱）"},
  "09460_头_Z_小篆": {"headline": "「头」就是人的脑袋。", "original_meaning": "「头」（頭）的本义是脑袋、头部。", "structure_desc": "「头」的繁体字是「頭」，从「页」（表示头部），「豆」表音。「页」字画的是一个人形，特别突出头部。「头」的本义就是人的脑袋。现在简化为「头」。比如「头发」「头顶」「开头」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「頭」條；香港中文大學《漢語多功能字庫》「頭」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A0%AD（2026-11-03 查閱）"},
  "09533_好_Z_說文‧女部": {"headline": "「好」就是妈妈抱着孩子，真好。", "original_meaning": "「好」的本义是美好，引申为优点多、令人满意。", "structure_desc": "甲骨文和金文的「好」字，左边是一个女子，右边是一个孩子，合起来表示母亲抱着孩子的情景。有学者认为这是母子相亲的样子，所以「好」的本义是美好。后来引申出「优点多」「令人满意」等意思，比如「好坏」「好人」「美好」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「好」條；香港中文大學《漢語多功能字庫》「好」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A5%BD（2026-11-03 查閱）"},
  "09538_如_Z_說文‧女部": {"headline": "「如」就是照着做、跟从。", "original_meaning": "「如」的本义是顺从、跟随，后来表示「好像」「如同」。", "structure_desc": "「如」从「女」从「口」，表示口里发出命令，女子听从照办的意思。本义是顺从、跟随。后来引申出「如同」「好像」等意思，比如「如果」「如今」「如意」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「如」條；香港中文大學《漢語多功能字庫》「如」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A6%82（2026-11-03 查閱）"},
  "10000_子_Z_說文‧子部": {"headline": "「子」画的是一个被包在襁褓里的婴儿。", "original_meaning": "「子」指小孩、婴儿，也指儿女。", "structure_desc": "甲骨文和金文的「子」字，画的是一个刚出生的婴儿，头上有头发，两条小腿包在襁褓里。本义就是小孩、婴儿。后来也用来表示儿女，或者对人的尊称，比如「孔子」「孟子」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「子」條；香港中文大學《漢語多功能字庫》「子」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%90（2026-11-03 查閱）"},
  "10022_学_Z_小篆": {"headline": "「学」就是教孩子用手摆弄算筹学算术。", "original_meaning": "「学」（學）的本义是学习、教导。", "structure_desc": "甲骨文的「学」字，画的是双手摆弄算筹（古代计数的工具）来学习算术的样子。金文又加了一个「子」（小孩），表示学习是和孩子有关的。繁体字写作「學」，现在简化为「学」。比如「学习」「学校」「学问」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「斆」條（今字作「學」）；香港中文大學《漢語多功能字庫》「學」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%B8（2026-11-03 查閱）"},
  "10074_定_Z_說文‧宀部": {"headline": "「定」就是屋里有了落脚的地方，心就安稳了。", "original_meaning": "「定」的本义是安定、安稳。", "structure_desc": "「定」从「宀」（房屋），「正」表音。房屋是安身的地方，有了房子心就安定了，所以「定」的本义是安定。后来引申出「决定」「一定」「稳定」等意思，比如「安定」「决定」「一定」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「定」條；香港中文大學《漢語多功能字庫》「定」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%9A（2026-11-03 查閱）"},
  "10078_实_Z_小篆": {"headline": "「实」就是屋子里堆满了宝贝。", "original_meaning": "「实」（實）的本义是富足、充实。", "structure_desc": "「实」的繁体字是「實」，从「宀」（房屋）从「贯」（穿成串的钱）。合起来就是屋子里堆满了钱财宝贝的意思，本义是富足、充实。后来引申出「真实」「实际」「果实」等意思，比如「诚实」「实际」「果实」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「實」條；香港中文大學《漢語多功能字庫》「實」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AF%A6（2026-11-03 查閱）"},
  "10102_家_Z_說文‧宀部": {"headline": "「家」就是屋里养着猪，就是家。", "original_meaning": "「家」指家庭、住所。", "structure_desc": "甲骨文和金文的「家」字，上面是房屋（宀），下面是一头猪（豕）。古人家里养猪，所以用「屋里有猪」来表示家。本义就是家庭、住所。后来引申出「家族」「家里」等意思，比如「家人」「家庭」「国家」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「家」條；香港中文大學《漢語多功能字庫》「家」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%B6（2026-11-03 查閱）"},
  "10169_对_Z_小篆": {"headline": "「对」本来是开荒立界，后来表示应答、相对。", "original_meaning": "「对」（對）的本义是开辟土地、树立地界，后来表示应答、相对。", "structure_desc": "「对」的繁体字是「對」。古人开荒后要树立地界，地界多半用植树来标记，所以「对」的本义是开辟土地、立下地界。后来「对」被借用来表示应答、相对的意思，比如「回答」「对手」「对错」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𡭊」條（今字作「對」）；香港中文大學《漢語多功能字庫》「對」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%8D（2026-11-03 查閱）"},
  "10191_小_Z_說文‧小部": {"headline": "「小」就是用几个小点点表示细小。", "original_meaning": "「小」指体积、面积、数量等不大，和「大」相对。", "structure_desc": "关于「小」字的来历有两种说法：一种认为用三个小点来表示事物很微小；另一种认为「小」是「沙」的本字，用细小的沙粒来表示微小。不管哪种说法，「小」的本义就是微小、不大，比如「小孩」「小心」「大小」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「小」條；香港中文大學《漢語多功能字庫》「小」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%8F（2026-11-03 查閱）"},
  "10225_就_Z_說文‧京部": {"headline": "「就」就是到高处去祭祀。", "original_meaning": "「就」的本义是到高处去、靠近，引申为成就、完成。", "structure_desc": "甲骨文和金文的「就」字，上面是宗庙建筑，下面是高台，合起来表示到高台上祭祀的意思。本义是靠近、去到某处。后来引申出「成就」「完成」「就是」等意思，比如「成就」「就是」「就业」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「就」條；香港中文大學《漢語多功能字庫》「就」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%B1（2026-11-03 查閱）"},
  "10261_展_Z_說文‧尸部": {"headline": "「展」就是人躺在床上翻来覆去。", "original_meaning": "「展」的本义是辗转、转动，引申为展开、舒展。", "structure_desc": "「展」从「尸」（表示人），本义是人躺在床上翻来覆去。因为人躺着的时候四肢会舒展开，所以「展」引申出「展开」「舒展」「展示」等意思，比如「展开」「展览」「发展」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「展」條；香港中文大學《漢語多功能字庫》「展」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B1%95（2026-11-03 查閱）"},
  "10661_工_Z_說文‧工部": {"headline": "「工」画的是古代的曲尺和工具。", "original_meaning": "「工」的本义是工匠、工具，引申为精巧、工作。", "structure_desc": "甲骨文和金文的「工」字，画的是一种工具，上面像曲尺（用来画直角的工具），下面像斧刃。本义就是工匠用的工具。后来引申出「工匠」「工作」「精巧」等意思，比如「工人」「工作」「工巧」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「工」條；香港中文大學《漢語多功能字庫》「工」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%A5（2026-11-03 查閱）"},
  "10673_己_Z_說文‧己部": {"headline": "「己」本来画的是捆东西的绳子。", "original_meaning": "「己」本来指用来捆绑的绳子，后来表示自己。", "structure_desc": "甲骨文和金文的「己」字，画的是一根弯弯曲曲的绳子，本义是用来捆绑东西的绳子，是「纪」的本字。后来「己」被借用来表示「自己」「自身」的意思，也用作天干第六位。比如「自己」「知己」「舍己为人」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「己」條；香港中文大學《漢語多功能字庫》「己」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%B1（2026-11-03 查閱）"},
  "10674_已_Z_小篆": {"headline": "「已」本来和「巳」是同一个字。", "original_meaning": "「已」表示停止、完毕，也作虚词。", "structure_desc": "古文字里「已」和「巳」原本是同一个字，后来才分开。「已」多用作虚词，表示「停止」「完毕」「已经」等意思，比如「已经」「而已」「不能自已」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「巳」條（今字作「已」）；香港中文大學《漢語多功能字庫》「已」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%B2（2026-11-03 查閱）"},
  "10690_市_Z_說文‧冂部": {"headline": "「市」就是吵吵闹闹的集市。", "original_meaning": "「市」指集市、市场，就是做买卖的地方。", "structure_desc": "甲骨文和金文的「市」字，有学者认为其中的「兮」表示喧闹的声音，合起来表示市场里吵吵闹闹做买卖的情景。本义就是集市、市场。后来引申出「城市」「买」等意思，比如「市场」「城市」「市恩」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「市」條；香港中文大學《漢語多功能字庫》「市」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B8%82（2026-11-03 查閱）"},
  "10803_平_Z_說文‧于部": {"headline": "「平」就是呼吸平稳、不颠簸。", "original_meaning": "「平」的本义是平稳、不倾斜。", "structure_desc": "「平」字上面是表示呼气的部分，下面一横表示平稳的状态。本义是气平稳、不颠簸。后来引申出「平坦」「公平」「和平」等意思，比如「平地」「公平」「平安」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「平」條；香港中文大學《漢語多功能字庫》「平」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B9%B3（2026-11-03 查閱）"},
  "10804_年_Z_說文‧禾部": {"headline": "「年」就是人背着收割的庄稼，丰收了就是一年。", "original_meaning": "「年」的本义是谷物成熟、丰收。", "structure_desc": "甲骨文的「年」字，画的是一个人背着一捆收割好的庄稼，表示谷物成熟丰收的意思。古时候人们以谷物成熟一次为一年，所以「年」就有了年岁的意思。比如「今年」「过年」「年年有余」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「年」條；香港中文大學《漢語多功能字庫》「年」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B9%B4（2026-11-03 查閱）"},
  "10836_应_Z_小篆": {"headline": "「应」就是心里觉得该做的事。", "original_meaning": "「应」（應）的本义是应当、应该。", "structure_desc": "「应」的繁体字是「應」，从「心」，表示心里的判断。本义是应当、应该，就是心里觉得该怎么做。后来也表示应答、回应，比如「应该」「答应」「反应」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「應」條；香港中文大學《漢語多功能字庫》「應」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%87%89（2026-11-03 查閱）"},
  "10854_度_Z_說文‧又部": {"headline": "「度」就是用手来量长短。", "original_meaning": "「度」的本义是量长短的标准，引申为制度、程度。", "structure_desc": "「度」从「又」（手），表示用手来量度长短。本义是计量长短的标准。后来引申出「制度」「程度」「气度」等意思，比如「尺度」「制度」「态度」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「度」條；香港中文大學《漢語多功能字庫》「度」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BA%A6（2026-11-03 查閱）"},
  "10938_建_Z_說文‧廴部": {"headline": "「建」就是用手把柱子立起来。", "original_meaning": "「建」的本义是树立、建立。", "structure_desc": "甲骨文和金文的「建」字，是一只手拿着一根木柱，把它竖立起来的样子。本义是树立、建立。后来引申出「建设」「建造」「建议」等意思，比如「建立」「建设」「建言」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「建」條；香港中文大學《漢語多功能字庫》「建」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BB%BA（2026-11-03 查閱）"},
  "10944_开_Z_小篆": {"headline": "「开」就是用两只手把门闩拿掉。", "original_meaning": "「开」（開）的本义是开门、打开。", "structure_desc": "「开」的繁体字是「開」，金文的字形是两只手把门上的横木（门闩）拿掉，把门打开的样子。本义是开门、打开。后来引申出「开始」「开放」「开发」等意思，比如「开门」「开始」「开心」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「開」條；香港中文大學《漢語多功能字庫》「開」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%96%8B（2026-11-03 查閱）"},
  "11027_当_Z_小篆": {"headline": "「当」就是两块田地对等、相当。", "original_meaning": "「当」（當）的本义是相对、相当。", "structure_desc": "「当」的繁体字是「當」，从「田」，「尚」表音。本义是两块田地相对、面积相当。后来引申出「应当」「对着」「担任」等意思，比如「应当」「当面」「担当」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「當」條；香港中文大學《漢語多功能字庫》「當」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%95%B6（2026-11-03 查閱）"},
  "11080_很_Z_說文‧彳部": {"headline": "「很」本来是不听劝、对着干。", "original_meaning": "「很」的本义是违逆、不听从，后来表示程度深。", "structure_desc": "「很」从「彳」（表示行走），「艮」表音。本义是违逆、不听从，就是别人说什么都不听，对着干。后来「很」被借用来表示程度深，相当于「非常」，比如「很好」「很快」「很多」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「很」條；香港中文大學《漢語多功能字庫》「很」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%88（2026-11-03 查閱）"},
  "11095_得_Z_說文‧彳部": {"headline": "「得」就是在路上捡到宝贝。", "original_meaning": "「得」的本义是得到、获得。", "structure_desc": "甲骨文和金文的「得」字，是一只手拿着贝（古代的钱币），有的还加了表示道路的「彳」，合起来表示在路上捡到了宝贝。本义是得到、获得。后来引申出「得到」「得失」「得意」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「得」條；香港中文大學《漢語多功能字庫》「得」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%97（2026-11-03 查閱）"},
  "11139_心_Z_說文‧心部": {"headline": "「心」画的就是人的心脏。", "original_meaning": "「心」指人的心脏，也指思想、情感。", "structure_desc": "甲骨文和金文的「心」字，画的就是人的心脏的形状，外面是心包，里面是心房心室。古人认为心是管思想的，所以「心」也指心思、情感，比如「心情」「心思」「用心」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「心」條；香港中文大學《漢語多功能字庫》「心」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%83（2026-11-03 查閱）"},
  "11179_快_Z_說文‧心部": {"headline": "「快」就是心里高兴、美滋滋。", "original_meaning": "「快」的本义是喜悦、高兴，后来表示速度快。", "structure_desc": "「快」从「心」，「夬」表音。本义是心里高兴、畅快。后来「快」引申出「速度快」的意思，因为心里畅快的时候做事也会特别带劲。比如「快乐」「快速」「快点」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「快」條；香港中文大學《漢語多功能字庫》「快」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%AB（2026-11-03 查閱）"},
  "11239_性_Z_說文‧心部": {"headline": "「性」就是人天生的本性。", "original_meaning": "「性」的本义是天性、本性。", "structure_desc": "「性」从「心」，「生」表音。本义是人的天性、本性，就是人生下来就有的特质。古人认为人天生有善良的本性。后来「性」也指事物的性质、特点，比如「本性」「性格」「性质」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「性」條；香港中文大學《漢語多功能字庫》「性」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%80%A7（2026-11-03 查閱）"},
  "11397_情_Z_說文‧心部": {"headline": "「情」就是人心里的喜怒哀乐。", "original_meaning": "「情」的本义是感情、情绪。", "structure_desc": "「情」从「心」，「青」表音。本义是人的感情、情绪，就是人心里产生的喜怒哀乐。古人说，本性的好坏、喜怒、哀乐就叫做情。比如「感情」「心情」「爱情」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「情」條；香港中文大學《漢語多功能字庫》「情」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%83%85（2026-11-03 查閱）"},
  "11443_想_Z_說文‧心部": {"headline": "「想」就是在心里动脑筋琢磨。", "original_meaning": "「想」的本义是思考、思索。", "structure_desc": "「想」从「心」，「相」表音。本义是在心里思考、琢磨。后来引申出「希望」「想念」等意思，比如「想法」「想念」「理想」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「想」條；香港中文大學《漢語多功能字庫》「想」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%83%B3（2026-11-03 查閱）"},
  "11471_意_Z_說文‧心部": {"headline": "「意」就是话里透出来的心思。", "original_meaning": "「意」的本义是心思、意思。", "structure_desc": "「意」从「心」从「音」，表示从声音或言语里看出来的心思。本义是心意、意思。后来引申出「意愿」「意料」「意思」等意思，比如「意思」「心意」「意料」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「意」條；香港中文大學《漢語多功能字庫》「意」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%84%8F（2026-11-03 查閱）"},
  "11728_成_Z_說文‧戊部": {"headline": "「成」就是拿着武器守住城池。", "original_meaning": "「成」的本义是完成、成功。", "structure_desc": "甲骨文的「成」字，是一把斧头（戌）和一座城邑（囗）的组合，表示用武器守卫城池。有学者认为「成」本来是「城」的本字。后来「成」引申出「完成」「成功」「成就」等意思，比如「成功」「完成」「成就」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「成」條；香港中文大學《漢語多功能字庫》「成」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%90（2026-11-03 查閱）"},
  "11729_我_Z_說文‧我部": {"headline": "「我」本来是一把带锯齿的兵器。", "original_meaning": "「我」本来是一种兵器，后来借来表示自己。", "structure_desc": "甲骨文和金文的「我」字，画的是一把带锯齿的长柄兵器，本义是一种类似锯的武器。后来被借用作第一人称代词，表示自己。比如「我们」「自我」「我行我素」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「我」條；香港中文大學《漢語多功能字庫》「我」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%91（2026-11-03 查閱）"},
  "11776_所_Z_說文‧斤部": {"headline": "「所」就是拿着斧头守在门口。", "original_meaning": "「所」的本义是处所、地方。", "structure_desc": "「所」从「户」（一扇门）从「斤」（斧头），有学者认为是拿着斧头守在门口的意思。本义是处所、地方。后来「所」虚化为助词，用在动词前面，比如「所以」「所有」「无所不在」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「所」條；香港中文大學《漢語多功能字庫》「所」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%80（2026-11-03 查閱）"},
  "11787_手_Z_說文‧手部": {"headline": "「手」画的是有五根手指的手掌。", "original_meaning": "「手」就是人的手。", "structure_desc": "甲骨文里「手」一般写作「又」，只画了三根手指。后来「又」被借用作连词，人们就另造了「手」字。金文的「手」字画了五根手指，连着手腕。「手」是汉字里最重要的部件之一，很多和动作有关的字都带「手」字旁。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「手」條；香港中文大學《漢語多功能字庫》「手」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%8B（2026-11-03 查閱）"},
  "11850_把_Z_說文‧手部": {"headline": "「把」就是用手抓住东西。", "original_meaning": "「把」的本义是握持、抓住。", "structure_desc": "「把」从「手」，「巴」表音。本义是用手握住、抓住。后来引申出量词用法（一把刀）和介词用法（把门打开）等。比如「把握」「把门」「一把刀」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「把」條；香港中文大學《漢語多功能字庫》「把」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8A%8A（2026-11-03 查閱）"},
  "12176_提_Z_說文‧手部": {"headline": "「提」就是用手把东西拎起来。", "original_meaning": "「提」的本义是悬持、拎起。", "structure_desc": "「提」从「手」，「是」表音。本义是用手把东西拎起来、悬空拿着。后来引申出「提起」「提出」「提醒」等意思，比如「提水」「提问」「提升」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「提」條；香港中文大學《漢語多功能字庫》「提」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8F%90（2026-11-03 查閱）"},
  "12543_政_Z_說文‧攴部": {"headline": "「政」就是拿着棍棒去打仗。", "original_meaning": "「政」的本义是征伐，后来表示政治。", "structure_desc": "「政」从「攴」（手持棍棒），「正」表音。「正」是「征」的本字，表示脚朝着目标前进。合起来就是拿着棍棒去征伐的意思。后来「政」引申出「政治」「政务」等意思，比如「政治」「政府」「政策」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「政」條；香港中文大學《漢語多功能字庫》「政」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%94%BF（2026-11-03 查閱）"},
  "12569_教_Z_說文‧教部": {"headline": "「教」就是拿着教鞭教孩子算数。", "original_meaning": "「教」的本义是教导、教育。", "structure_desc": "甲骨文的「教」字，左边是一个孩子（子），右边是一只手拿着教鞭（攴），中间是算筹（爻）。合起来就是老师拿着教鞭，教孩子摆弄算筹学算术的样子。本义就是教导。古人说「教学相长」，就是教和学互相促进。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「敎」條（今字作「教」）；香港中文大學《漢語多功能字庫》「教」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%95%99（2026-11-03 查閱）"},
  "12615_文_Z_說文‧文部": {"headline": "「文」就是人身上画的花纹。", "original_meaning": "「文」的本义是纹身、花纹，后来指文字。", "structure_desc": "甲骨文和金文的「文」字，画的是一个站立的人，胸前画着花纹。本义是纹身、花纹。后来人们用花纹来记录事情，「文」就有了文字的意思。比如「文字」「文章」「文化」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「文」條；香港中文大學《漢語多功能字庫》「文」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%87（2026-11-03 查閱）"},
  "12656_新_Z_說文‧斤部": {"headline": "「新」就是用斧头砍木头取柴。", "original_meaning": "「新」的本义是砍柴，引申为新旧的新。", "structure_desc": "「新」从「斤」（斧头）从「木」，表示用斧头砍木头取柴。因为刚砍下来的柴火是新鲜的，所以「新」引申出「新旧」的「新」。比如「新鲜」「新年」「创新」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「新」條；香港中文大學《漢語多功能字庫》「新」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%B0（2026-11-03 查閱）"},
  "12665_方_Z_說文‧方部": {"headline": "「方」就是用一横指出刀的锋芒。", "original_meaning": "「方」的本义是刀的锋芒，后来表示方形、方向。", "structure_desc": "甲骨文和金文的「方」字，是一把刀，加一横指出刀的锋芒。本义是刀的锋芒。因为表示方形的「□」容易和别的字混，古人就借用「方」来表示方形、方向。比如「方向」「方面」「方法」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「方」條；香港中文大學《漢語多功能字庫》「方」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%B9（2026-11-03 查閱）"},
  "12704_无_Z_說文‧亡部": {"headline": "「无」画的是人拿着牛尾跳舞。", "original_meaning": "「无」的本义是跳舞，后来借来表示没有。", "structure_desc": "甲骨文的「无」字，画的是一个人手里拿着牛尾一类的饰物在跳舞。后来这个字被借用来表示「有没有」的「无」，就不再表示跳舞了。比如「无穷」「无限」「无中生有」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𣞤」條（今字作「無」）；香港中文大學《漢語多功能字庫》「無」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%84%A1（2026-11-03 查閱）"},
  "12709_日_Z_說文‧日部": {"headline": "「日」画的就是太阳。", "original_meaning": "「日」的本义是太阳，也指一天。", "structure_desc": "「日」是个象形字，画的是太阳的样子。最早是圆形的，因为圆形在甲骨上不好刻，就变成了方形。中间加一点，避免和表示框框的「囗」混淆。「日」是汉字里最重要的部件之一，很多和时间、光明有关的字都带「日」字旁。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「日」條；香港中文大學《漢語多功能字庫》「日」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%97%A5（2026-11-03 查閱）"},
  "12726_时_Z_小篆": {"headline": "「时」就是跟着太阳走的时间。", "original_meaning": "「时」的本义是时间、时节。", "structure_desc": "「时」的繁体是「時」，从「日」（太阳），「寺」表音。古人看太阳的位置来判断时间，所以「时」从「日」。本义是时间、时节。比如「时间」「时候」「四时」（春夏秋冬）。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「時」條；香港中文大學《漢語多功能字庫》「時」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%99%82（2026-11-03 查閱）"},
  "12750_明_Z_說文‧明部": {"headline": "「明」就是太阳和月亮都在发光。", "original_meaning": "「明」的本义是明亮、光明。", "structure_desc": "甲骨文的「明」字，一边是「日」（太阳），一边是「月」（月亮），合起来表示日月交辉、非常明亮的意思。也有一种写法是月光透过窗户照进屋里。本义是明亮。后来引申出「明白」「聪明」等意思，比如「光明」「明白」「聪明」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「朙」條（今字作「明」）；香港中文大學《漢語多功能字庫》「明」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%8E（2026-11-03 查閱）"},
  "12783_是_Z_說文‧是部": {"headline": "「是」就是对着太阳站得正。", "original_meaning": "「是」的本义是正直、正确，后来表示判断。", "structure_desc": "「是」从「日」（太阳）从「正」（端正），表示对着太阳站得端正。本义是正直、正确。后来「是」被用作判断词，相当于「就是」的意思。比如「是非」「是的」「可是」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「是」條；香港中文大學《漢語多功能字庫》「是」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%AF（2026-11-03 查閱）"},
  "12992_最_Z_說文‧冃部": {"headline": "「最」就是冒犯着去夺取。", "original_meaning": "「最」的本义是冒犯而取，引申为极、顶。", "structure_desc": "「最」从「冃」（帽子，引申为冒犯）从「取」，表示冒着风险去夺取。后来「最」虚化为副词，表示程度达到顶点，相当于「极」「顶」。比如「最好」「最大」「最终」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「最」條；香港中文大學《漢語多功能字庫》「最」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%80（2026-11-03 查閱）"},
  "13000_月_Z_說文‧月部": {"headline": "「月」画的是弯弯的月牙。", "original_meaning": "「月」的本义是月亮，也指月份。", "structure_desc": "「月」是个象形字，画的是弯弯的月亮（半月形）。因为月亮有圆缺变化的周期，古人就用「月」来记时间，一个月就是月亮圆缺一次。「月」也是汉字里重要的部件，很多和身体有关的字都带「月」字旁（其实是「肉」字旁的变形）。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「月」條；香港中文大學《漢語多功能字庫》「月」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%88（2026-11-03 查閱）"},
  "13001_有_Z_說文‧有部": {"headline": "「有」就是手里拿着一块肉。", "original_meaning": "「有」的本义是持有、拥有。", "structure_desc": "金文的「有」字，上面是「又」（手），下面是「肉」，合起来就是手里拿着一块肉。古时候肉很珍贵，手里有肉就表示拥有东西。后来「有」就成了「没有」的反义词。比如「拥有」「富有」「有备无患」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「有」條；香港中文大學《漢語多功能字庫》「有」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%89（2026-11-03 查閱）"},
  "13036_本_Z_說文‧木部": {"headline": "「本」就是树木的根部。", "original_meaning": "「本」的本义是草木的根，引申为根本。", "structure_desc": "「本」在「木」字的下方加一横，指出树木的根部所在。本义是草木的根。因为根是树木生长的基础，所以「本」引申出「根本」「本来」等意思。比如「根本」「本来」「忘本」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「本」條；香港中文大學《漢語多功能字庫》「本」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%AC（2026-11-03 查閱）"},
  "13050_机_Z_說文‧木部": {"headline": "「机」就是弩上发箭的机关。", "original_meaning": "「机」的本义是弩机，引申为机关、机会。", "structure_desc": "「机」的繁体是「機」，从「木」，「几」表音。本义是弩机，就是古代弩上用来发射箭的装置。因为弩机是整个弩最关键的部分，一触动就会发射，所以「机」引申出「机关」「机会」「机器」等意思。比如「机会」「机器」「时机」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「機」條；香港中文大學《漢語多功能字庫》「機」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A9%9F（2026-11-03 查閱）"},
  "13093_来_Z_小篆": {"headline": "「来」本来是一棵麦子。", "original_meaning": "「来」的本义是麦子，后来借来表示到来。", "structure_desc": "甲骨文的「来」字画的是一棵麦子：中间是直直的麦穗，两边叶子下垂，下面是茎和根。本来「来」就是麦子的意思，后来被借用来表示「到来」的「来」，用久了就不还了，人们就另造了「麦」字表示麦子。比如「来到」「回来」「未来」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「來」條；香港中文大學《漢語多功能字庫》「來」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BE%86（2026-11-03 查閱）"},
  "13303_样_Z_小篆": {"headline": "「样」本来是橡树的果实。", "original_meaning": "「样」的本义是栎树的果实，后来表示样式。", "structure_desc": "「样」的繁体是「樣」，从「木」，「羕」表音。本义是栎树（橡树）的果实。后来人们用「橡」字来表示橡树的果实，「样」就专门用来表示「样式」「样子」的意思了。比如「样子」「样品」「榜样」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「樣」條；香港中文大學《漢語多功能字庫》「樣」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A8%A3（2026-11-03 查閱）"},
  "14049_次_Z_說文‧欠部": {"headline": "「次」就是人说话时溅出的口水。", "original_meaning": "「次」的本义是商议、咨询，后来表示次序、第二。", "structure_desc": "金文的「次」字，左边是「欠」（一个张着嘴的人），旁边两点像说话时溅出的口水。本义是商议、咨询（是「咨」的本字）。后来「次」引申出「次序」「第二」等意思，比如「名次」「其次」「次日」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「次」條；香港中文大學《漢語多功能字庫》「次」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AC%A1（2026-11-03 查閱）"},
  "14115_正_Z_說文‧正部": {"headline": "「正」就是脚朝着目标前进。", "original_meaning": "「正」的本义是远行，引申为端正、正确。", "structure_desc": "甲骨文和金文的「正」字，上面是「止」（脚），下面是「丁」（表示目标或城邑），合起来就是脚朝着目标前进的意思。「正」是「征」的本字。后来「正」引申出「端正」「正确」等意思，比如「正好」「正确」「正直」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「正」條；香港中文大學《漢語多功能字庫》「正」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AD%A3（2026-11-03 查閱）"},
  "14228_比_Z_說文‧比部": {"headline": "「比」就是两个人并排站着。", "original_meaning": "「比」的本义是并列、挨着，引申为比较。", "structure_desc": "甲骨文和金文的「比」字，画的是两个人并排站着，挨得很近。本义是并列、挨着。因为两个人挨在一起就容易比较，所以「比」引申出「比较」「比方」等意思。比如「比较」「对比」「比如」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「比」條；香港中文大學《漢語多功能字庫》「比」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AF%94（2026-11-03 查閱）"},
  "14289_民_Z_說文‧民部": {"headline": "「民」就是被刺瞎眼睛的奴隶。", "original_meaning": "「民」的本义是奴隶，后来指老百姓。", "structure_desc": "甲骨文和金文的「民」字，左边是「目」（眼睛），右边像一把利器刺向眼睛。本义是奴隶，因为古代奴隶主会刺瞎奴隶的眼睛来防止他们逃跑。后来「民」引申为普通百姓的意思，比如「人民」「民众」「民生」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「民」條；香港中文大學《漢語多功能字庫》「民」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B0%91（2026-11-03 查閱）"},
  "14324_水_Z_說文‧水部": {"headline": "「水」画的是流动的水流。", "original_meaning": "「水」就是水，也作偏旁。", "structure_desc": "「水」是个象形字，中间一竖表示水流，两边的点表示水滴。本义就是水。「水」是汉字里最重要的部件之一，很多和液体、河流有关的字都带「水」字旁（三点水）。比如「江河」「海洋」「喝水」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「水」條；香港中文大學《漢語多功能字庫》「水」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B0%B4（2026-11-03 查閱）"},
  "14433_没_Z_說文‧水部": {"headline": "「没」就是沉入水中看不见了。", "original_meaning": "「没」的本义是沉没，引申为没有。", "structure_desc": "「没」的繁体是「沒」，从「水」，右边表示沉入。本义是沉入水中。东西沉入水里就看不见了，所以「没」引申出「没有」的意思。比如「淹没」「没有」「没落」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「沒」條；香港中文大學《漢語多功能字庫》「沒」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B2%92（2026-11-03 查閱）"},
  "14485_法_Z_說文‧廌部": {"headline": "「法」就是像水一样公平的审判。", "original_meaning": "「法」的本义是法律、刑罚。", "structure_desc": "「法」的古字写作「灋」，从「水」（表示公平如水）从「廌」（一种神兽，会用角去顶无理的一方）从「去」（去除不公）。合起来就是审判要像水一样公平，让神兽去除无理的人。后来简化成「法」。比如「法律」「方法」「效法」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「灋」條（今字作「法」）；香港中文大學《漢語多功能字庫》「法」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B3%95（2026-11-03 查閱）"},
  "15481_点_Z_小篆": {"headline": "「点」就是一个小黑斑。", "original_meaning": "「点」的本义是细小的黑色斑痕。", "structure_desc": "「点」的繁体是「點」，从「黑」，「占」表音。本义是细小的黑色斑痕。后来「点」引申出很多意思，比如「点心」「点滴」「点燃」「标点」等。比如「雨点」「点头」「点灯」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「點」條；香港中文大學《漢語多功能字庫》「點」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%BB%9E（2026-11-03 查閱）"},
  "15606_然_Z_說文‧火部": {"headline": "「然」就是在火上烤狗肉。", "original_meaning": "「然」的本义是燃烧，后来作虚词。", "structure_desc": "「然」上面是「肰」（狗肉），下面是「火」，合起来就是在火上烤狗肉的意思。本义是燃烧。后来「然」被借用作虚词（表示「这样」「然而」等），人们就另造了「燃」字表示燃烧。比如「然后」「然而」「自然」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「然」條；香港中文大學《漢語多功能字庫》「然」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%84%B6（2026-11-03 查閱）"},
  "16326_理_Z_說文‧玉部": {"headline": "「理」就是顺着玉的纹路来雕琢。", "original_meaning": "「理」的本义是治玉、雕琢玉石。", "structure_desc": "「理」从「玉」，「里」表音。本义是顺着玉的纹理来雕琢玉石。因为雕琢玉石要顺着纹路，所以「理」引申出「道理」「治理」「整理」等意思。比如「道理」「治理」「整理」「理由」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「理」條；香港中文大學《漢語多功能字庫》「理」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%90%86（2026-11-03 查閱）"},
  "16607_生_Z_說文‧生部": {"headline": "「生」就是一棵草从泥土里长出来。", "original_meaning": "「生」的本义是生长、出生。", "structure_desc": "甲骨文的「生」字，下面一横是土地，上面是一棵小草（屮）从土里钻出来。本义是生长、出生。后来引申出「生命」「生活」「产生」等意思。比如「生长」「生命」「生产」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「生」條；香港中文大學《漢語多功能字庫》「生」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%9F（2026-11-03 查閱）"},
  "16616_用_Z_說文‧用部": {"headline": "「用」本来是一只木桶。", "original_meaning": "「用」的本义是木桶，后来表示使用。", "structure_desc": "甲骨文的「用」字画的是一只木桶，左边是桶身，右边是把手。本义是木桶。后来「用」被借用来表示「使用」「施行」的意思，用久了就不还了。比如「使用」「作用」「有用」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「用」條；香港中文大學《漢語多功能字庫》「用」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%A8（2026-11-03 查閱）"},
  "16964_的_Z_小篆": {"headline": "「的」就是太阳照得很明亮。", "original_meaning": "「的」的本义是明亮，后来作助词。", "structure_desc": "「的」本作「旳」，从「日」（太阳），「勺」表音。本义是明亮。后来「的」被借用作助词，用在定语和中心语之间，比如「我的书」「红色的花」。这是现代汉语里用得最多的字之一。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「旳」條（今字作「的」）；香港中文大學《漢語多功能字庫》「的」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9A%84（2026-11-03 查閱）"},
  "17099_看_Z_說文‧目部": {"headline": "「看」就是把手搭在眼睛上远望。", "original_meaning": "「看」的本义是用眼睛看东西。", "structure_desc": "「看」从「手」从「目」，像一个人把手搭在眼睛上面，遮住阳光往远处看的样子。本义就是用眼睛看东西。比如「看见」「看书」「看病」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「看」條；香港中文大學《漢語多功能字庫》「看」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9C%8B（2026-11-03 查閱）"},
  "17119_真_Z_說文‧𠤎部": {"headline": "「真」就是货真价实的贝币。", "original_meaning": "「真」的本义是真实、不虚假。", "structure_desc": "金文的「真」字从「贝」（古代用贝做货币），「𠂈」表音。贝是真正的钱，所以「真」有真实的意思。《说文解字》认为「真」是仙人登天的样子，但学者多认为本义和「贝」有关。后来「真」表示「真实」「真正」，和「假」相对。比如「真实」「真正」「真心」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「眞」條（今字作「真」）；香港中文大學《漢語多功能字庫》「真」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9C%9F（2026-11-03 查閱）"},
  "17152_着_Z_小篆": {"headline": "「着」就是明显地露出来。", "original_meaning": "「着」的本义是明显、显著。", "structure_desc": "「着」本作「著」，从「艸」（草），「者」表音。本义是明显、显著。后来「着」分化出来，表示「附着」「穿着」「着落」等意思，也作动态助词，比如「看着」「走着」。比如「穿着」「着急」「看着」。", "source": "香港中文大學《漢語多功能字庫》「著」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%91%97（2026-11-03 查閱）"},
  "17317_知_Z_說文‧矢部": {"headline": "「知」就是说话像箭一样快准。", "original_meaning": "「知」的本义是知道、懂得。", "structure_desc": "「知」从「矢」（箭）从「口」，表示说话像箭一样又快又准，一矢中的。本义是知道、懂得。因为知道了才能说得准、说得快。比如「知道」「知识」「通知」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「知」條；香港中文大學《漢語多功能字庫》「知」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9F%A5（2026-11-03 查閱）"},
  "17662_社_Z_說文‧示部": {"headline": "「社」就是祭祀土地神的地方。", "original_meaning": "「社」的本义是土地之神，也指祭祀土地神的地方。", "structure_desc": "「社」从「示」（表示祭祀）从「土」（土地），合起来就是祭祀土地神的意思。古人相信土地神能保佑庄稼丰收，所以会立社祭祀。后来「社」引申出「社会」「社团」等意思。比如「社会」「社团」「报社」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「社」條；香港中文大學《漢語多功能字庫》「社」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A4%BE（2026-11-03 查閱）"},
  "17805_种_Z_小篆": {"headline": "「种」就是禾苗的种子。", "original_meaning": "「种」的本义是植物的种子，也指种植。", "structure_desc": "「种」的繁体是「種」，从「禾」（禾苗），「重」表音。本义是植物的种子。因为种子可以种下去长出新的植物，所以「种」也表示「种植」的意思。比如「种子」「种地」「种类」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「種」條；香港中文大學《漢語多功能字庫》「種」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A8%AE（2026-11-03 查閱）"},
  "18185_等_Z_說文‧竹部": {"headline": "「等」就是把竹简整理得整整齐齐。", "original_meaning": "「等」的本义是整齐竹简，引申为等级、等同。", "structure_desc": "「等」从「竹」（竹简）从「寺」（古代的官府），表示在官府里把竹简整理得整整齐齐。本义是整齐、等同。因为竹简是按顺序排列的，所以「等」引申出「等级」「等待」等意思。比如「等级」「等待」「等于」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「等」條；香港中文大學《漢語多功能字庫》「等」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AD%89（2026-11-03 查閱）"},
  "18247_箇_Z_說文‧竹部": {"headline": "「箇」就是一根竹枝。", "original_meaning": "「箇」的本义是竹枝，后来作量词。", "structure_desc": "「箇」从「竹」，「固」表音。本义是竹枝。后来「箇」被借用作量词，相当于「个」。现在简化字写作「个」。比如「一个人」「两个苹果」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「箇」條；香港中文大學《漢語多功能字庫》「箇」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AE%87（2026-11-03 查閱）"},
  "19087_经_Z_小篆": {"headline": "「经」就是织布机上的竖线。", "original_meaning": "「经」的本义是织布的经线，引申为经过、经典。", "structure_desc": "「经」的繁体是「經」，从「糸」（丝线），「巠」表音。「巠」像织布机上纵向的经线，和横向的纬线相对。本义是织布的经线。因为经线是贯穿整匹布的主线，所以「经」引申出「经过」「经历」「经典」等意思。比如「经过」「经历」「经典」「经常」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「經」條；香港中文大學《漢語多功能字庫》「經」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B6%93（2026-11-03 查閱）"},
  "19091_结_Z_小篆": {"headline": "「结」就是把绳子系在一起。", "original_meaning": "「结」的本义是打结、系结。", "structure_desc": "「结」的繁体是「結」，从「糸」（丝线），「吉」表音。本义是把绳子系在一起、打结。后来「结」引申出「结合」「结果」「结束」等意思。比如「打结」「结合」「结果」「结束」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「結」條；香港中文大學《漢語多功能字庫》「結」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B5%90（2026-11-03 查閱）"},
  "19097_给_Z_小篆": {"headline": "「给」就是丝线充足、丰衣足食。", "original_meaning": "「给」的本义是丰足、充裕，引申为给予。", "structure_desc": "「给」的繁体是「給」，从「糸」（丝线），「合」表音。本义是丰足、充裕。丝线充足就不愁穿，所以「给」有丰足的意思。后来「给」引申出「给予」「供给」等意思。比如「给予」「供给」「给以」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「給」條；香港中文大學《漢語多功能字庫》「給」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B5%A6（2026-11-03 查閱）"},
  "19278_美_Z_說文‧羊部": {"headline": "「美」就是人头上戴着漂亮的角饰。", "original_meaning": "「美」的本义是漂亮、好看。", "structure_desc": "甲骨文的「美」字，下面是「大」（一个人），上面像头上戴着羽毛或羊角之类的装饰物。本义是漂亮、好看。古人喜欢把动物的角戴在头上做装饰，觉得这样很美。比如「美丽」「美好」「美味」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「美」條；香港中文大學《漢語多功能字庫》「美」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BE%8E（2026-11-03 查閱）"},
  "19393_老_Z_說文‧老部": {"headline": "「老」就是驼背长发、拄着拐杖的老人。", "original_meaning": "「老」的本义是年老、老人。", "structure_desc": "甲骨文的「老」字，画的是一个驼背、长头发、手里拄着拐杖的老人。本义就是年老、老人。因为老人经验丰富，所以「老」也表示「老练」「陈旧」等意思。比如「老人」「老年」「老练」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「老」條；香港中文大學《漢語多功能字庫》「老」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%81（2026-11-03 查閱）"},
  "19397_者_Z_說文‧𦣹部": {"headline": "「者」是一个指代名词，本义不太清楚。", "original_meaning": "「者」的本义不明，常用作代词、助词。", "structure_desc": "「者」字的构形本义，学者们还没有定论。金文的「者」从「木」从几点从「口」，可能和祭祀或陈列有关。后来「者」被用作代词和助词，比如「作者」「读者」「或者」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「者」條；香港中文大學《漢語多功能字庫》「者」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%85（2026-11-03 查閱）"},
  "19404_而_Z_說文‧而部": {"headline": "「而」就是下巴上的胡子。", "original_meaning": "「而」的本义是颊毛、胡须，后来作连词。", "structure_desc": "「而」字像下巴上的胡须，上面加一短横是装饰笔。本义是胡须。后来「而」被借用作连词，表示「而且」「然而」等意思，人们就另造了字来表示胡须。比如「而且」「然而」「因而」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「而」條；香港中文大學《漢語多功能字庫》「而」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%8C（2026-11-03 查閱）"},
  "19645_能_Z_說文‧能部": {"headline": "「能」本来是一只大熊。", "original_meaning": "「能」的本义是熊，引申为能力、能够。", "structure_desc": "「能」字本来画的是一只熊，是「熊」的本字。因为熊很有力气，所以「能」引申出「能力」「能够」的意思。后来人们另造了「熊」字表示动物，「能」就专门表示能力了。比如「能力」「能够」「才能」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「能」條；香港中文大學《漢語多功能字庫》「能」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%83%BD（2026-11-03 查閱）"},
  "19882_自_Z_說文‧自部": {"headline": "「自」就是一只鼻子。", "original_meaning": "「自」的本义是鼻子，后来表示自己。", "structure_desc": "甲骨文和金文的「自」字，画的是一只鼻子，中间两横像鼻子上的皱纹。本义是鼻子。后来人们说「我自己」的时候，习惯用手指着自己的鼻子，所以「自」就引申出「自己」的意思。比如「自己」「自然」「自由」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「自」條；香港中文大學《漢語多功能字庫》「自」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%87%AA（2026-11-03 查閱）"},
  "21516_行_Z_說文‧行部": {"headline": "「行」就是四通八达的十字路口。", "original_meaning": "「行」的本义是道路，引申为行走。", "structure_desc": "甲骨文和金文的「行」字，画的是一个四通八达的十字路口。本义是道路。因为路是人走出来的，所以「行」引申出「行走」的意思。「行」作偏旁时常常写作「彳」，很多和走路有关的字都带「彳」。比如「行走」「行动」「旅行」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「行」條；香港中文大學《漢語多功能字庫》「行」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A1%8C（2026-11-03 查閱）"},
  "21544_表_Z_說文‧衣部": {"headline": "「表」就是外面带毛的皮衣。", "original_meaning": "「表」的本义是外衣，引申为外表、表示。", "structure_desc": "「表」从「衣」从「毛」，表示衣服外面带毛，也就是皮衣的外面。本义是外衣、外表。因为外衣是露在外面的，所以「表」引申出「表面」「表示」「表达」等意思。比如「表面」「表示」「表达」「手表」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「表」條；香港中文大學《漢語多功能字庫》「表」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A1%A8（2026-11-03 查閱）"},
  "21825_要_Z_說文‧𦥑部": {"headline": "「要」就是人双手叉着腰。", "original_meaning": "「要」的本义是腰部，引申为主要、需要。", "structure_desc": "古文字的「要」字，上面是「目」（代表头），中间是「大」（人），下面是双手叉腰的样子。本义是腰部（是「腰」的本字）。因为腰是身体的中间、关键部位，所以「要」引申出「主要」「重要」「需要」等意思。比如「重要」「需要」「要点」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「要」條；香港中文大學《漢語多功能字庫》「要」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A6%81（2026-11-03 查閱）"},
  "21889_见_Z_小篆": {"headline": "「见」就是一个人睁大了眼睛看。", "original_meaning": "「见」的本义是看见、看到。", "structure_desc": "「见」的繁体是「見」，甲骨文和金文从「目」从「卩」（一个跪坐的人），突出人的大眼睛，表示看见。本义就是看见、看到。比如「看见」「见面」「意见」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「見」條；香港中文大學《漢語多功能字庫》「見」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A6%8B（2026-11-03 查閱）"},
  "22452_说_Z_小篆": {"headline": "「说」就是用言语把话讲出来。", "original_meaning": "「说」的本义是讲述、解释。", "structure_desc": "「说」的繁体是「說」，从「言」，「兑」表音。本义是用言语讲述、解释。后来「说」引申出「说法」「说服」等意思。古文中「说」还可以表示「悦」（高兴），比如「学而时习之，不亦说乎」。比如「说话」「说明」「小说」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「說」條；香港中文大學《漢語多功能字庫》「說」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%AA%AA（2026-11-03 查閱）"},
  "22839_起_Z_說文‧走部": {"headline": "「起」就是从座位上站起来。", "original_meaning": "「起」的本义是起立、站起。", "structure_desc": "「起」从「走」（表示行走），「巳」表音。本义是站起来、起立。后来「起」引申出「开始」「兴起」「起床」等意思。比如「起立」「起床」「起来」「兴起」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「起」條；香港中文大學《漢語多功能字庫》「起」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B5%B7（2026-11-03 查閱）"},
  "23431_过_Z_小篆": {"headline": "「过」就是渡过水面、走过去。", "original_meaning": "「过」的本义是渡过、经过。", "structure_desc": "「过」的繁体是「過」，从「辵」（表示行走），「呙」表音。本义是渡过、经过。后来「过」引申出「过去」「超过」「过错」等意思。比如「经过」「过去」「超过」「过错」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「過」條；香港中文大學《漢語多功能字庫》「過」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%81%8E（2026-11-03 查閱）"},
  "23448_还_Z_小篆": {"headline": "「还」就是沿着圆形的路走回来。", "original_meaning": "「还」的本义是返回、归还。", "structure_desc": "「还」的繁体是「還」，从「辵」（表示行走），「睘」表音。「睘」本义是圆形的玉璧，圆的东西有回转的意思，加上「辵」表示行走，合起来就是走回来的意思。本义是返回、归还。后来「还」又表示「还是」「还有」等意思。比如「还有」「还是」「归还」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𨘣」條（今字作「還」）；香港中文大學《漢語多功能字庫》「還」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%82%84（2026-11-03 查閱）"},
  "23451_进_Z_小篆": {"headline": "「进」就是像鸟一样只能往前走。", "original_meaning": "「进」的本义是前进、向前走。", "structure_desc": "「进」的繁体是「進」，甲骨文从「隹」（短尾巴的鸟）从「止」（脚），表示鸟在往前走。因为鸟只会往前走不会后退，所以「进」有前进的意思。后来加上「辵」（行走），表示向前走。比如「前进」「进步」「进入」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「進」條；香港中文大學《漢語多功能字庫》「進」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%80%B2（2026-11-03 查閱）"},
  "23571_道_Z_說文‧辵部": {"headline": "「道」就是人走在大路上。", "original_meaning": "「道」的本义是道路，引申为道理、道德。", "structure_desc": "「道」从「首」（人头）从「止」（脚），表示人在走路。古文字的「首」和「止」合起来代表人，整个字画的是一个人走在道路上。本义是道路。因为走路要有路，做人也要有原则，所以「道」引申出「道理」「道德」等意思。比如「道路」「道理」「道德」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「道」條；香港中文大學《漢語多功能字庫》「道」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%81%93（2026-11-03 查閱）"},
  "23651_那_Z_說文‧邑部": {"headline": "「那」就是指比较远的人或东西。", "original_meaning": "「那」的本义是指代较远的事物，与「这」相对。", "structure_desc": "「那」从「邑」（表示地方），「冉」表音。《说文解字》说「那」是古代的一个国名。后来「那」被借用作指示代词，指代比较远的人或事物，和「这」相对。比如「那里」「那个」「那样」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𨙻」條（今字作「那」）；香港中文大學《漢語多功能字庫》「那」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%82%A3（2026-11-03 查閱）"},
  "23720_部_Z_說文‧邑部": {"headline": "「部」就是按地域划分的区域。", "original_meaning": "「部」的本义是古地名，引申为部门、部分。", "structure_desc": "「部」从「邑」（表示地方），「咅」表音。本义是古代的一个地名。后来「部」引申出「部分」「部门」「部位」等意思，指整体中的一个组成部分。比如「部分」「部门」「部位」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「部」條；香港中文大學《漢語多功能字庫》「部」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%83%A8（2026-11-03 查閱）"},
  "23741_都_Z_說文‧邑部": {"headline": "「都」就是有宗庙的大城市。", "original_meaning": "「都」的本义是都城、大城市。", "structure_desc": "「都」从「邑」（表示城邑），「者」表音。《说文解字》说，有先王宗庙的城邑叫「都」。本义是都城、大城市。后来「都」也作副词，表示「全部」，比如「都是」「都好」。比如「首都」「都市」「都是」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「都」條；香港中文大學《漢語多功能字庫》「都」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%83%BD（2026-11-03 查閱）"},
  "23948_里_Z_說文‧里部": {"headline": "「里」就是有田有土的村庄。", "original_meaning": "「里」的本义是人们聚居的地方，也表示内部。", "structure_desc": "「里」从「田」从「土」，表示有田有土可以居住的地方。本义是古代村民聚居的村庄。后来「里」也表示长度单位（一里路），还和「裏」合并，表示「里面」的意思。比如「里外」「里面」「公里」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「里」條；香港中文大學《漢語多功能字庫》「里」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%87%8C（2026-11-03 查閱）"},
  "23949_重_Z_說文‧重部": {"headline": "「重」就是人背着一个大口袋。", "original_meaning": "「重」的本义是沉重、分量大。", "structure_desc": "甲骨文和金文的「重」字，上面是「人」，下面是「東」（像一个大口袋），合起来就是一个人背着大口袋的样子。背着口袋当然很沉，所以「重」的本义是沉重。后来「重」引申出「重要」「重视」等意思。比如「沉重」「重要」「重视」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「重」條；香港中文大學《漢語多功能字庫》「重」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%87%8D（2026-11-03 查閱）"},
  "23951_量_Z_說文‧重部": {"headline": "「量」就是在太阳下量东西。", "original_meaning": "「量」的本义是衡量、量度。", "structure_desc": "甲骨文和金文的「量」字从「日」从「東」（像口袋），一说表示在太阳底下量度东西。本义是衡量、量度。后来「量」引申出「数量」「容量」等意思。比如「测量」「数量」「力量」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「量」條；香港中文大學《漢語多功能字庫》「量」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%87%8F（2026-11-03 查閱）"},
  "24895_长_Z_小篆": {"headline": "「长」就是拄着拐杖的长发老人。", "original_meaning": "「长」的本义是年长、长者，引申为长短的长。", "structure_desc": "「长」的繁体是「長」，甲骨文和金文字形象一个长头发的老人拄着拐杖。本义是年长、长者。因为老人的头发很长，所以「长」引申出「长短」的「长」。比如「长短」「长久」「长辈」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「長」條；香港中文大學《漢語多功能字庫》「長」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%95%B7（2026-11-03 查閱）"},
  "25006_问_Z_小篆": {"headline": "「问」就是在门口开口问话。", "original_meaning": "「问」的本义是询问、提问。", "structure_desc": "「问」的繁体是「問」，从「口」，「门」表音。甲骨文和金文从「门」从「口」，表示在门口开口问话。本义是询问、提问。比如「问题」「提问」「问候」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「問」條；香港中文大學《漢語多功能字庫》「問」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%95%8F（2026-11-03 查閱）"},
  "25012_间_Z_小篆": {"headline": "「间」就是月光从门缝里照进来。", "original_meaning": "「间」的本义是门缝、空隙。", "structure_desc": "「间」的繁体是「間」，本作「閒」，从「门」从「月」，表示月光从门缝里照进来。本义是门缝、空隙。后来「间」引申出「中间」「间隔」「房间」等意思。比如「中间」「间隔」「房间」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「閒」條（今字作「間」）；香港中文大學《漢語多功能字庫》「間」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%96%93（2026-11-03 查閱）"},
  "25378_面_Z_說文‧面部": {"headline": "「面」就是一张脸，中间是眼睛。", "original_meaning": "「面」的本义是脸、颜面。", "structure_desc": "甲骨文的「面」字，外面是脸的轮廓，中间是一只眼睛（目）。本义是脸、颜面。后来「面」引申出「表面」「面向」「面条」等意思。比如「面孔」「表面」「面向」「面条」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「面」條；香港中文大學《漢語多功能字庫》「面」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9D%A2（2026-11-03 查閱）"},
  "26264_高_Z_說文‧高部": {"headline": "「高」就是建在台基上的高楼。", "original_meaning": "「高」的本义是高大的楼台，引申为高低的高。", "structure_desc": "甲骨文和金文的「高」字，画的是建在高高的台基上的楼台。本义是高大的楼台。后来「高」引申出「高低」「高大」「高尚」等意思。比如「高大」「高低」「高尚」「高兴」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「高」條；香港中文大學《漢語多功能字庫》「高」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%AB%98（2026-11-03 查閱）"},
  "06740_五_Z_說文‧五部": {"headline": "两横相交，表示天地之间的第五种元素。", "original_meaning": "「五」的本义是五行，指金、木、水、火、土五者。", "structure_desc": "甲骨文、金文和小篆的「五」字构形相同，写法一直没有变。它的本义究竟是什么，至今没有定论。许慎认为这个字象天地阴阳交错之形，朱芳圃也持同样的看法。也有学者认为它只是一个刻识符号，用来表示数字「五」；还有学者认为它象收绳器的样子，是「互」字的初文。后来「五」被假借去表示数目「五」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「五」條；香港中文大學《漢語多功能字庫》「五」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%94（2026-11-11 查閱）"},
  "06672_乐_Z_小篆": {"headline": "木头架上系着琴弦，就是「乐」。", "original_meaning": "「乐」的本义是木制的乐器，后来引申出音乐和快乐的意思。", "structure_desc": "甲骨文的「乐」字从「糸」从「木」，罗振玉解释为「从丝附木上，琴瑟之象也」——木头上面附着琴弦，画的是一张琴。西周中期的金文又加上了「白」，「白」是拇指的形状，于是全字会出以手指弹琴的意思。到春秋以后，「木」又写成「亦」的形状。《说文解字》说「乐，五声八音总名。象鼓鞞。木，虡也」，还把鼓和乐器的木架都算了进去。后来「乐」引申为奏乐，又引申为使人快乐。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「樂」條；香港中文大學《漢語多功能字庫》「樂」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A8%82（2026-11-11 查閱）"},
  "07433_光_Z_說文‧火部": {"headline": "火在人的头顶上照着，就是「光」。", "original_meaning": "「光」的本义是光明、光亮。", "structure_desc": "甲骨文和金文的「光」字从「火」从「卩」，「卩」象一个人跪坐的样子。火在人上，取的是光明照耀的意思，许慎、李孝定、何琳仪都这样解释。《说文解字》说「光，明也。从火在人上，光明意也」，正说明了这一点。古文字另有「𤎫」「炗」等写法。「光」后来引申出光彩、光荣等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「光」條；香港中文大學《漢語多功能字庫》「光」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%89（2026-11-11 查閱）"},
  "17364_研_Z_說文‧石部": {"headline": "石头和刑具放在一起，就是「研」。", "original_meaning": "「研」的本义是研磨，就是细磨使东西粉碎或光滑。", "structure_desc": "「研」字从「石」从「幵」，「幵」是声符。石头是研的用物，所以「石」作意符；「幵」只用来标读音。本义是研磨，也就是把东西细细地磨碎或者磨光。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「研」條；香港中文大學《漢語多功能字庫》「研」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A0%94（2026-11-11 查閱）"},
  "25122_院_Z_說文‧阜部": {"headline": "土墙围起来的院子，就是「院」。", "original_meaning": "「院」的本义是围墙。", "structure_desc": "「院」字从「𨸏」从「完」，「𨸏」是阜的象形，表示土山、围墙一类的土石结构，「完」作声符。本义是围墙。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「院」條；香港中文大學《漢語多功能字庫》「院」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%99%A2（2026-11-11 查閱）"},
  "06756_交_Z_說文‧交部": {"headline": "一个人双腿交叉站着，就是「交」。", "original_meaning": "「交」的本义是交叉，指两腿相交。", "structure_desc": "「交」字从「大」象交叉之形。甲骨文和金文、小篆的「交」都是「人」字形变体，画的是一个人双手伸展、两腿交叉的样子。《说文解字》说「交，交胛也。从大，象交形」。甲骨文旧释作「交」的字，有一部分和「黄」字相混。战国竹简里「交」指交往，比如《郭店楚简．性情论》说「同方而交，以道者也」。传世的「交」多指交错，也指结交。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「交」條；香港中文大學《漢語多功能字庫》「交」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%A4（2026-11-11 查閱）"},
  "08192_呀_Z_說文‧口部": {"headline": "张开嘴巴露出牙，就是「呀」。", "original_meaning": "「呀」的本义是张口的样子。", "structure_desc": "「呀」字从「口」从「牙」，「牙」作声符，「口」表意。合起来表示张开嘴巴的样子。这个字属于《说文解字》的《说文新附》，是东汉以后才收入的字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「呀」條；香港中文大學《漢語多功能字庫》「呀」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%91%80（2026-11-11 查閱）"},
  "11141_必_Z_說文‧八部": {"headline": "原来画的是一件兵器的柄。", "original_meaning": "「必」的本义是兵器的柄，后来引申出必定、必然的意思。", "structure_desc": "甲骨文的「柲」象古代兵器的柄。金文在柄的形状两边加上声符「八」，写成「必」。《说文解字》把「必」释为从「八」「弋」，其实是误释。段玉裁说「柲」是「弋」的本字，柄就是用来把持兵器的，所以「必」有了「必定如此、一定要」的意思，是从柄的坚固耐用引申出来的。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「必」條；香港中文大學《漢語多功能字庫》「必」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%85（2026-11-11 查閱）"},
  "23422_达_Z_小篆": {"headline": "一个人走在大路上，就是「达」。", "original_meaning": "「达」的本义是通达，指行路不相遇。", "structure_desc": "甲骨文的「达」字从「辵」从「大」，「大」是声符，「辵」表示行走，整字象一个人在大路上行走，含通达、到达的意思。金文从「辵」从「午」从「羊」，构形的原义已不明确。战国文字里「辵」旁的字都有行走的意思，所以从「辵」的「达」字本义是前往、去到。金文中「达」表示讨伐，比如《尚书．顾命》说「用克达殷集大命」。楚简里「达」表示通达、发达，《郭店楚简．穷达以时》说「穷达以时」，讲的是穷困和发达要看时机和际遇。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「達」條；香港中文大學《漢語多功能字庫》「達」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%81%94（2026-11-11 查閱）"},
  "11736_战_Z_小篆": {"headline": "两件兵器摆在一起，就是「战」。", "original_meaning": "「战」的本义是战斗。", "structure_desc": "金文的「战」字从「单」从「戈」，「单」象狩猎或作战用的工具，「戈」是兵器，两件都是作战的器具，所以用「单」「戈」表示战斗。《说文解字》说「战，鬬也。从戈，单声」，并把「单」定为声符。金文里也有不从「单」而从「嘼」的写法，「嘼」是「单」的繁体，意思相同。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「戰」條；香港中文大學《漢語多功能字庫》「戰」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%B0（2026-11-11 查閱）"},
  "21892_规_Z_小篆": {"headline": "一个人拿着工具画圆，就是「规」。", "original_meaning": "「规」的本义是法度、准则，一说本义是画圆的工具。", "structure_desc": "「规」字从「夫」从「见」，两个字都作意符。画圆要用圆规，画的时候要俯身去看，所以「夫」（人）和「见」（看）合在一起就是画圆的姿态。它的本义，一说就是画圆的工具，一说是法度、准则。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「規」條；香港中文大學《漢語多功能字庫》「規」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A6%8F（2026-11-11 查閱）"},
  "19047_级_Z_小篆": {"headline": "丝线分出先后次序，就是「级」。", "original_meaning": "「级」的本义是丝的优劣次第，引申表示次第、等级。", "structure_desc": "「级」字从「糸」从「及」，「及」作声符。丝线有粗有细、有先有后，古人用丝的次第来表示等级的先后，本义是丝的优劣次第。后来「级」引申为次第、等级，又表示级别的台阶，比如「级别」「高级」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「級」條；香港中文大學《漢語多功能字庫》「級」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B4%9A（2026-11-11 查閱）"},
  "07774_办_Z_小篆": {"headline": "把力气使出来，就是「办」。", "original_meaning": "「办」的本义是致力、治理、办理。", "structure_desc": "「办」的繁体是「辦」，从「力」从「辡」，「辡」作声符，「力」表意。《说文解字》把「办」收入《说文新附》，释为「致力也。从力，辡声」，是东汉以后才补入的字。因为要办成事情就得使出力气，所以有致力、办理的意思。后来「办」引申为举办、置办、准备。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「辦」條；香港中文大學《漢語多功能字庫》「辦」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%BE%A6（2026-11-11 查閱）"},
  "12534_收_Z_說文‧攴部": {"headline": "用手把猎物抓住，就是「收」。", "original_meaning": "「收」的本义是拘捕、捕捉。", "structure_desc": "「收」字从「攴」从「丩」，「丩」作声符。「攴」是拿鞭子敲打的动作，表示捕捉时需要追打、制服。本义是拘捕。《诗经．大雅．瞻仰》说「此宜无罪，女反收之」，毛传解释为「收，拘收也」。后来「收」引申为征收、收缴、收回，又表示收敛、殓葬。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「收」條；香港中文大學《漢語多功能字庫》「收」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%94%B6（2026-11-11 查閱）"},
  "25670_领_Z_小篆": {"headline": "一个人低着头，就是「领」。", "original_meaning": "「领」的本义是脖子、颈项。", "structure_desc": "「领」的繁体是「領」，从「页」从「令」，「令」作声符。「页」是头部的象形，古文字里「页」象人低头的样子。《诗经．卫风．硕人》说「领如蝤蛴」，毛传解释「领，颈也」。本义是脖子。因为脖子上的衣领最显眼，「领」引申为衣领；又因为首领能统率众人，「领」又引申出统率、管领、治理的意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「領」條；香港中文大學《漢語多功能字庫》「領」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A0%98（2026-11-11 查閱）"},
  "14117_步_Z_說文‧步部": {"headline": "两只脚一前一后迈开，就是「步」。", "original_meaning": "「步」的本义是步行，指缓缓地走。", "structure_desc": "「步」字从两个「止」，「止」象脚趾之形。两个「止」多左右异向，一个象左足，一个象右足，两足一上一下，会出左右两脚前后相承的样子。郑樵《通志．六书略》说「步，行也，象二趾相前后」。甲骨文、陶文里或类化成两个方向相同的「止」，兆域图铜板上的「步」，两个「止」还变成左右相背形。《尔雅．释宫》说「堂下谓之步」，郝懿行义疏引《淮南．人间篇》「走者，人之所以为疾也；步者，人之所以为迟也」，说明「步」是徐行，与「走」的疾行有别。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「步」條；香港中文大學《漢語多功能字庫》「步」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AD%A5（2026-11-11 查閱）"},
  "14769_深_Z_說文‧水部": {"headline": "手伸进洞穴去探，就是「深」。", "original_meaning": "「深」的本义是水深，引申为情感的深切。", "structure_desc": "甲骨文和金文的「深」字从「水」从「罙」，「罙」作声符。「罙」是「探」的初文，象以手探穴之形；「水」作意符，本义是深浅的「深」。甲骨文的用法还不详，金文表示深浅之深，由水深引申为情感的深切，中山王方壶有「爱深则贤人亲」之语。简帛文字里表示深浅，简帛上又借「探」字表示「深」，《马王堆帛书．十问》说「息必探而久」，指呼吸深而长久。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「深」條；香港中文大學《漢語多功能字庫》「深」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B7%B1（2026-11-11 查閱）"},
  "08086_取_Z_說文‧又部": {"headline": "一只手拎着耳朵，就是「取」。", "original_meaning": "「取」的本义是持取、捕获。", "structure_desc": "甲骨文和金文的「取」字从「耳」从「又」，象一只手拿着耳朵的样子。古时打仗抓到俘虏要割下左耳来计数记功，《周礼》说「获者取左耳」，《司马法》说「载献聝」，「聝」就是耳朵。所以「取」有了捕取、取得的意思，后来引申为一切取获之义，连娶妻的「娶」也从这里来。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「取」條；香港中文大學《漢語多功能字庫》「取」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%96（2026-11-11 查閱）"},
  "07957_单_Z_小篆": {"headline": "树枝上绑着一块石头，就是「单」。", "original_meaning": "「单」的本义是一种用于打猎或作战的武器。", "structure_desc": "甲骨文和金文的「单」象在树枝上绑上石刀，是一种武器，用来打猎或打仗。中间那个田形的部分，可能象柄部缠绕的绳索，以便投掷后收回，也可能象绑着的石头。「单」作声符兼意符的字，大都与狩猎或战争有关，比如「战」表示战争，「弹」表示弹弓，「殫」表示竭尽。后来「单」被假借用来表示数词「一个」，又引申为单独、孤单。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「單」條；香港中文大學《漢語多功能字庫》「單」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%96%AE（2026-11-11 查閱）"},
  "10696_师_Z_小篆": {"headline": "军队驻扎在土阜上，就是「师」。", "original_meaning": "「师」的本义是军队，二千五百人为一师。", "structure_desc": "「师」字从「𠂤」从「帀」，「𠂤」字形有解作小土阜的，也有解作「臀尻」的；「帀」是古「柢」字，象根柢，作「师」的声符。由于军旅驻扎多据土阜以守，所以「𠂤」后来就解作「师」。《说文解字》说「师，二千五百人为师」，金文多表示职官名，为军事长官，又叫「师氏」，兼掌行政与教育。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「師」條；香港中文大學《漢語多功能字庫》「師」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B8%AB（2026-11-11 查閱）"},
  "10976_张_Z_小篆": {"headline": "把弓弦绷紧，就是「张」。", "original_meaning": "「张」的本义是施弓弦、拉弓弦。", "structure_desc": "「张」的繁体是「張」，金文从「弓」从「长」，「长」作声符。小篆的字形表示把弦绷在弓上或者拉紧弓弦，与「弛」相对。《说文解字》说「张，施弓弦也。从弓，长声」。《诗经．小雅．吉日》说「既张我弓，既挟我矢」，用的就是张弓的意思。后来「张」引申出拉紧乐器的弦、紧张、张开、展开，又表示盛大、布列、陈设。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「張」條；香港中文大學《漢語多功能字庫》「張」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BC%B5（2026-11-11 查閱）"},
  "23520_造_Z_說文‧辵部": {"headline": "走到告的地方去，就是「造」。", "original_meaning": "「造」的本义是前往、去到。", "structure_desc": "「造」字最初以「艸」的象形初文作声符。甲骨文的样子象弯曲的草形，到金文变成头部向左倾的「屮」形。古文字的「造」并不从「告」：「造」字所从声符上半的中竖常向左屈头，「告」字的中竖都是直头，这是陈剑考证出的区别。金文或加「辵」，而从「辵」的字都有行走之意，所以从「辵」的「造」字本义是前往、去到。《说文解字》说「造，就也。从辵，告声」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「造」條；香港中文大學《漢語多功能字庫》「造」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%80%A0（2026-11-11 查閱）"},
  "20081_花_Z_小篆": {"headline": "草字头下面，一朵花开了。", "original_meaning": "「花」的本义是花朵，古字作「華」。", "structure_desc": "「花」的古字是「華」。金文的「華」上面象花朵盛放之形，下面是茎叶（「于」形），「于」为声符，本义是花朵。《诗经．周南．桃夭》说「桃之夭夭，灼灼其华」，用的就是这个意思。也有一说认为上面象花蕾，不过金文的构形并不像花苞。「華」的小篆写作「𦻏」，「𠌶」和「華」音义皆同，古本一字，《说文解字》误分为二。《说文》说「华，荣也。从艸从𠌶」，「荣也」这一义是从花朵盛放引申来的。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「華」條；香港中文大學《漢語多功能字庫》「花」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%8A%B1（2026-11-11 查閱）"},
  "17185_睡_Z_說文‧目部": {"headline": "眼皮垂下来，就是「睡」。", "original_meaning": "「睡」的本义是坐着打盹。", "structure_desc": "「睡」字从「目」从「垂」，「垂」作声符，「目」表意，表示眼睛垂下、合上。本义是坐着打盹。典籍里有用本义的，《战国策．秦策一》说「读书欲睡，引锥自刺其股」，《史记．商君列传》说「孝公时时睡，弗听」。后来「睡」引申为躺下、入睡，又表示睡梦中不能说话或不能行动。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「睡」條；香港中文大學《漢語多功能字庫》「睡」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9D%A1（2026-11-11 查閱）"},
  "10196_尔_Z_說文‧八部": {"headline": "三足的绕丝架子，就是「尔」。", "original_meaning": "「尔」的本义是绕丝、纺线的架子，后来借用作第二人称代词。", "structure_desc": "甲骨文和金文的「尔」象一个三足的绕丝、纺线架子：上面是锐头，中间是器身，下面是竖足，四周有丝线缠绕。本义是绕丝的架子，是「檷」的初文（林义光）。金文「爾」的上部写作「尔」，其实是从「爾」字省去下半部分分化出来的，所以简化字用「尔」表示「爾」。许慎认为「爾」的本义是「丽尔」，即窗棂交错、格格相连的样子，这个义罕用。后来「尔」借用作第二人称代词，也就是「你」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「爾」條；香港中文大學《漢語多功能字庫》「爾」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%88%BE（2026-11-11 查閱）"},
  "16652_界_Z_說文‧田部": {"headline": "田地划出边界，就是「界」。", "original_meaning": "「界」的本义是疆界、边境，即土地的分界。", "structure_desc": "「界」字从「田」从「介」，「介」作声符，「田」表意。田地是要划分界限的，所以从「田」，本义是境、边境。马王堆帛书里「界」字简写作「介」，或写作「畍」。《说文解字》写作「畍，境也。从田，介声」。后来「界」引申出界限、范围，又表示不同的门类，比如「界线」「境界」「各界」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「畍」條（今字作「界」）；香港中文大學《漢語多功能字庫》「界」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%95%8C（2026-11-11 查閱）"},
  "12552_效_Z_說文‧攴部": {"headline": "用棍子鞭策着学，就是「效」。", "original_meaning": "「效」的本义是效法、学习别人的长处。", "structure_desc": "甲骨文和金文的「效」从「攴」从「交」，「交」作声符。「攴」表示手持棍棒或鞭子敲打，「效」字会用棍子督促、鞭策，教人效法。「交」象两腿相交之形，在这里作声符。不过甲骨文、金文部分字形里的「交」写得近乎「矢」，于是有学者解为矫正弓箭之形，白川静也持这种看法，可以两说并存。「效」本义疑为效法，后来这一意义的「效」被加上人字旁写成「傚」。「效」又引申出效果、效忠等用法。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「效」條；香港中文大學《漢語多功能字庫》「效」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%95%88（2026-11-11 查閱）"},
  "08253_命_Z_說文‧口部": {"headline": "张开口，向跪着的人下令。", "original_meaning": "「命」的本义是发号施令，使唤人。", "structure_desc": "金文的「命」从「卩」从「亼」从「口」，「亼」象朝下张大的口，「卩」象跪坐的人形，合起来会出张口向跪着的下人发号施令的样子。「命」由「令」加「口」分化而成。后来「命」引申出天命、生命的意思，又表示命运、奉命。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「命」條；香港中文大學《漢語多功能字庫》「命」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%91%BD（2026-11-11 查閱）"},
  "17454_确_Z_說文‧石部": {"headline": "石头坚硬，就是「确」。", "original_meaning": "「确」的本义是坚固、坚硬。", "structure_desc": "「确」的繁体是「確」，从「石」从「隺」，「隺」作声符，「石」表意，表示坚硬可靠。《说文解字》的本字写作「确」，释为「礊石也。从石，角声」，臣铉等注「今俗作确，非是」。《玉篇．石部》说「确，坚固也」。后来「确」表示坚定、坚决，又表示真实、准确。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「确」條；香港中文大學《漢語多功能字庫》「確」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A2%BA（2026-11-11 查閱）"},
  "07515_军_Z_小篆": {"headline": "战车围成一个圈子，就是「军」。", "original_meaning": "「军」的本义是围起来的车阵，四千人为一军。", "structure_desc": "金文的「军」字初从「勹」从「车」，中山王鼎写作从「车」从「勻」，九年将军戈则从「车」从「螾」，都是围合之形。《说文解字》说「军，圜围也。四千人为军。从车从包省」，又说「军，兵车也」。《周礼．地官．司徒》说「五旅为师，五师为军」，郑玄注「军万二千五百人」。后来「军」引申为军队、武装，又指驻军的地方。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「軍」條；香港中文大學《漢語多功能字庫》「軍」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%BB%8D（2026-11-11 查閱）"},
  "12078_据_Z_說文‧手部": {"headline": "手握着一根杖，就是「据」。", "original_meaning": "「据」的本义是拄着杖，手持支撑。", "structure_desc": "「据」的繁体是「據」，从「手」从「豦」，「豦」作声符。「手」表意，「豦」只用来标读音。本义是杖持，就是拄着拐杖支撑身体。《说文解字》说「据，杖持也。从手，豦声」。后来「据」引申为占据、依据，又表示依据、凭证。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「據」條；香港中文大學《漢語多功能字庫》「據」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%93%9A（2026-11-11 查閱）"},
  "06849_企_Z_說文‧人部": {"headline": "人踮起脚尖往远处看。", "original_meaning": "「企」的本义是踮着脚尖、抬起脚跟站立。", "structure_desc": "甲骨文和金文的「企」象一个人站在「止」上，突出人的足部，表明这个动作与脚有关。《说文解字》说「企，举踵也。从人，止声」，「举踵」就是抬起脚跟。段玉裁注指出古文字中脚部渐渐从「人」分离出来，所以字从「人」从「止」。由于「企」指踮脚站立，又可以指翘首远望，《汉书．高帝纪上》说「日夜企而望归」。后来「企」引申出企望、企盼。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「企」條；香港中文大學《漢語多功能字庫》「企」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BC%81（2026-11-11 查閱）"},
  "11913_拉_Z_說文‧手部": {"headline": "手一使劲，把东西折断。", "original_meaning": "「拉」的本义是折断、摧折。", "structure_desc": "「拉」字从「手」从「立」，「立」作声符，「手」表意。本义是折断。《说文解字》说「拉，摧也。从手，立声」。《汉书．邹阳传》写「范雎拉胁折齿于魏，卒为应侯」，颜师古注「拉，摧也」。后来「拉」表示牵引、拉扯，又表示邀约。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「拉」條；香港中文大學《漢語多功能字庫》「拉」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8B%89（2026-11-11 查閱）"},
  "06770_亲_Z_說文‧木部": {"headline": "親自到場去看，就是「亲」。", "original_meaning": "「亲」的本义是亲临、亲自。", "structure_desc": "金文的「亲」从「辛」从「视」的古文，「辛」是声符。金文里「亲」表示亲临、亲自，克钟有「王亲令克遹泾东至于京师」之语。古文字里「视」与「见」的区别在于：「视」的人形是站立的，「见」的人形是跪坐的。战国秦简的「辛」下从「木」，为小篆所本。《说文解字》说「亲，至也。从见，亲声」。后来「亲」引申出亲近、亲近的人，又表示父亲、母亲。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「親」條；香港中文大學《漢語多功能字庫》「親」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A6%AA（2026-11-11 查閱）"},
  "06987_例_Z_說文‧人部": {"headline": "人排成行列，就是「例」。", "original_meaning": "「例」的本义是类别、行列。", "structure_desc": "「例」字从「人」从「列」，「列」作声符，「人」表意。人排成行列，就有了类别、等级的意思。《说文解字》说「例，比也。从人，列声」。《公羊传．僖公元年》有「臣子一例也」，何休注说臣之继君犹子之继父。后来「例」表示准则、规则，又表示用来帮助说明或证明某种情况的事物，比如「举例」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「例」條；香港中文大學《漢語多功能字庫》「例」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BE%8B（2026-11-11 查閱）"},
  "23340_转_Z_小篆": {"headline": "车子调转方向，就是「转」。", "original_meaning": "「转」的本义是转运、移徙。", "structure_desc": "「转」的繁体是「轉」，从「车」从「专」，「专」作声符。「车」表意，本义是转运、移徙。《说文解字》说「转，运也。从车，专声」。《逸周书．大匡》说「粮穷不转，孤寡不废」，用的就是这个意思。后来「转」表示转向、改变，也表示逃避、摇动。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「轉」條；香港中文大學《漢語多功能字庫》「轉」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%BD%89（2026-11-11 查閱）"},
  "22406_识_Z_小篆": {"headline": "用言语记下见闻，就是「识」。", "original_meaning": "「识」的本义是记识、记得。", "structure_desc": "「识」的繁体是「識」，从「言」从「戠」，「戠」作声符，「言」表意，表示用言语记下来，所以本义是记识、记得。《说文解字》说「识，常也。一曰：知也。从言，戠声」。杨树达《积微居小学述林．释识》指出，「识」字按记事的先后分三义：最先为记识，次为认识，最后为知识。后来「识」表示知道、认识，又表示见识、常识。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「識」條；香港中文大學《漢語多功能字庫》「識」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%AD%98（2026-11-11 查閱）"},
  "22858_越_Z_說文‧走部": {"headline": "跨过一道坎，就是「越」。", "original_meaning": "「越」的本义是越过、跨过。", "structure_desc": "「越」字从「走」从「戉」，「戉」作声符，「走」表意，表示跨过去，所以本义是越过、跨过。《说文解字》说「越，度也。从走，戉声」。《楚辞．天问》有「阻穷西征，岩何越焉」，王逸注「越，度也」。后来「越」引申出时间上的经过，表示经历，又表示超出、胜过。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「越」條；香港中文大學《漢語多功能字庫》「越」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B6%8A（2026-11-11 查閱）"},
  "25055_队_Z_小篆": {"headline": "从高处掉下来，就是「队」。", "original_meaning": "「队」的本义是从高处坠落。", "structure_desc": "「队」的繁体是「隊」，金文从「阜」从「㒸」，「㒸」作声符，小篆相同。「阜」是土山的意思，从高处落下，与山阜有关，所以本义是坠落，后来多写作「坠」。段玉裁注说「队」「坠」是正俗字，古书多作「队」，今则「坠」行而「队」废。《左传．庄公八年》有「公惧，队于车」，说的就是这个意思。后来「队」表示队伍、行列。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「隊」條；香港中文大學《漢語多功能字庫》「隊」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9A%8A（2026-11-11 查閱）"},
  "14789_清_Z_說文‧水部": {"headline": "水清得能照见底。", "original_meaning": "「清」的本义是水清、水澄澈。", "structure_desc": "「清」字从「水」从「青」，「青」作声符，「水」表意，表示水源清澈澄明。《说文解字》说「清，朗也。澄水之皃。从水，青声」。金文里的用法还不详，战国竹简上表示清醇，《睡虎地秦简．日书甲种》有「肥豚清酒美白粱」。又通假为「静」，表示清静，《郭店简．老子乙》写「清清为天下定」，传世本《老子》则作「清静为天下正」。后来「清」引申为清楚、清明，又表示廉洁、清白。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「清」條；香港中文大學《漢語多功能字庫》「清」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B8%85（2026-11-11 查閱）"},
  "06880_传_Z_小篆": {"headline": "驿站备着的车马，就是「传」。", "original_meaning": "「传」的本义是驿站所设的车马，后来引申为传递、传记。", "structure_desc": "「传」的繁体是「傳」，甲骨文和金文从「人」从「专」，「专」作声符。本义是驿站所设的车马（许慎）。段玉裁注说「传者，如今之驿马。驿必有舍，故曰传舍」。《尔雅．释言》说「驹、遽，传也」，郭璞注「皆传车驿马之名」。《周礼．秋官．行夫》说「行夫掌邦国传遽之小事」，郑玄注「传遽，若今时乘传骑驿而使者也」。金文「传」或从「辵」，表示行走之意。后来「传」引申为传递、传送，又表示传播、传记。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「傳」條；香港中文大學《漢語多功能字庫》「傳」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%82%B3（2026-11-11 查閱）"},
  "25374_非_Z_說文‧非部": {"headline": "两只翅膀向两边张开。", "original_meaning": "「非」的本义是翅膀，因两翅相背而有违背的意思。", "structure_desc": "甲骨文和金文的「非」象向左右张开的翅膀之形，本义是翅膀（许慎、林义光）。由于左右翅膀展开后彼此互相背向，所以「非」有了违背的意思。《说文解字》说「非，违也。从飞下翄，取其相背」。甲骨文里「非」用作否定词表示无，《合集》16927 有「非忧」之语，指没有忧患。金文表示过失、错误，毛公鼎有「引唯乃知余非，庸又闻」，意谓你知道我的过失。金文中「非」又用作动词表示认为错误，中山王方壶有「寡人非之」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「非」條；香港中文大學《漢語多功能字庫》「非」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9D%9E（2026-11-11 查閱）"},
  "23363_较_Z_小篆": {"headline": "车箱两旁的横木，就是「较」。", "original_meaning": "「较」的本义是车箱两旁车栏上的横木。", "structure_desc": "「较」的繁体是「較」，金文从「车」从「爻」，「爻」作声符，《说文》作「䡈」。传世的「较」多写作从「车」从「交」，「交」作声符。本义是车箱两旁车栏上的横木。徐灏《说文解字注笺》引郑玄《考工记》注说「较，辐上出式者是也」，马瑞辰《毛诗传笺通释》解说「车辐上之木为较」。《诗经．小雅．淇奥》有「宽兮绰兮，倚重较兮」，用的就是这个意思。「较」后来通「角」，表示比试、竞逐。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「䡈」條（今字作「较」）；香港中文大學《漢語多功能字庫》「較」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%BC%83（2026-11-11 查閱）"},
  "07558_准_Z_小篆": {"headline": "水平如镜，就用「准」来量。", "original_meaning": "「准」的本义是水之平，引申为标准、准则。", "structure_desc": "「准」从「水」从「隼」，「隼」作声符，「水」表意，天下没有比水更平的东西，所以用水平来作标准。《说文解字》说「准，平也。从水，隼声」，段玉裁注「谓水之平也。天下莫平于水，水平谓之准」。后来「准」表示古代测量水平的仪器，《韩非子．有度》说「绳直而枉木斲，准夷而高科削」。「准」又表示标准、准则，《荀子．致仕》说「程者，物之准也；礼者，节之准也」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「準」條；香港中文大學《漢語多功能字庫》「準」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%BA%96（2026-11-11 查閱）"},
  "13255_标_Z_小篆": {"headline": "树梢最末端的那一截。", "original_meaning": "「标」的本义是树梢，引申表示事物的枝节或表面。", "structure_desc": "「标」的繁体是「標」，从「木」从「票」，「票」作声符。本义是树梢。《说文解字》说「标，木杪末也。从木，票声」。《庄子．天地》说「上如标枝，民如野鹿」，陆德明释文「言树杪之枝无心在上也」。《楚辞．九章．悲回风》有「处雌霓之标颠」，李白《蜀道难》有「上有六龙回日之高标」，都是指顶端。「标」又表示事物的枝节或表面，与「本」相对，《素问．标本病传论》说「病发而有余，本而标之，先治其本，后治其标」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「標」條；香港中文大學《漢語多功能字庫》「標」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A8%99（2026-11-11 查閱）"},
  "14139_死_Z_說文‧死部": {"headline": "一个人跪坐在白骨旁边。", "original_meaning": "「死」的本义是死亡。", "structure_desc": "甲骨文和金文的「死」从「歹」从「人」，「人」是跪坐的人形，「歹」疑象剔去肉以后的残骨，合起来会出生人低头跪坐在朽骨旁悼念的样子，本义是死亡（罗振玉、刘兴隆）。也有一种说法认为「人」「歹」合起来表示人死后身体腐化、剩下白骨（加藤常贤）。杨树达、马叙伦、高鸿缙认为「死」是尸体「尸」的本字。甲骨文用作本义，《合集》22049 有「贞：不死」。金文表示死亡，齐侯镈有「用祈寿老母死」，中山王鼎有「死罪」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「死」條；香港中文大學《漢語多功能字庫》「死」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AD%BB（2026-11-11 查閱）"},
  "19476_联_Z_小篆": {"headline": "用丝线把饰物系在耳朵上。", "original_meaning": "「联」的本义是绑系、联系。", "structure_desc": "「联」的繁体是「聯」，甲骨文从「耳」从「幺」，金文从「耳」从「糸」，会以丝来装饰或绑系饰物于耳的意思（叶保民）。林义光则认为「耳」是指鼎、爵、盘一类器物的耳，「联」指把这些器物的耳用丝绳穿起来，姑备一说。《说文解字》说「联，连也。从耳，耳连于颊也；从丝，丝连不绝也」。甲骨文「联雨」表示连绵地下雨。金文又同音通假为「琏」，《论语．公冶长》孔子说子贡是「瑚琏」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「聯」條；香港中文大學《漢語多功能字庫》「聯」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%81%AF（2026-11-11 查閱）"},
  "20034_节_Z_小篆": {"headline": "竹子一段段相接的地方。", "original_meaning": "「节」的本义是竹节。", "structure_desc": "「节」本指竹的节理，即竹子各段相连处突出的部位。《说文解字》说「节，竹约也。从竹，即声」，桂馥《说文解字义证》说「约谓身有九节也」。《史记．龟策列传》说「竹，外有节理，中直空虚」。「节」始见于战国金文，从「竹」「即」声，与小篆同。古时「节」用作身份、权力的凭证，竹节剖成两半，分由帝王和执事官员持有，两半吻合才有效。战国时的鄂君启舟节、车节是水陆经商的免税通行证，而虎符也可称为「节」。后来「节」引申为节省、节日，又表示气节、节操。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「節」條；香港中文大學《漢語多功能字庫》「節」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AF%80（2026-11-11 查閱）"},
  "07435_克_Z_說文‧克部": {"headline": "一个人用肩膀挑着重物。", "original_meaning": "「克」的本义是肩负重物，引申为胜任、能够。", "structure_desc": "甲骨文和金文的「克」从「由」从另一个部件，林义光、李孝定认为象人以肩膀担负重物，上部象所肩负之物，本义为肩负重物，引申为胜任。《说文解字》说「克，肩也。象屋下刻木之形」，并说「𠅡，古文克」。后期金文上部不从「由」而从「古」。甲骨文用作人名，又表示能够，《合集》20508 有「其克翦周」。又表示战胜，《乙》5582 有「正征基方，克」。金文表示战胜，何尊有「武王既克大邑商」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「克」條；香港中文大學《漢語多功能字庫》「克」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%8B（2026-11-11 查閱）"},
  "22943_跟_Z_說文‧足部": {"headline": "脚后面跟着的那一段。", "original_meaning": "「跟」的本义是脚后跟。", "structure_desc": "「跟」从「足」从「艮」，「艮」作声符。《说文解字》的或体作「𣥦」，从「止」从「艮」，「足」和「止」是义近的形符，可以通用。本义是脚后跟。《释名．释形体》说「足后曰跟，在下旁著地，一体任之，象木根也」。《焦氏易林．蹇之第三十九》有「头痒搔跟，无益于疾」，苏轼《凤翔八观．石鼓》有「模糊半已似瘢胝，诘曲犹能辨跟肘」。「跟」后来引申为泛指物件的底部、后部，又表示追随、跟随。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「跟」條；香港中文大學《漢語多功能字庫》「跟」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B7%9F（2026-11-11 查閱）"},
  "21890_观_Z_小篆": {"headline": "站得高，看得远。", "original_meaning": "「观」的本义是观看、观察。", "structure_desc": "「观」的繁体是「觀」，金文从「见」为意符，「雚」为声符，本义是观看、观察。凭高望远可以望到的建筑物称为楼观、台观。甲骨文以「雈」「雚」表示「观」。《说文解字》说「观，谛视也。从见，雚声」，又收古文「𩁰」，从「囧」。后来「观」引申出观看、观赏，又表示观察、考察，比如「参观」「观念」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「觀」條；香港中文大學《漢語多功能字庫》「觀」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A7%80（2026-11-11 查閱）"},
  "07039_便_Z_說文‧人部": {"headline": "人遇到不方便，就换一换。", "original_meaning": "「便」的本义是安适。", "structure_desc": "「便」从「人」从「更」，两个字都作意符。《说文解字》说「便，安也。人有不便，更之。从人、更」，意思是人如果有不便的地方，就把它改掉，所以本义是安适、舒适。《战国策．秦策三》有「食不甘味，卧不便席」，用的就是这个意思。后来「便」表示适宜的时机、顺便的机会，如《史记．秦始皇本纪》说「因利乘便，宰割天下」；又表示方便、擅长、灵便。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「便」條；香港中文大學《漢語多功能字庫》「便」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BE%BF（2026-11-11 查閱）"},
  "13019_望_Z_說文‧亡部": {"headline": "站在高處，向远处眺望。", "original_meaning": "「望」的本义是远望。", "structure_desc": "「望」的金文从「亡」从「月」从「𡈼」，「亡」是声符。「望」「朢」是一字异体，「朢」的本义是登高望远，后来象竖起眼睛的「臣」声化为「亡」。由于金文常用「朢」表示月满，是透过月亮的圆缺来记录时间，所以「朢」从「月」为意符。《说文解字》以「朢」表示月满、「望」表示希望，其实「朢」「望」本来是一字。李孝定说「臣为竖目形，绝不可省，作字者任意为之耳，形声之字，例属后起，故知作望者必较为朢为晚出」。金文里的「望」多用为月相名。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「望」條；香港中文大學《漢語多功能字庫》「望」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%9B（2026-11-11 查閱）"},
  "17974_究_Z_說文‧穴部": {"headline": "一直挖到洞穴的尽头。", "original_meaning": "「究」的本义是穷尽、到底。", "structure_desc": "「究」从「穴」从「九」，「九」作声符，「穴」表意，表示挖到洞穴的最深处，本义是穷尽。《说文解字》说「究，穷也。从穴，九声」，《汉书．司马迁传》有「当年不能究其礼」，颜师古注「究，尽也」。后来「究」引申为达到终极、尽头，《庄子．盗跖》说「穷美究势，至人之所不得逮」。又引申为遍及、贯彻，如《汉书．萧望之传》说「恐德化之不究」。现在「究」又有研究、探求的意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「究」條；香港中文大學《漢語多功能字庫》「究」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A9%B6（2026-11-11 查閱）"},
  "11127_德_Z_說文‧彳部": {"headline": "在路上走着，目视前方。", "original_meaning": "「德」的本义是道德、德行。", "structure_desc": "「德」的甲骨文从「彳」从「直」，金文改从「惪」，「直」「惪」都作声符。「彳」象道路，强调正道、得道之意。全字表示人在路上行走，目光直望向前，意会人的行为正直，所以本义是道德。甲骨文或不从「彳」而从「亍」或从「行」，表示的道路意思相同。金文所从的「惪」，「心」旁中间或加一点，变成从「直」从「悤」，「悤」象人心通彻、聪明，以表有德者多为聪明敏慧之人。甲骨文通作「陟」表示前进。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「德」條；香港中文大學《漢語多功能字庫》「德」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%B7（2026-11-11 查閱）"},
  "07950_华_Z_小篆": {"headline": "草字头下面，一朵花开了。", "original_meaning": "「华」的本义是花朵，是「花」的古字。", "structure_desc": "「華」是「花」的古字。金文的「華」上面象花朵盛放之形，下面是茎叶（「于」形），「于」为声符，本义是花朵。《诗经．周南．桃夭》说「桃之夭夭，灼灼其华」，用的就是这个意思。也有一说认为上面象花蕾（高鸿缙），不过金文的构形并不像花苞。「華」的小篆写作「𦻏」，「𠌶」和「華」音义皆同，古本一字，《说文解字》误分为二。《说文》说「华，荣也。从艸从𠌶」，「荣也」这一义是从花朵盛放引申来的。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「華」條；香港中文大學《漢語多功能字庫》「華」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%8F%AF（2026-11-11 查閱）"},
  "10815_广_Z_說文‧广部": {"headline": "一座没有围墙的大屋子。", "original_meaning": "「广」的本义是大屋，引申为宽广。", "structure_desc": "「广」的繁体是「廣」，甲骨文从「宀」从「黄」，金文从「广」从「黄」，「黄」是声符。「宀」象房屋之形，「广」象比「宀」更简单的建筑（裘锡圭），所以本义是大屋。段玉裁认为「广」的本义是四周没有墙壁的大屋，他注说「殿谓堂无四壁……覆乎上者曰屋，无四壁而有大覆盖，其所通者宏远矣，是曰广」，姑备一说。金文里的「广」多从「广」，间或从「宀」，后期金文或讹作从「厂」，因为「广」「厂」形近所以相混。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「廣」條；香港中文大學《漢語多功能字庫》「廣」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BB%A3（2026-11-11 查閱）"},
  "19891_至_Z_說文‧至部": {"headline": "箭射出去，落在它该到的地方。", "original_meaning": "「至」的本义是到达。", "structure_desc": "甲骨文的「至」从「矢」从「一」，以「一」表示箭矢所至，字象箭矢到达其所止之处。另外「矢」可能也是「至」字的声符，所以本义是到达。《合集》32372 另有一字与倒「侯」同形，但确为「至」字（季旭升）。《说文解字》说「至，鸟飞从高下至地也。从一。一，犹地也。象形」，是就鸟从高处飞到地面的样子立说的。后来「至」表示到达、极致，又表示周到，比如「周至」「宾至如归」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「至」條；香港中文大學《漢語多功能字庫》「至」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%87%B3（2026-11-11 查閱）"},
  "15655_照_Z_說文‧火部": {"headline": "火烧着，把东西照亮。", "original_meaning": "「照」的本义是照耀、光线照射。", "structure_desc": "「照」本作「㷖」，见于金文。《说文解字》说「㷖，明也。从火，昭声」，「火」表意，「昭」作声符，本义是照耀、光线照射。《易．恒》说「日月得天而能久照，四时变化而能久成」。「照」后来表示日光，又表示知晓、明白，《逸周书．武称》有「照其储」之语，朱右曾校释「照，训知」。又表示对照、比照，还表示关心、照料。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「照」條；香港中文大學《漢語多功能字庫》「照」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%85%A7（2026-11-11 查閱）"},
  "06704_买_Z_小篆": {"headline": "用网兜着贝壳去交易。", "original_meaning": "「买」的本义是买进、购置。", "structure_desc": "「买」的繁体是「買」，甲骨文和金文都从「贝」从「网」。商承祚《殷契佚存》说「象以网取贝之形」。从常识看，古人于市上买物，总要货币（贝），又或需以网携带，所以从「贝」从「网」。《说文解字》说「买，市也。从网、贝。《孟子》曰：登垄断而网市利」，段玉裁注「市者，买物之所。因之买物亦言市」。甲骨文里「买」用作人名，金文用作国族名和人名。秦简始见买卖之义，《睡虎地秦简．秦律十八种》有「有买及卖也，各婴其价」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「買」條；香港中文大學《漢語多功能字庫》「買」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B2%B7（2026-11-11 查閱）"},
  "19071_线_Z_小篆": {"headline": "两根丝线并在一起。", "original_meaning": "「线」的本义是细缕、用丝线作成的绳。", "structure_desc": "「线」本作「綫」，从「糸」从「戔」，「戔」作声符，本义是用棉、毛、丝、麻、金属等材料制成的细缕。《说文解字》说「线，缕也。从糸，戔声。线，古文綫」。《周礼．天官．缝人》说「缝人掌王宫之缝线之事」，郑玄注引郑司农说「线，缕也」。后来「线」表示细长如线的东西，南朝梁范云《送别诗》有「东风柳线长」；又用作量词，限于数词「一」，表示细微。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「綫」條（今字作「线」）；香港中文大學《漢語多功能字庫》「線」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B7%9A（2026-11-11 查閱）"},
  "07623_切_Z_說文‧刀部": {"headline": "一刀下去，把东西割开。", "original_meaning": "「切」的本义是用刀切割。", "structure_desc": "「切」从「刀」从「七」，「七」作声符，「刀」表意，本义是用刀切割。《说文解字》说「切，刌也。从刀，七声」。「切」的初文疑为「七」，小篆开始才出现从「刀」以「七」为声符的「切」。后来「切」表示切合、紧密，又表示急切，比如「亲切」「迫切」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「切」條；香港中文大學《漢語多功能字庫》「切」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%87（2026-11-11 查閱）"},
  "15533_热_Z_小篆": {"headline": "火烤着，热气往上冒。", "original_meaning": "「热」的本义是温度高。", "structure_desc": "「热」的繁体是「熱」，从「火」从「埶」，「埶」作声符，「火」表意，本义是温度高。《说文解字》说「热，温也。从火，埶声」。《诗经．大雅．桑柔》有「谁能执热，逝不以濯」，郑玄笺「当如手执热物之用濯」。「热」作动词表示使它热，《庄子．齐物论》说「大泽焚而不能热，河汉冱而不能寒」；又表示燃烧。「热」后来也用作中医名词，表示热症、热邪。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「熱」條；香港中文大學《漢語多功能字庫》「熱」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%86%B1（2026-11-11 查閱）"},
  "18129_笑_Z_說文‧竹部": {"headline": "竹枝摇动，弯着身子。", "original_meaning": "「笑」的本义是因喜悦而开颜或发声。", "structure_desc": "「笑」从「竹」从「夭」，本义是因喜悦而开颜或发声。「笑」在古文字中从「艸」从「犬」，后小篆讹为从「竹」从「犬」。唐代李阳冰刊定《说文》改为从「竹」从「夭」，成为今天「笑」字之所本。《增韵．笑韵》说「笑，喜而解颜启齿也」。典籍里有用本义的，《邓析子．无厚》说「心悦者颜不能笑」。简帛文字也用本义，《马王堆．老子乙本卷前古佚书．称》有「至乐不笑」。后来「笑」引申为欣羡、喜爱。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「笑」條；香港中文大學《漢語多功能字庫》「笑」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AC%91（2026-11-11 查閱）"},
  "09620_委_Z_說文‧女部": {"headline": "禾苗的穗子垂下来。", "original_meaning": "「委」的本义是委曲、曲折，引申为委托、交给。", "structure_desc": "「委」的甲骨文从「禾」从「𠃊」（或「匸」），会出禾苗弯曲之意，是委曲、委积的「委」的本字（施谢捷）。战国后期始见从「禾」从「女」的字形，《说文》小篆相同。徐铉说「委，曲也。取其禾谷垂穗委曲之貌，故从禾」。《汉书．成帝纪》有「流星光烛地，长四五丈，委曲蛇形」。后来「委」引申表示随顺，又表示委托、交给，中山王鼎有「是以寡人委任之邦」之语。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「委」條；香港中文大學《漢語多功能字庫》「委」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A7%94（2026-11-11 查閱）"},
  "19395_考_Z_說文‧老部": {"headline": "老字头上加了个记号，就是「考」。", "original_meaning": "「考」的本义是父亲。", "structure_desc": "「考」的本义是父亲，西周早期本来用「老」字表达这个词义。由于「年老」和「父亲」两个词同时用「老」字表示，为区别两者，因此在「老」上加注声符「丂」，分化出「考」字（林澐）。从「老」「丂」声的「考」字一般略去「匕」形（象手杖形），所以许慎认为「考」字从「老」省，《说文解字》说「考，老也。从老省，丂声」。许慎在《说文解字叙》里论「转注」时举「老」「考」二字为例，说「建类一首，同意相受」，但两字究竟是什么关系，两千年来一直没有定论。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「考」條；香港中文大學《漢語多功能字庫》「考」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%83（2026-11-11 查閱）"},
  "25280_需_Z_說文‧雨部": {"headline": "天下着雨，只能站着等。", "original_meaning": "「需」的本义是下雨不能出门，停下等待。", "structure_desc": "「需」的金文从「雨」从「天」，表示外面下雨，不利出行，得站着等待雨下完。《说文解字》说「需，𩓣也。遇雨不进止𩓣也。从雨，而声。《易》曰：云上于天需」，引的是《易》「需」卦的《象》辞。孔颖达疏说「云上于天，是天之欲雨，待时而落」。「需」字等待的意思渐渐少用，反而用「须」来表示，所以后世须待的「须」是「需」的假借字。「需」也是六十四卦中的第五卦。后来「需」有需要、索取之义。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「需」條；香港中文大學《漢語多功能字庫》「需」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9C%80（2026-11-11 查閱）"},
  "18263_算_Z_說文‧竹部": {"headline": "一把竹筹，一五一十地数。", "original_meaning": "「算」的本义是数目。", "structure_desc": "「算」从「竹」从「具」，本义是数目。《说文解字》说「算，数也。从竹从具。读若筭」。《礼记．檀弓下》有「辟踊，哀之至也，有算」，郑玄注「算，数也」，孔颖达疏说「若不裁限，恐伤其性，故辟踊有算」，说的是哀泣跳动的次数要有限制，可见古人确以竹筹计数。后来「算」表示计算、谋划，《孙子．计》说「未战而庙算胜者，得算多也」。又表示料想，还用来指寿命。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「算」條；香港中文大學《漢語多功能字庫》「算」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AE%97（2026-11-11 查閱）"},
  "09102_城_Z_說文‧土部": {"headline": "用土筑起城墙，围住城邑。", "original_meaning": "「城」的本义是城邑四周用作防守的墙垣。", "structure_desc": "「城」西周金文从「𩫖」从「成」，「成」亦是声符，为《说文》籀文所本。「𩫖」象城郭之形，「成」象以斧钺守卫城邑之形，本义是城邑。东周金文则从「土」从「成」，象以土筑成的城邑；「成」的一小竖或与「土」旁合用竖笔。金文表示长城，是用以防守的墙垣，𠫑羌钟有「长城」之语。「城」的本义为都邑四周用作防守的墙垣，引申指墙垣内的区域，后泛指一般城市。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「城」條；香港中文大學《漢語多功能字庫》「城」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9F%8E（2026-11-11 查閱）"},
  "08232_周_Z_說文‧口部": {"headline": "一块雕着花纹的玉。", "original_meaning": "「周」的本义是雕琢玉器。", "structure_desc": "「周」字甲骨文的释义有二：一说以为象田畴之貌（鲁实先），一说则以为「周」是「雕」「琱」的初字，象有雕饰的玉器（孙常叙）。《说文解字》说「琱，治玉也。一曰石似玉。从玉周声」。由于「周」字充当「实」「画」等字的部件，似乎较难理解为田畴，且金文中「周」有用作「琱」的本义，所以采用后一种说法。「周」因借用作国名，金文又在字形下方另加「口」形，甲金文国名之字往往加「口」作分化符号。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「周」條；香港中文大學《漢語多功能字庫》「周」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%91%A8（2026-11-11 查閱）"},
  "25385_革_Z_說文‧革部": {"headline": "一张刮掉毛的兽皮。", "original_meaning": "「革」的本义是兽皮、皮革。", "structure_desc": "「革」的金文象割剥后的兽皮展列之形，上象头，中象身，下象尾，其身部后渐讹为「臼」形（象双手形），本义是兽皮（参《金文形义通解》）。也有一种说法认为金文象兽头角足尾之形，并以双手治去毛（林义光、高田忠周、高鸿缙）。初义是皮革，引申而指甲胄之属，如《礼记．中庸》说「衽金革，死而不厌，北方之强也」。金文里还多用为「勒」，即马头络衔，康鼎有「命汝幽黄、镳革」之语。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「革」條；香港中文大學《漢語多功能字庫》「革」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9D%A9（2026-11-11 查閱）"},
  "12596_整_Z_說文‧攴部": {"headline": "把东西收拾齐整。", "original_meaning": "「整」的本义是整齐。", "structure_desc": "「整」的金文从「攴」从「束」从「正」，「正」亦声，构形的初义不明，常表示整齐。「攴」表示敲打，「束」表示捆扎，「正」表示不偏，合起来是收拾整齐的意思。《说文解字》说「整，齐也。从攴从束从正，正亦声」。《诗经．小雅．六月》有「玁狁匪茹，整居焦获」，郑玄笺说「乃自整齐而处周之焦获」。后来「整」表示端方、端庄，又表示整理、整治，《诗经．大雅．皇矣》有「王赫斯怒，爰整其旅」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「整」條；香港中文大學《漢語多功能字庫》「整」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%95%B4（2026-11-11 查閱）"},
  "13308_格_Z_說文‧木部": {"headline": "树长得高，长成一副骨架。", "original_meaning": "「格」的本义是树木高长。", "structure_desc": "「格」从「木」从「各」，「木」是意符，「各」是声符，本义是树木高长。《说文．木部》说「格，木长皃。从木，各声」。「长」字古有「高」义，现代湘方言仍把高个儿的男人叫「长子」，古书中的「长亭」「短亭」即高亭、矮亭（孙雍长《长亭短亭考》）。过去认为《说文》的「木长」是树枝长，未必正确，如徐锴《繫传》说「亦谓树高长枝为格」。白川静认为树枝的形状像骨架，所以有「骨格」「骨骼」一类词汇。后来「格」引申为架子、格式、标准。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「格」條；香港中文大學《漢語多功能字庫》「格」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A0%BC（2026-11-11 查閱）"},
  "09421_复_Z_說文‧夊部": {"headline": "从洞口进进出出。", "original_meaning": "「复」的本义是往返、来回。", "structure_desc": "「复」的繁体是「復」，金文从「彳」从「复」，「复」作声符，或从「辵」。「复」会出足趾从土室（穴居之处）进出的意思，本义是进出往来（陈永正、徐中舒）、回来，后来加从「彳」或「辵」以表行走之意。张日昇则认为「复」象二豆相合之形，豆中食物由一器倾覆至另一器，故有往来反复之意，可备一说。《说文解字》说「复，往来也。从彳，复声」。引申为反复、再、又。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「復」條；香港中文大學《漢語多功能字庫》「復」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%A9（2026-11-11 查閱）"},
  "09035_型_Z_說文‧土部": {"headline": "挖土成模，用来浇铸器物。", "original_meaning": "「型」的本义是法度、准则。", "structure_desc": "「型」的金文从「㓝」从「土」，「㓝」或从「刃」。「㓝」与「刑」同，作「型」的声符；「㓝」「型」都从「井」声，古代井边围栏交错有序，所以从「井」取其有秩序、法度之意，本义是法度、准则。「型」的异体从「犬」。金文「型」通读作「刑」，表示法度、准则，中山王鼎有「考度惟型」之语，意指考察量度事物均有准则可循（张世超）。又表示刑罚，中山王圆壶有「大去型罚」之语。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「型」條；香港中文大學《漢語多功能字庫》「型」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9E%8B（2026-11-11 查閱）"},
  "07427_元_Z_說文‧一部": {"headline": "人的头顶上那一块。", "original_meaning": "「元」的本义是头，引申为首位、开始。", "structure_desc": "「元」的甲骨文和金文从「人」从一圆点或方框，象人形而突出头部，所以本义是头，引申为首位、首次、开始。甲骨文和金文象人头的圆点或方框，或简省为一横；古文字往往在一横上再加一短横为饰笔，发展为小篆、楷书的「元」。「元」和「兀」是一字之分化（林义光）。后来「元」表示第一、首要，比如「元年」「元首」，又表示根本、开始。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「元」條；香港中文大學《漢語多功能字庫》「元」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%83（2026-11-11 查閱）"},
  "12136_推_Z_說文‧手部": {"headline": "用手把东西往前送。", "original_meaning": "「推」的本义是手向外用力使物体前移。", "structure_desc": "「推」从「手」从「隹」，「隹」作声符，「手」表意，本义是手向外用力使物体前移。《说文解字》说「推，排也。从手，隹声」。《左传．襄公十四年》有「或輓之，或推之，欲无入，得乎」。唐韩愈《南山诗》有「褰衣步推马，颠踬退且后」。后来「推」引申为推广、扩展，《礼记．祭义》说「推而放诸东海而准」，《孟子．梁惠王上》说「故推恩足以保四海」。又引申为排除、除去。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「推」條；香港中文大學《漢語多功能字庫》「推」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8E%A8（2026-11-11 查閱）"},
  "21504_血_Z_說文‧血部": {"headline": "器皿里盛着的血。", "original_meaning": "「血」的本义是祭祀时献给神明的牲畜的血。", "structure_desc": "「血」是象形字，从「皿」，中间的一圈或一点象血形，本义是祭祀时献给神明的牲畜的血（许慎）。甲骨文里「血」与「盟」字形很接近，惟有两者「皿」上所盛的东西有别，但在卜辞中常有彼此换用的情况。古人祭祀时要用牲畜的血血祭，所以这个字从盛血的器皿「皿」。《说文解字》说「血，祭所荐牲血也。从皿，一象血形」。后来「血」引申为有血缘关系的亲属，又表示血液。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「血」條；香港中文大學《漢語多功能字庫》「血」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A1%80（2026-11-11 查閱）"},
  "12798_显_Z_小篆": {"headline": "在太阳底下细看丝线。", "original_meaning": "「显」的本义是显明、显现。", "structure_desc": "「显」的繁体是「顯」，金文从「日」从顶部相连的「丝」从「页」，「页」象人形而突显头部，全字象人在日下视丝的样子。丝线幼细难视，所以需要在太阳之下才能显明，本义是显明、显现（参林义光）。战国文字的「顯」或省写作「㬎」。《说文解字》说「显，头明饰也。从页，㬎声」，把本义说成是头上的明饰。后来「显」表示明显、显著，又表示显贵、显赫，比如「显著」「display」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「顯」條；香港中文大學《漢語多功能字庫》「顯」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A1%AF（2026-11-11 查閱）"},
  "22382_议_Z_小篆": {"headline": "说出合宜的话。", "original_meaning": "「议」的本义是合适的言谈。", "structure_desc": "「议」的繁体是「議」，从「言」从「义」，「义」作声符。段玉裁认为「义」声原则上带有合适的含义，因此「议」字的本义是合适的言谈。他说「议者，谊也。谊者，人所宜也。言得其宜之谓议」，言下之意，「议」有「谊」的意思，「谊」则指人所适合做的事，所以「议」的本义就是「言得其宜」。刘钧杰以「言」「议」为同源词，可备一说。甲骨文里并没有「议」字。金文中「议」借为「仪」，左行议率戈有「左行仪率戈」之语。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「議」條；香港中文大學《漢語多功能字庫》「議」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%AD%B0（2026-11-11 查閱）"},
  "06933_何_Z_說文‧人部": {"headline": "一个人肩上扛着扁担。", "original_meaning": "「何」的本义是担荷、负荷。", "structure_desc": "「何」的甲骨文从「人」从一圆点，象人的肩上扛着锄头或扁担之形，本义是担荷、负荷。《说文解字》说「何，儋也。从人，可声」。金文或不从圆点而从「戈」，「戈」是「何」的声符；「戈」「何」上古皆为歌部字，声母皆为牙音。后期金文不从「戈」而从「可」，「可」也是「何」的声符。甲骨文、金文里「何」用作人名。战国竹简里「何」用作疑问代词，《上博楚竹书三．周易》有「上九：何？天之衢，亨」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「何」條；香港中文大學《漢語多功能字庫》「何」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%95（2026-11-11 查閱）"},
  "17978_空_Z_說文‧穴部": {"headline": "洞穴里凿出的孔。", "original_meaning": "「空」的本义是孔洞、空隙。", "structure_desc": "「空」从「穴」从「工」，「工」作声符，「穴」表意，本义是孔洞。《说文解字》说「空，窍也。从穴，工声」，段玉裁注「今俗语所谓孔也」，又说「空、孔古今字」。《庄子．秋水》有「四海之天地之间也，不似礨空之在大泽乎」，陆德明释文「空，音孔。礨孔，小穴也」。《汉书．王贡两龚鲍传》有「衣又穿空，父子夫妇不能相保」。金文的「空」通假作「容」，表示容量，库啬夫鼎有「容二斗」。后来「空」引申为空间、空隙，又表示空虚、不实。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「空」條；香港中文大學《漢語多功能字庫》「空」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A9%BA（2026-11-11 查閱）"},
  "18558_精_Z_說文‧米部": {"headline": "从米里挑选出最好的。", "original_meaning": "「精」的本义是择、挑选。", "structure_desc": "「精」从「米」从「青」，「青」作声符。「精」的字书都从米，但《说文解字》释为「精，择也。从米，青声」，本义是挑选。段玉裁注说「米形與Selectors同意，故曰择也」，古人挑选谷物要用到米，因此「米」作意符。这个字后来引申出精良、精密、精细的意思，又表示精神、精力。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「精」條；香港中文大學《漢語多功能字庫》「精」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B2%BE（2026-11-11 查閱）"},
  "14457_油_Z_說文‧水部": {"headline": "一条从山里流出来的大河。", "original_meaning": "「油」的本义是水名，即今湖南的渌水。", "structure_desc": "「油」从「水」从「由」，「由」作声符。《说文解字》说「油，水。出武陵孱陵西，东南入江。从水，由声」，本义是水名。金文里的「由」是在口中加一横画，金文通假为「淯」，用作水名。战国文字「油」又用作「由」的通假字。因为用动物的脂膏点灯燃烧时油多呈黑色且流动，古人又以「油」表示这种液态的油脂。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「油」條；香港中文大學《漢語多功能字庫》「油」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B2%B9（2026-11-11 查閱）"},
  "08894_图_Z_小篆": {"headline": "把城邑和郊野画在一张版上。", "original_meaning": "「图」的本义是版图、地图。", "structure_desc": "「图」的繁体是「圖」，金文从「囗」从「啚」，「啚」是「鄙」的初文，象仓廪设在田野边郊，所以有边鄙之意；「囗」象城邑之形，杨树达认为既有城邑，又有边鄙，所以「图」的本义当为版图。也有一说认为字象以「囗」围绕鄙邑绘画地图之意（何琳仪）。《说文解字》说「图，画计难也。从囗从啚。啚，难意也」；按图谋画计为「图」的引申义，因为古人谋画之事往往要借助图籍，所以「图」又从图籍引申出谋画的意思。金文用作本义表示版图。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「圖」條；香港中文大學《漢語多功能字庫》「圖」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%96（2026-11-11 查閱）"},
  "22561_象_Z_說文‧象部": {"headline": "侧面站着的大象，长鼻子特别突出。", "original_meaning": "「象」的本义是大象。", "structure_desc": "「象」的甲骨文和金文象侧面的大象之形，突出大象的长鼻子，本义是大象。《说文解字》说「象，长鼻牙，南越大兽，三年一乳，象耳、牙、四足之形」。韩非认为由于北方少见大象，人们凭着象骨想像其形状，所以凡意想、想像都称为「象」。《韩非子．解老》说「人希见生象也，而得死象之骨，按其图以想其生也，故诸人之所以意想者皆谓之象也」。后来「象」引申为抽象、形象之「象」，又增「人」旁分化出「像」字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「象」條；香港中文大學《漢語多功能字庫》「象」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B1%A1（2026-11-11 查閱）"},
  "13305_根_Z_說文‧木部": {"headline": "扎在土里的那一段。", "original_meaning": "「根」的本义是植物生长在土中的部分。", "structure_desc": "「根」从「木」从「艮」，「艮」作声符，本义是植物生长在土中的部分。《说文解字》说「根，木株也。从木，艮声」。先秦文献用其本义，《左传．文公七年》有「若去之，则本根无所庇廕矣」，曹植《七步诗》有「本是同根生，相煎何太急」。唐诗也用本义，李白《为吴王谢责赴行在迟滞表》有「落叶坠于本根」。「根」也用来作物体的基部，庾信《明月山铭》有「云出山根」。后来「根」多引申为事物的本源。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「根」條；香港中文大學《漢語多功能字庫》「根」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A0%B9（2026-11-11 查閱）"},
  "07877_包_Z_說文‧包部": {"headline": "胎儿裹在胎衣里。", "original_meaning": "「包」的本义是包孕，是「胞」的初文。", "structure_desc": "「包」的金文从「勹」从「巳」，「勹」亦是声符，「巳」为未成形之子，「勹」为胎衣，「包」象胎儿于胎衣中之形，本义是包孕，是「胞」的初文（林义光、马叙伦、杨树达）。金文从「巳」，「勹」亦声，象胎儿裹于腹中，小篆上承金文之形。《说文解字》说「包，象人褢妊，巳在中，象子未成形也」，并详述男左行三十、女右行二十的成孕起算法。后来「包」由包孕的本义，引申出包裹、包含，以及包揽、承包的意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「包」條；香港中文大學《漢語多功能字庫》「包」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8C%85（2026-11-11 查閱）"},
  "22421_试_Z_小篆": {"headline": "用言语去试用、去考察。", "original_meaning": "「试」的本义是使用、任用。", "structure_desc": "「试」的繁体是「試」，从「言」从「式」，「式」作声符，「言」表意，本义是使用、任用。《说文解字》说「试，用也。从言，式声」，《礼记．缁衣》引孔子语后有「刑不试而民咸服」，郑玄注「试，用也」。后来「试」表示尝试，《易．无妄》说「无妄之药，不可试也」；也表示检验，《书．舜典》说「敷奏以言，明试以功」，孔传说诸侯各使陈述治礼之言，明试其言以要其功。后来「试」表示试探，又特指科举考试。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「試」條；香港中文大學《漢語多功能字庫》「試」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A9%A6（2026-11-11 查閱）"},
  "07931_医_Z_說文‧匸部": {"headline": "治病要用酒，所以字里有酒。", "original_meaning": "「医」的本义是治病的人、医生。", "structure_desc": "「医」的繁体是「醫」，从「酉」从「殹」，「殹」作声符，表示治病的人。《说文解字》说「医，治病工也。殹，恶姿也。医之性然，得酒而使。从酉」，并说「一曰：殹，病声。酒所以治病也。《周礼》有医酒。古者巫彭初作医」。古人治病要用酒来送服药物，所以字里带一个酒器「酉」。《礼记．曲礼下》说「医不三世，不服其药」。后来「医」表示医术、医学。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「醫」條；香港中文大學《漢語多功能字庫》「醫」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%86%AB（2026-11-11 查閱）"},
  "09415_备_Z_小篆": {"headline": "背上背着装满箭矢的箭袋。", "original_meaning": "「备」的本义是准备、具备。", "structure_desc": "「备」的甲骨文和金文从「人」从「𤰈」，「𤰈」亦声。「𤰈」象箭矢插在盛器中，箭羽露在外面便于抽取，文献作「箙」，本义是盛矢器。从甲骨文、金文到简帛文字，人形一律背向箭袋，象人背负箭袋之形，以便随时射箭，引申出准备、具备之意（白川静）。肩负箭囊表示做好作战准备，进而泛指各种准备、防备；事前做好准备需要各方面的周到安排，所以「备」又有「全部」「全都」之义。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「備」條；香港中文大學《漢語多功能字庫》「備」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%82%99（2026-11-11 查閱）"},
  "08202_告_Z_說文‧告部": {"headline": "张开嘴伸出舌头说话。", "original_meaning": "「告」的本义是说话、告诉、舌辩。", "structure_desc": "「告」的甲骨文从「舌」从一圆点，「告」字是把「舌」字的中竖向上突出而产生的分化字（张玉金），象张口伸舌，本义是说话、告诉、舌辩。也有一种说法认为「告」字从「牛」从「口」，会以牛祭神并且祝告之意，引申为报告（张日昇），可备一说。甲骨文里「告」用作祭名，读作「祰」，《合集》1166甲有「告于太甲、祖乙」，表示对太甲、祖乙进行祰祭。甲骨文、金文又用作本义表示报告。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「告」條；香港中文大學《漢語多功能字庫》「告」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%91%8A（2026-11-11 查閱）"},
  "24689_钱_Z_小篆": {"headline": "一把像铁铲的农具。", "original_meaning": "「钱」的本义是农具，形似铁铲。", "structure_desc": "「钱」的繁体是「錢」，从「金」从「戔」，「戔」作声符，本义是农具，形似铁铲。《说文解字》说「钱，铫也。古田器。从金，戔声。《诗》曰：庤乃钱镛」，曹操《步出夏门行．冬十月》有「钱镡停置，农收积场」。后来「钱」常表示货币。《国语．周语下》说「景王二十一年，将铸大钱」，韦昭注「钱者，金币之名，所以贸易买物，通财用者也。古曰泉，后转曰钱」。「钱」还进一步引申表示费用。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「錢」條；香港中文大學《漢語多功能字庫》「錢」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%8C%A2（2026-11-11 查閱）"},
  "26188_验_Z_小篆": {"headline": "拉弓试马，看它跑得怎样。", "original_meaning": "「验」的本义是马名，后来表示验证。", "structure_desc": "「验」的繁体是「驗」，从「马」从「僉」，「僉」作声符。《说文解字》说「验，马名。从马，僉声」，本义是马名，后来常表示验证。《韩非子．南面》说「言无端末，辩无所验者，此言之责也」。《史记．商君列传》说「商君之法，舍人无验者坐之」。「验」也可表示证据、检查，《楚辞．九章．惜往日》有「弗参验以考实兮」。还表示效果和徵兆，《淮南子．主术训》说「验在近而求之远，故弗得也」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「驗」條；香港中文大學《漢語多功能字庫》「驗」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A9%97（2026-11-11 查閱）"},
  "17089_省_Z_說文‧眉部": {"headline": "眼睛里长出东西，看不清楚。", "original_meaning": "「省」的本义是一种目疾、眼病。", "structure_desc": "「省」的甲骨文和金文从「屮」从「目」，表示眼睛生出一个东西，被东西挡住，看不清楚眼前的事物。「屮」是「草」的初文，表示眼睛长出的东西，就像地上长草（沈培）。本义是一种目疾、眼病。甲骨文、金文的这个字是「眚」「省」的初文，后来字形分化为二：一、把「屮」改写为与它音近的「生」，成为从「生」声、从「目」义的「眚」；二、借目病义的「眚」来表示省察的「省」，把「屮」改写为「少」，成为「省」，表示省察。也有一说认为「省」象视察草木之形，本义是视察（季旭升）。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「省」條；香港中文大學《漢語多功能字庫》「省」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9C%81（2026-11-11 查閱）"},
  "07479_具_Z_說文‧廾部": {"headline": "两手把鼎举起来。", "original_meaning": "「具」的本义是准备。", "structure_desc": "「具」的甲骨文从「鼎」从「廾」（同「𠬞」，象一双手），象两手举起鼎的样子（陈伟湛、白川静、刘兴隆、沈培）。鼎是盛食物的器皿，会准备食物以供给宾客（季旭升），或用于祭祀，所以本义是准备，《广雅．释诂》说「具，备也」。甲骨文所从的「鼎」到金文讹变为「贝」，金文的「贝」到小篆又讹变为「目」；楷书「具」下部的「𠆣」是从甲金篆文的「廾」形讹变而来。古时移动大鼎要用木棒穿过鼎的双耳合力搬运。用鼎盛食物做好祭祀准备称为「具」，后来「具」引申出皆具、具体，又用来指各种器具。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「具」條；香港中文大學《漢語多功能字庫》「具」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%B7（2026-11-11 查閱）"},
  "08107_叫_Z_說文‧口部": {"headline": "张口大声呼喊。", "original_meaning": "「叫」的本义是呼喊。", "structure_desc": "「叫」从「口」从「丩」，「丩」作声符，本义是呼喊。《说文解字》说「叫，嘑也。从口，丩声」。《诗经．小雅．北山》有「或不知叫号，或惨惨劬劳」，毛传说「叫，呼」。后来「叫」表示鸣叫，马融《长笛赋》说「猿猱昼吟，鼯鼠夜叫」。又表示招呼，王逸《九思．疾世》有「叫我友兮配耦」。近现代汉语中「叫」还表示称作、名称是，《红楼梦》第6回说「他就叫小红」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「叫」條；香港中文大學《漢語多功能字庫》「叫」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%AB（2026-11-11 查閱）"},
  "08120_司_Z_說文‧司部": {"headline": "主管一件事的人。", "original_meaning": "「司」的本义是主管、主宰。", "structure_desc": "「司」的甲骨文字形释义未有定论。刘兴隆释字象用手罩口上大聲说话，会为主管之事，本义为主管。季旭昇认为那一圆点象权杖之形，所以有职司、主宰之义。徐中舒释「司」的上部象倒置的柶（古代舀取食物的礼器），以倒柶覆于口上会意为进食；氏族社会中食物为共同分配，负责食物分配的人也称为「司」。此外，甲骨文的「司」与「后」字形相近相混，唐兰认为司、后二字本同形，待考。后来「司」表示掌管、主管，又表示古代官名。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「司」條；香港中文大學《漢語多功能字庫》「司」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%B8（2026-11-11 查閱）"},
  "14504_注_Z_說文‧水部": {"headline": "把液体从一个器皿倒进另一个。", "original_meaning": "「注」的本义是灌注。", "structure_desc": "「注」的甲骨文和金文象用手将一个器皿里的液体注入另一个器皿之内，如《合集》28012（裘锡圭）。它的简体有省去手形的（如《合集》5458），也有省去受注器形的（如《合集》28030）。本义是灌注。《说文解字》说「注，灌也。从水，主声」。甲骨文的「注」表示其引申义，读为「驻」，以注液体入某器来比喻派人到某地，如《合集》28012有「勿注襄人」，意谓不必派人到襄地。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「注」條；香港中文大學《漢語多功能字庫》「注」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B3%A8（2026-11-11 查閱）"},
  "16958_百_Z_說文‧𦣹部": {"headline": "「一百」的合文。", "original_meaning": "「百」的本义是数词「百」。", "structure_desc": "「百」的甲骨文和金文是「一」「白」的合文。古代借「白」来表示数词「百」，加「一」于「白」上表示「一百」。因为古人读「一百」习惯省去「一」字，所以「一百」的合文就成了单字「百」。《说文解字》说「百，十十也。从一、白。数，十百为一贯。相章也」。「百」字中部又加「入」形，以区分「白」与「百」。商代后期有在「白」字上加「二」以为「二百」合文、加「三」以为「三百」合文的写法（周法高）。后来「百」用来表示众多、全部。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「百」條；香港中文大學《漢語多功能字庫》「百」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%99%BE（2026-11-11 查閱）"},
  "12527_支_Z_說文‧支部": {"headline": "一只手拿着半根竹子。", "original_meaning": "「支」的本义是去掉竹子的枝条。", "structure_desc": "「支」的小篆如手拿着半根竹子，本义是去掉竹子的枝条，后来写作「枝」。《说文解字》说「支，去竹之枝也。从手持半竹」，所以从「手」。「支」后来引申为支持、支撑，又表示分支、支派，比如「支线」「支援」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「支」條；香港中文大學《漢語多功能字庫》「支」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%94%AF（2026-11-11 查閱）"},
  "25222_集_Z_說文‧雥部": {"headline": "几只鸟停在树上。", "original_meaning": "「集」的本义是聚集。", "structure_desc": "「集」古作「雧」，从「木」从「隹」，或从「鸟」，象鸟在树上聚集的样子，后省作一个「隹」在「木」上，所以本义是聚集，引申为集合、集体。《说文解字》说「集，羣鸟在木上也。从雥从木。集，雧或省」。后来「集」表示鸟聚在树上，引申为众人聚集，又表示集合、集会。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「雧」條（今字作「集」）；香港中文大學《漢語多功能字庫》「集」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9B%86（2026-11-11 查閱）"},
  "13073_村_Z_小篆": {"headline": "树木旁边住着人家。", "original_meaning": "「村」的本义是村庄。", "structure_desc": "「村」从「木」从「寸」，「寸」作声符，「木」表意，本义是村庄。晋陶潜《桃花源记》有「村中闻有此人，咸来问讯」。《说文解字》收的是「邨」，释为「邨，地名。从邑，屯声」，臣铉等注「今俗作村，非是」。「邨」是村落地名，今字「村」是它的俗写，与「邑」旁所说的地名同源。后来「村」引申出村野、粗俗的意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「邨」條；香港中文大學《漢語多功能字庫》「村」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9D%91（2026-11-11 查閱）"},
  "16631_男_Z_說文‧男部": {"headline": "在田里用力耕种的人。", "original_meaning": "「男」的本义是男子、丈夫。", "structure_desc": "「男」的甲骨文和金文从「田」从「力」，「力」象耒耜之形，会出用耒耜在田中耕作的意思。因为农耕者为男性，所以用「男」作为男子的称呼（徐中舒）。《说文解字》说「男，丈夫也。从田从力。言男用力于田也」。段玉裁注「人长一丈，故曰丈夫」，又引《白虎通》说「男，任也。任，功业也」，指出古音男与任相同。甲骨文表示男服，金文也表示男服，是古代的爵名，《书．康诰》有「侯、甸、男、邦、采、卫」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「男」條；香港中文大學《漢語多功能字庫》「男」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%B7（2026-11-11 查閱）"},
  "22001_許_Z_說文‧言部": {"headline": "开口答应一声。", "original_meaning": "「许」的本义是答应、认可。", "structure_desc": "「许」从「言」从「午」，「午」作声符。一说以为「午」亦是意符，「午」象捣粟之杵，字的本义为舂谷时送杵之声，后假借为许可之「许」（杨树达、戴家祥）。许慎则以「听」训「许」，《说文解字》说「许，听也。从言，午声」，段玉裁改为「听言也」，注云「听从之言也。耳与声相入曰听，引伸之凡顺从曰听」。金文用本义表示允许、认可，中山王鼎有「是以寡人许之」。后来「许」表示许可、答应，又表示可能、大概，还用来表示估量的数目。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「許」條（今字作「许」）；香港中文大學《漢語多功能字庫》「許」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A8%B1（2026-11-11 查閱）"},
  "17658_示_Z_說文‧示部": {"headline": "一根杆子，标出神灵所在。", "original_meaning": "「示」的本义是祭祀时所用的神主牌位。", "structure_desc": "关于「示」字的释形说法很多，没有定论。一说认为设杆以祭天，以象征神祇（丁山）。二说象神主牌位形，如徐中舒说「象以木表或石柱为神主之形」。「示」下方的几点象祭祀拜祷时灌酒之状（姚孝遂）。没有数点的「示」与「主」原本同字，后来才分化为二，甲骨文里的「示」表示神主，又用作祭名。《说文解字》说「示，天垂象，见吉凶，所以示人也」，从「𠄞」和三垂，日月星也，说的是悬示以观天象以察吉凶的意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「示」條；香港中文大學《漢語多功能字庫》「示」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A4%BA（2026-11-11 查閱）"},
  "25093_际_Z_小篆": {"headline": "两堵墙合在一起的那道缝。", "original_meaning": "「际」的本义是两墙相接之处。", "structure_desc": "「际」的繁体是「際」，从「阜」从「祭」，「祭」作声符，「阜」表意。本义是两墙相接之处。《说文解字》说「际，壁会也。从阜，祭声」，段玉裁注「两墙相合之缝也。引申之，凡两合皆曰际」。引申表示交界处、边缘处，《左传．定公十年》有「居齐、鲁之际而无事，必不可矣」，《楚辞．天问》有「九天之际，安于安属」。又表示事物的分界、界限，《庄子．知北游》说「物物者与物无际」。还表示先后交接的时间。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「際」條；香港中文大學《漢語多功能字庫》「際」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9A%9B（2026-11-11 查閱）"},
  "06871_众_Z_小篆": {"headline": "太阳底下，一群人在干活。", "original_meaning": "「众」的本义是众人，引申为众多。", "structure_desc": "「众」的繁体是「眾」，甲骨文从「日」从三个人，象众人在日下劳作，本义是众人，引申为众多。李孝定说「字从日者，盖取众人相聚，日出而作之意」。金文所从的「日」形或讹变为「目」，为小篆所本。《说文解字》说「众，多也。从乑、目，众意」。甲骨文里「众」表示地位低的民众，《合集》50正有「贞：我其丧众人」，《合集》1 有「大令众人曰：协田」，表示命令众人合作耕田。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「眾」條；香港中文大學《漢語多功能字庫》「眾」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9C%BE（2026-11-11 查閱）"},
  "13281_校_Z_說文‧木部": {"headline": "木头做的镣铐。", "original_meaning": "「校」的本义是木制的刑具。", "structure_desc": "「校」从「木」从「交」，「交」作声符，本义是木制的刑具。《说文解字》说「校，木囚也。从木，交声」，段玉裁注「囚，系也。木囚者，以木羁之也」。《玉篇．木部》说「校，械也」。《周易．噬嗑》有「履校灭趾」，孔颖达疏「校，谓所施之械也」。后来「校」引申表示栅栏，《墨子．备穴》有「为铁校，卫穴四」；又表示考核、比较，汉代以后成为校对、考核的常用字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「校」條；香港中文大學《漢語多功能字庫》「校」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A0%A1（2026-11-11 查閱）"},
  "12653_断_Z_小篆": {"headline": "一把斧子，把东西截成两段。", "original_meaning": "「断」的本义是截断。", "structure_desc": "「断」的繁体是「斷」，从「斤」从「𢇍」，「𢇍」是「絕」的古文，本义是截断。《说文解字》说「断，截也。从斤从𢇍」，并收「𠸿」等古文形体，说「《周书》曰：𠸿𠸿猗无他技」。后来「断」表示截断、断开，又表示判断、决断，比如「判断」「果断」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「斷」條；香港中文大學《漢語多功能字庫》「斷」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%B7（2026-11-11 查閱）"},
  "12633_料_Z_說文‧斗部": {"headline": "一斗米，用斗来量。", "original_meaning": "「料」的本义是量，就是称量多少。", "structure_desc": "「料」的金文从「米」从「斗」，与小篆构形相同，会出以斗量米的意思，所以本义是量。段玉裁注「量者，称轻重也。称其轻重曰量，称其多少曰料，其义一也。知其多少，斯知其轻重矣」，又说「引申之，凡所量度预备之物曰料」。后来「料」泛指各种估量、推想，又可指材料、原料。战国竹简里「料」通作「劳」，指劳役，《清华简一．尹至》简5有「夏料民入于水曰战」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「料」條；香港中文大學《漢語多功能字庫》「料」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%99（2026-11-11 查閱）"},
  "08866_团_Z_小篆": {"headline": "围成一个圆。", "original_meaning": "「团」的本义是圆。", "structure_desc": "「团」的繁体是「團」，从「囗」从「专」，「专」作声符，「囗」表意，本义是圆。《说文解字》说「团，圜也。从囗，专声」，《玉篇．囗部》说「团，团圆也」。《墨子．经下》有「鉴团景一」，孙诒让闲诂说「盖谓鉴正圜则光聚于一」。后来「团」引申泛指圆形、球形的东西，又表示集合、聚集，如唐德宗《讨吴少诚诏》说「其所在百姓，能团结士众，讨除枭斩少诚者，准则封赏」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「團」條；香港中文大學《漢語多功能字庫》「團」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%98（2026-11-11 查閱）"},
  "06764_京_Z_說文‧京部": {"headline": "高高的楼台，下有木柱撑着。", "original_meaning": "「京」的本义是高大的楼台，引申为国都。", "structure_desc": "「京」的甲骨文和金文象高高的台观之形，上象宫观，下部象木结构的支柱（张日昇），本义是高大的楼台，引申出大的意思。《说文解字》说「京，人所为绝高丘也。从高省，丨象高形」。《尔雅．释诂》说「京，大也」。高大的宫观是帝王所居之处，所以「京」后来专门表示国都，如「京师」「京城」。「京」与「高」的形体相近，后来在「高」字下加「口」以作区别。金文里的「京师」即公刘建都之地，此后周王所居也就称作「京师」（李学勤）。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「京」條；香港中文大學《漢語多功能字庫》「京」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%AC（2026-11-11 查閱）"},
  "07643_创_Z_小篆": {"headline": "用刀砍开荆棘，受伤了。", "original_meaning": "「创」的本义是创伤、伤口。", "structure_desc": "「创」的繁体是「創」，古文作「刅」。「刅」是「创」的初文，象以刀斫荆刺之形，因为过程中容易受创伤，所以有创伤之意。后来加上「井」作声符，写作「刱」。「創」从「刀」从「仓」，「仓」作声符，《说文解字》以为「刅」的或体。《说文》说「刅，伤也。从刃从一。创，或从刀，仓声」，臣铉等注「今俗别作疮，非是也」。《战国策．燕策三》有「秦王复击轲，被八创」。后来「创」引申表示开始、创立，如《孟子．梁惠王下》说「君子创业垂统，为可继也」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「刅」條（今字作「创」）；香港中文大學《漢語多功能字庫》「創」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%89%B5（2026-11-11 查閱）"},
  "06612_且_Z_說文‧且部": {"headline": "俯视一块切肉的砧板。", "original_meaning": "「且」的本义是祭祀时陈放牲体的礼器。", "structure_desc": "「且」的甲骨文和金文象俯视的俎面，即王国维《说俎》所谓「象自上观下之形」（以区别于「自其侧观之」的「俎」字）。《说文解字》说「且，荐也。从几，足有二横，一其下地也」，其实「且」并不从「几」；中间的二横为俎面上的横格、阑界，并非足间的横（林义光、唐兰）。「俎」是古代用以切肉、盛载牲体和其他食物的礼器，后来专门表示切肉用的砧板。甲骨文里「且」假借为「祖」表示祖先，《合集》371正有「御于祖丁」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「且」條；香港中文大學《漢語多功能字庫》「且」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%94（2026-11-11 查閱）"},
  "22401_证_Z_小篆": {"headline": "把事情说出来作证。", "original_meaning": "「证」的本义是告发、检举。", "structure_desc": "「证」的繁体是「證」，从「言」从「登」，「登」作声符，「言」表意，本义是告发、检举。《说文解字》说「证，告也。从言，登声」。《论语．子路》记叶公对孔子说「吾党有直躬者，其父攘羊，而子证之」，用的就是这个意思。后来「证」表示验证、证实，《楚辞．九章．惜诵》有「所以证之不远」，王逸注「证，验也」。又表示凭证、证据，《大戴礼记．文王官人》有「平心去私，慎用六证」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「證」條；香港中文大學《漢語多功能字庫》「證」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%AD%89（2026-11-11 查閱）"},
  "19300_群_Z_說文‧羊部": {"headline": "羊喜欢合群，聚在一起。", "original_meaning": "「群」的本义是众多、众多同类相聚。", "structure_desc": "「群」的繁体是「羣」，金文从「羊」从「君」，「君」作声符，「君」以「尹」为声符，所以字或省从「尹」声。「群」以「羊」为意符，原因是羊喜欢合群，古人利用形旁「羊」来表示群体、众多的意思，这字的本义并非专指羊群（裘锡圭）。《说文解字》说「群，辈也。从羊，君声」，臣铉等注「羊性好群，故从羊」，段玉裁注引《犬部》说「羊为群，犬为独」，引申凡类聚之称。《国语．周语上》说「兽三为群，人三为众」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「羣」條（今字作「群」）；香港中文大學《漢語多功能字庫》「群」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BE%A4（2026-11-11 查閱）"},
  "06729_争_Z_小篆": {"headline": "两个人拖着一张犁。", "original_meaning": "「争」的本义是耕作，后来假借为争夺之义。", "structure_desc": "「争」的甲骨文从二「又」从一圆点，象犁耕之形（刘洪涛），或认为象耦耕之形（贾文）。圆点下方呈三角形，象农耕用的犁；「又」象手形。「争」字象两只手（代表两个人）拖动一个犁铧耕作的样子，本来表示耕作，后来假借为争夺的「争」，耕作之本义已废。陆懋德先生《中国发现之上古铜犁考》说「耜是犁头，而最初的牵用人拉……二人同时工作，一人在后扶犁，一人在前拉犁，如此二人并耦，是谓之耦也」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「爭」條；香港中文大學《漢語多功能字庫》「爭」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%88%AD（2026-11-11 查閱）"},
  "06611_专_Z_小篆": {"headline": "一只手，转动纺轮。", "original_meaning": "「专」的本义是转动纺轮。", "structure_desc": "「专」的繁体是「專」，甲骨文和金文都从「叀」从「又」。「叀」象纺轮形，「专」字象以手转纺轮之形，以表转动之义。徐中舒认为「专」是「转」的初文。《说文解字》说「专，六寸簿也。从寸，叀声。一曰：专，纺专」，前者说的是一种六寸长的竹简，后者说的就是纺专。甲骨文里「专」用作侯伯名、贞人名及地名，金文用作氏族徽号及人名。后来「专」引申出专一、专门、独占的意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「專」條；香港中文大學《漢語多功能字庫》「專」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%88（2026-11-11 查閱）"},
  "10007_字_Z_說文‧子部": {"headline": "在屋檐下养孩子。", "original_meaning": "「字」的本义是生育、抚养。", "structure_desc": "「字」的金文从「子」在「宀」下，「子」亦声，「宀」表意，表示在屋里养孩子，所以本义是生育、抚养。《说文解字》说「字，乳也。从子在宀下，子亦声」。金文的「字」又表示「生」，如吴王光鉴有「唯王五月，既字白期」，郭沫若、于省吾释为「既生霸」；善夫簋有「百子千孙，子子孙孙永宝用享」，「字」读作「子」。简帛材料里「字」也表示生，《睡虎地秦简．日书甲种》有「女子以巳字，不复字」，整理者注「字，生子」。后来「字」引申为文字、书写的字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「字」條；香港中文大學《漢語多功能字庫》「字」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%97（2026-11-11 查閱）"},
  "13121_极_Z_說文‧木部": {"headline": "房屋最高的那根大梁。", "original_meaning": "「极」的本义是房屋的正梁。", "structure_desc": "「极」的繁体是「極」，从「木」从「亟」，「亟」作声符，本义是房屋的正梁。《说文解字》说「极，栋也。从木，亟声」，徐锴《繫传》说「极，屋脊之栋也」。《汉书．天文志》有「后流星下燕万载宫极」，颜师古注引李奇说「极，屋梁也」。后来「极」引申表示顶点、最高点，《广雅．释诂四》说「极，高也」，如《诗．唐风．鸨羽》有「悠悠苍天，曷其有极」。现在「极」又表示极点、终极，又表示极端、极点。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「極」條；香港中文大學《漢語多功能字庫》「極」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A5%B5（2026-11-11 查閱）"},
  "15009_满_Z_小篆": {"headline": "水多到要溢出来。", "original_meaning": "「满」的本义是充盈、充满。", "structure_desc": "「满」的繁体是「滿」，从「水」从「㒼」，「㒼」作声符，「水」表意，本义是充盈、充满。《说文解字》说「满，盈溢也。从水，㒼声」。《庄子．天运》有「在谷满谷，在坑满坑」，成玄英疏「乃谷乃坑，悉皆盈满」。后来「满」表示满足，《汉书．食货志上》有「其心意未满，狭小汉家制度，以为疏阔」；又表示自满，《书．仲虺之诰》说「志自满，九族乃离」；还用作表示全、整个。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「滿」條；香港中文大學《漢語多功能字庫》「滿」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%BB%BF（2026-11-11 查閱）"},
  "22455_请_Z_小篆": {"headline": "上朝拜见天子。", "original_meaning": "「请」的本义是朝见、朝请。", "structure_desc": "「请」的繁体是「請」，金文从「言」从「青」从「口」，「青」是声符，「口」旁当为饰笔，本义是朝见、朝请。《说文解字》说「请，谒也。从言，青声」，段玉裁注「周礼：春朝秋觐。汉改为春朝秋请」。《周礼．春官》记诸侯见王六礼：春见曰朝，夏见曰宗，秋见曰觐，冬见曰遇，时见曰会，殷见曰同。金文里「请」音近通读为「靖」，表示镇抚、安定，中山王方壶有「以请郾疆」之语。后来「请」表示请求、邀请，又表示聘请。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「請」條；香港中文大學《漢語多功能字庫》「請」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%AB%8B（2026-11-11 查閱）"},
  "23452_远_Z_小篆": {"headline": "走在很远的路上。", "original_meaning": "「远」的本义是辽远。", "structure_desc": "「远」的繁体是「遠」，甲骨文从「彳」从「袁」，「袁」作声符，「彳」象道路，所以「远」有路途遥远之意，本义是辽远。金文从「辵」从「袁」，从「彳」「辵」的字都有行走之意，「远」表示脚程遥远。《说文解字》说「远，辽也。从辵，袁声」。甲骨文里「远」表示遥远，与「迩」相对，《屯南》3759有「王其田远，湄日无灾」。金文表示安抚远方，晋姜鼎有「用康柔妥怀远迩君子」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「遠」條；香港中文大學《漢語多功能字庫》「遠」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%81%A0（2026-11-11 查閱）"},
  "18491_类_Z_小篆": {"headline": "狗最懂得同类相聚。", "original_meaning": "「类」的本义是种类。", "structure_desc": "「类」的繁体 is「類」，从「犬」从「頪」，「頪」作声符，「犬」表意，本义是种类，即多种相同或相似事物的综合。《说文解字》说「类，种类相似，唯犬为甚。从犬，頪声」。《易．乾》说「本乎天者亲上，本乎地者亲下，则各从其类也」。后来「类」表示法则、法式，《荀子．非十二子》有「谓之五行，甚僻违而无类」；又指事理，《孟子．告子上》有「此之谓不知类也」。还表示比较、类似。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「類」條；香港中文大學《漢語多功能字庫》「類」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A1%9E（2026-11-11 查閱）"},
  "19078_细_Z_小篆": {"headline": "细小到像一根丝。", "original_meaning": "「细」的本义是微小，指微小的丝。", "structure_desc": "「细」的繁体是「細」，从「糸」从「囟」，「囟」在隶楷阶段讛变为「田」。《说文解字》说「细，微也。从糸，囟声」。「细」表示微小，朱骏声以为本义是微小的丝，《说文通训定声》说「细者，丝之微也」。后来「细」与「巨」相对，《史记．田儋列传》有「政无巨细皆断于相」；又与「粗」相对，《魏书．乐志》有「弦有粗细」。还引申表示琐碎、精细。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「細」條；香港中文大學《漢語多功能字庫》「細」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B4%B0（2026-11-11 查閱）"},
  "07483_养_Z_小篆": {"headline": "拿着鞭子放羊。", "original_meaning": "「养」的本义是牧养牲畜。", "structure_desc": "「养」的繁体是「養」，从「食」从「羊」，「羊」作声符。《说文解字》说「养，供养也。从食，羊声」，又收古文「𢼝」。「𢼝」又作「䍩」，从「羊」从「攴」，字形见于战国楚简，如《郭店简．六德》简33有「求养亲之志」。甲骨文里有从「羊」从「攴」的「䍩」字，金文字形从「羊」从「𠓥」，一般释为「牧」的异体。商承祚认为字形与《说文》古文同，象以手持鞭而牧羊：「牧牛则字从牛，养羊则字从羊也」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「養」條；香港中文大學《漢語多功能字庫》「養」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A4%8A（2026-11-11 查閱）"},
  "09611_始_Z_說文‧女部": {"headline": "一个女孩子的开始。", "original_meaning": "「始」的本义是女子初生，引申为开端。", "structure_desc": "「始」从「女」从「台」，「台」作声符，「台」是「㠯」的孳乳字，上古读音、用法相同，疑本义是女姓。许慎则认为本义是女子初出生。《说文解字》说「始，女之初也。从女台声」。金文的「始」读作「姒」，用作姓氏，如孟始鬲有「孟始乍宝鬲」，颂鼎有「皇母龏始宝尊鼎」。此外「始」字金文异体有加从「司」之形，「司」也是「始」的声符。后来「始」表示开始、开端，比如「始终」「创始」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「始」條；香港中文大學《漢語多功能字庫》「始」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A7%8B（2026-11-11 查閱）"},
  "11311_息_Z_說文‧心部": {"headline": "鼻子呼出的气息。", "original_meaning": "「息」的本义是气息、喘息。", "structure_desc": "「息」的甲骨文和早期金文从「自」从数点，「自」象鼻子，全字象鼻子呼出气息之形，本义是气息、喘息。《说文解字》说「息，喘也。从心从自，自亦声」，段玉裁注「人之气急曰喘，舒曰息，引伸为休息之偁，又引伸为生长之偁」，又说「心气必从鼻出，故从心自」。战国金文改从「自」从「心」，「心」是声符。杨树达认为「心」是指肺而言，从「心」从「自」，会气息自肺达于鼻。后来「息」表示止息、休息，又表示子息、利息。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「息」條；香港中文大學《漢語多功能字庫》「息」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%81%AF（2026-11-11 查閱）"},
  "06926_低_Z_說文‧人部": {"headline": "离地面很近。", "original_meaning": "「低」的本义是离地面距离小，与「高」相对。", "structure_desc": "「低」从「人」从「氐」，「氐」亦声，《说文新附》释为「下也。从人、氐，氐亦声」。《六书故．人一》说「低，卑也。古称高卑，今言高低」。南朝梁萧纲《采莲曲》有「香风起，白日低」。后来「低」表示向下，《庄子．盗跖》有「据轼低头，不能出气」；又表示一般水平或标准之下，苏轼《金橙径》有「不见鲈鱼价自低」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「低」條；香港中文大學《漢語多功能字庫》「低」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%8E（2026-11-11 查閱）"},
  "19046_约_Z_小篆": {"headline": "用绳子把东西缠住。", "original_meaning": "「约」的本义是缠束、环束。", "structure_desc": "「约」从「糸」从「勺」，「勺」作声符，本义是缠束、环束。《说文解字》说「约，缠束也。从糸，勺声」。《诗经．小雅．斯干》有「约之阁阁，椓之橐橐」，毛传说「约，束也」。后来「约」也表示绳子，《左传．哀公十一年》有「人寻约，吴发短」，杜预注「约，绳也。八尺为寻」；又表示约束、检束，《论语．雍也》说「君子博学于文，约之以礼」。还表示省减、简约。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「約」條；香港中文大學《漢語多功能字庫》「約」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B4%84（2026-11-11 查閱）"},
  "16203_王_Z_說文‧王部": {"headline": "一把锋刃朝下的斧钺。", "original_meaning": "「王」的本义是斧钺，象征王权。", "structure_desc": "「王」是把「戉」字转九十度，把全字转向以与原字区别。早期金文底画呈弧形，且弧笔丰厚，仍保留锋刃之形；后期金文底画线条化为一横，容易与「玉」字相混，区别是「王」的首两横画较接近，而与底画距离较远，而「玉」字三横之间的距离相约；后来为了进一步区别二字，遂于「玉」字中加点。甲骨文里「王」「士」用同一个字形表示（林澐），因为斧钺既是王权的象征，又是武士所持的器具。董仲舒说「三画而连其中谓之王」，指的是天地人三才贯通。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「王」條；香港中文大學《漢語多功能字庫》「王」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%8E%8B（2026-11-11 查閱）"},
  "18629_紅_Z_說文‧糸部": {"headline": "丝织品上的淡红色。", "original_meaning": "「红」的本义是浅赤色的帛。", "structure_desc": "「红」的繁体是「紅」，从「糸」从「工」，「工」作声符，「糸」表意，本义是浅赤色的帛。《说文解字》说「红，帛赤白色。从糸，工声」。《史记．司马相如列传》有「红杳渺以眩溣兮」，司马贞索隐「红，赤色貌」。后来「红」泛指各种红色，唐白居易《忆江南》有「日出江花红胜火，春来江水绿如蓝」。又可借指红色的花，韩愈《花源》有「叮咀红与紫，慎莫一时开」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「紅」條（今字作「红」）；香港中文大學《漢語多功能字庫》「紅」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B4%85（2026-11-11 查閱）"},
  "14664_消_Z_說文‧水部": {"headline": "冰雪化开，水流走了。", "original_meaning": "「消」的本义是冰雪溶化。", "structure_desc": "「消」从「水」从「肖」，「肖」作声符，「水」表意。「消」本指冰雪溶化，《礼记．月令》说「时雪不降，冰冻消释」。后来泛指各种事物的消散、消失。《说文解字》说「消，尽也。从水，肖声」。《孟子．滕文公下》有「险阻既远，鸟兽之害人者消，然后人得平土而居之」，赵岐注「水去，故鸟兽害人者消尽也」。后来「消」引申表示除去、消除。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「消」條；香港中文大學《漢語多功能字庫》「消」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B6%88（2026-11-11 查閱）"},
  "08358_哦_Z_說文‧口部": {"headline": "张口唱出一声。", "original_meaning": "「哦」的本义是吟哦、吟诵。", "structure_desc": "「哦」从「口」从「我」，金文和战国楚系文字为上下结构，小篆为左右结构。《说文新附》说「哦，吟也。从口，我声」。如唐代韩愈《记梦》有「壮非少者哦七言，六字常语一字难」，北宋梅尧臣《吊石曼卿》有「独哦秋露中，岂顾衣裘湿」。金文里「哦」用作人名，楚简里读为「义」，《郭店简．忠信之道》简8有「信，义之基也」。后来「哦」也作叹词，表示领会、醒悟。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「哦」條；香港中文大學《漢語多功能字庫》「哦」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%93%A6（2026-11-11 查閱）"},
  "20271_药_Z_小篆": {"headline": "能治病的草。", "original_meaning": "「药」的本义是药物、药材。", "structure_desc": "「药」的繁体是「藥」，从「艸」从「樂」，「樂」作声符，「艸」表意，本义是药物、药材。《说文解字》说「药，治病艸。从艸，乐声」。《周礼．天官．医师》说「医师掌医之政令，聚毒药以共医事」。后来「药」表示疗治，《诗经．大雅．板》有「多将烕烕，不可救药」。也可以指某些有化学作用的物质，宋应星《天工开物．火器》说「铁管载药，嵌盛木棍之中，以便手握」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「藥」條；香港中文大學《漢語多功能字庫》「藥」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%97%A5（2026-11-11 查閱）"},
  "10105_容_Z_說文‧宀部": {"headline": "一间能装东西的屋子。", "original_meaning": "「容」的本义是盛载。", "structure_desc": "「容」的金文从「宀」从「公」，「公」作声符，「宀」表意，是可容纳的房屋、仓库，所以本义是盛载。《说文解字》说「容，盛也。从宀、谷」，又收古文「㝐」从「公」。战国竹简多从「宀」「公」声，构形与金文相同；或改从「穴」，遂演化成后来小篆从「宀」从「谷」之形。金文里「容」用作本义表示盛载，三年詔事鼎有「容一斗二升」，《礼记．投壶》说「容斗五升」。后来「容」引申有容纳、宽容的意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「容」條；香港中文大學《漢語多功能字庫》「容」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%B9（2026-11-11 查閱）"},
  "23454_连_Z_小篆": {"headline": "人拉着车走在路上。", "original_meaning": "「连」的本义是相连、连接。", "structure_desc": "「连」的繁体 is「連」，金文从「车」从「辵」，「辵」旁反写，「止」象人脚，会人拉车行走之意（参段玉裁）。《说文解字》说「连，员连也。从辵从车」，段玉裁改为「负车也」，注云「连即古文辇也。负车者，人挽车而行，车在后如负也。字从辵车会意，犹辇从㚘车会意也。人与车相属不绝，故引伸为连属字」。金文里「连」表示结盟，能原镈有「连者夷」之语。《孟子．离娄》说「连诸侯者次之」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「連」條；香港中文大學《漢語多功能字庫》「連」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%80%A3（2026-11-11 查閱）"},
  "08112_台_Z_說文‧口部": {"headline": "四方而高的一个平台。", "original_meaning": "「台」的本义是四方高而平的建筑。", "structure_desc": "「台」的繁体是「臺」，甲骨文从「之」从「宀」，「之」是声符，「宀」表示与建筑物有关。战国文字从「室」「之」声，从「宀」与从「室」意义相近。后来「臺」上半的声符「之」字下又增从「口」，逐渐演变为现在的「臺」。《说文解字》以为「臺」字从「高」省，是把「室」的上半跟「口」形结合成一部分而言（姚萱）。《尔雅．释宫》说「四方而高曰台」。《左传．僖公五年》有「公既视朔，遂登观台以望」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「臺」條；香港中文大學《漢語多功能字庫》「臺」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%87%BA（2026-11-11 查閱）"},
  "24793_错_Z_小篆": {"headline": "打磨玉石用的砺石。", "original_meaning": "「错」的本义是琢玉石的砺石、磨石。", "structure_desc": "「错」的繁体是「錯」，从「金」从「昔」，「昔」作声符，本义是琢玉石的砺石、磨石。《书．禹贡》有「锡贡磬错」，孔传说「治玉石曰错，治磬错」，孔颖达疏「磬有以玉为之者，故云治玉石曰错」。后来「错」表示用金涂饰，《说文解字》说「错，金涂也。从金，昔声」，《盐铁论．散不足》有「金错蜀杯」；也可泛指嵌饰，《国语．晋语八》有「文错其服」。又表示锉刀，列女传有「错者所以治锯」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「錯」條；香港中文大學《漢語多功能字庫》「錯」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%8C%AF（2026-11-11 查閱）"},
  "13059_权_Z_小篆": {"headline": "木杆上挂着一块秤砣。", "original_meaning": "「权」的本义是秤锤。", "structure_desc": "「权」的繁体是「權」，从「木」从「雚」，「雚」作声符，「木」表意。《说文解字》说「权，秤也。从木，雚声」，段玉裁注「秤者，衡也」。《论语．子罕》有「君子不 Schwer重，荡荡乎不知其名」。后来「权」表示秤锤，又引申为衡量、权衡，进而表示权力、权变。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「權」條；香港中文大學《漢語多功能字庫》「權」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AC%8A（2026-11-11 查閱）"},
  "08333_响_Z_小篆": {"headline": "声音从回音的屋子里传出来。", "original_meaning": "「响」的本义是回声。", "structure_desc": "「响」的繁体 is「響」，从「鄉」从「音」，「鄉」作声符，「音」表意。《说文解字》说「响，声也。从音鄉声」，本义是回声。甲骨文从「鄉」从「音」，金文或从「鄉」从「言」。声音在山谷或屋子里来回反射，就有了回响，所以本义是回声。后来「响」表示声音、声响，又表示回响、应声。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「響」條；香港中文大學《漢語多功能字庫》「響」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9F%BF（2026-11-11 查閱）"},
  "22465_谁_Z_小篆": {"headline": "言字旁，问的是哪一个人。", "original_meaning": "「谁」的本义是询问的话语，即「何」。", "structure_desc": "「谁」的繁体是「誰」，从「言」从「隹」，「隹」作声符，「言」表意。《说文解字》说「谁，问也。从言隹声」，本义是询问的话语，也就是「何」。后来「谁」成为疑问代词，用来询问不定的人或事物，比如「是谁」「谁说的」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「誰」條；香港中文大學《漢語多功能字庫》「誰」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%AA%B0（2026-11-11 查閱）"},
  "11201_态_Z_小篆": {"headline": "心里装着，能是什么样子。", "original_meaning": "「态」的本义是姿态、容态。", "structure_desc": "「态」的繁体是「態」，从「心」从「能」，「能」作声符，「心」表意。《说文解字》说「态，熊态也。从心能声」，本义是姿态、容态。这个字属于《说文解字》的《说文新附》，是东汉以后才收入的字。后来「态」表示神态、态度，又表示情势、状态。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「態」條；香港中文大學《漢語多功能字庫》「態」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%85%8B（2026-11-11 查閱）"},
  "07541_况_Z_小篆": {"headline": "水冷到什么程度，情况就怎样。", "original_meaning": "「况」的本义是水寒的情形。", "structure_desc": "「况」的繁体是「況」，从「水」从「兄」，「兄」作声符，「水」表意。《说文新附》说「況，洞也。从水兄声」，指水的深度。后来「况」引申为情况、情形，又表示比况、何况。这个字也属于《说文新附》，是东汉以后才补入的。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「況」條；香港中文大學《漢語多功能字庫》「況」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B3%81（2026-11-11 查閱）"},
  "06688_习_Z_說文‧羽部": {"headline": "太阳底下，把羽毛晒得暖暖的。", "original_meaning": "「习」的本义是暴晒，后来假借为习惯、练习。", "structure_desc": "「习」的繁体是「習」，甲骨文从「彗」从「日」，「彗」是声符，「日」是意符，所以本义是暴晒。根据唐兰的研究，甲骨文的「彗」字形与后来的「羽」字相近，但不是「羽」而是「彗」，因为甲骨文没有「羽」字。「彗」暴晒的意义后来保留在同从「彗」声的「㷵」字中，《汉书．贾谊传》说「日中必㷵」，《说文》释「㷵，暴乾也」。「习」本身则被假借为鸟重复试飞、熟习、习惯、学习的意义。到小篆，「習」所从的「彗」讹变为「羽」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「習」條；香港中文大學《漢語多功能字庫》「習」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BF%92（2026-11-11 查閱）"},
  "06839_价_Z_說文‧人部": {"headline": "人和货品买卖，就是「价」。", "original_meaning": "「价」的本义是价格，是「贾」的今字。", "structure_desc": "「价」的繁体是「價」，从「人」从「贾」，「贾」亦声，本义是价格，是「贾」的今字，可参看「贾」。《说文解字》说「价，物直也。从人、贾，贾亦声」。《韩非子．外储说左下》有「郑县人卖豚，人问其价」，用的就是这个意思。后来「价」也表示声望、名声，北齐颜之推《颜氏家训．名实》说「夫神灭形消，遗声余价」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「價」條；香港中文大學《漢語多功能字庫》「價」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%83%B9（2026-11-11 查閱）"},
  "07641_则_Z_小篆": {"headline": "在鼎上刻下字，成为规矩。", "original_meaning": "「则」的本义是法则。", "structure_desc": "「则」的金文从「鼎」从「刀」，表示用刀在鼎上刻画文字，作为法则，所以本义是法则。《左传．昭公六年》记「郑人铸刑书」，杜预注「铸刑书于鼎，以为国之常法」。「则」字至今保留这一原义，但也被假借为虚词「则」。《说文解字》说「则，等画物也。从刀从贝。贝，古之物货也」，又收籀文从「鼎」。战国竹简里「鼎」往往写作「贝」，为小篆所本，今天「则」字中的「贝」其实是古文字「鼎」的讹写。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「則」條；香港中文大學《漢語多功能字庫》「則」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%89%87（2026-11-11 查閱）"},
  "07642_刚_Z_小篆": {"headline": "一刀把网割断。", "original_meaning": "「刚」的本义是刚强、刚劲。", "structure_desc": "「刚」的繁体 is「剛」，甲骨文从「刀」从「网」，「网」是「网」的初文，全字象以刀割断网之形，以示强力之意。《说文解字》说「刚，强断也。从刀，冈声」，又收古文「𠇙」。因为刀能割断最坚韧的网，所以「刚」引申出刚强、坚强、刚劲的意思，后来又表示刚刚、才。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「剛」條；香港中文大學《漢語多功能字庫》「剛」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%89%9B（2026-11-11 查閱）"},
  "07775_功_Z_說文‧力部": {"headline": "用气力做工，有了功劳。", "original_meaning": "「功」的本义是功劳、功绩。", "structure_desc": "「功」从「力」从「工」，「工」作声符，「力」表意。《说文解字》说「功，以劳定国也。从力从工，工亦声」，用功劳来安定国家，所以本义是功劳、功绩。金文里「功」表示功劳，师艅尊有「王夜功，易师艅金」，记述周王奖掖师艅的功劳。马王堆汉墓帛书表示功绩、功劳，《马王堆．老子甲本》说「不自伐故有功，弗矜故能长」。后来「功」表示功效、作用，又表示功夫。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「功」條；香港中文大學《漢語多功能字庫》「功」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%9F（2026-11-11 查閱）"},
  "07946_半_Z_說文‧半部": {"headline": "把一头牛劈成两半。", "original_meaning": "「半」的本义是剖开，引申为一半。", "structure_desc": "「半」的春秋金文从「八」从「牛」，「八」亦是声符，会出把牛只分割为两半之意，是「判」的初文（何琳仪）。本义是剖开。把事物切开，即成两半，所以「半」有一半之义。「八」象物体被分开两半，既是「半」的意符，又是声符。《说文解字》说「半，物中分也。从八从牛，牛为物大，可以分也」。后来「半」又表示一半的程度，比如「半途而废」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「半」條；香港中文大學《漢語多功能字庫》「半」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%8A（2026-11-11 查閱）"},
  "07988_却_Z_小篆": {"headline": "后退一步，让开。", "original_meaning": "「却」的本义是使之退。", "structure_desc": "「却」的繁体是「卻」，从「卩」从「𧮫」，「𧮫」作声符，「卩」象跪坐的人，表示使之退。《战国策．秦策一》有「弃甲兵，怒战慄而却」。后来「却」表示拒绝、推辞，《孟子．万章下》说「却之却之为不恭」；也表示推后、撤去，《汉书．文帝纪上》记「盎却慎夫人席，慎夫人怒，不肯坐」。又表示返回、止息。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「卻」條；香港中文大學《漢語多功能字庫》「卻」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%BB（2026-11-11 查閱）"},
  "08066_参_Z_小篆": {"headline": "三颗亮星挂在头顶。", "original_meaning": "「参」的本义是二十八宿中的参星。", "structure_desc": "「参」的繁体是「參」，金文从「晶」从「光」，「彡」亦是声符，「晶」象三颗星星，而参宿有三颗星特别明亮，所以朱芳圃认为「参」字象参宿三星在人头上、光芒下射之形，本义是二十八宿中的参星。「彡」除了是声符外，既可象星光的辉煌，也可指参星之三数；到了后期有不少讛变的形体，如讹作从「三」声。《诗经．豳风．七月》有「七月流火，九月授衣」。后来「参」用来表示参与、参加。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「曑」條（今字作「参」）；香港中文大學《漢語多功能字庫》「參」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%83（2026-11-11 查閱）"},
  "08119_号_Z_說文‧号部": {"headline": "老虎在山林里的一声吼。", "original_meaning": "「号」的本义是老虎的吼叫声。", "structure_desc": "「号」的繁体是「號」，从「虎」从「号」，「号」亦声，「虎」表意。因为古时遍地山林，老虎为患，老虎的吼声最吓人，所以「號」字以「虎」为意符，本指老虎咆哮。南北朝释慧皎《高僧传》卷十一有「行人数里，忽大风雨，群虎号鸣」。引申为动物禽畜的鸣叫声，《史记．历书》有「时鸡三号，卒明」。再引申为一切生物、事物的呼声，杜甫《茅屋为秋风所破歌》有「八月秋高风怒号」。后来「号」又表示名号、称号、号令。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「號」條；香港中文大學《漢語多功能字庫》「號」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%99%9F（2026-11-11 查閱）"},
  "08357_哥_Z_說文‧可部": {"headline": "两个「可」叠在一起。", "original_meaning": "「哥」的本义是声音，是「歌」的古字。", "structure_desc": "「哥」从二「可」，是「歌」的古字。《说文解字》说「哥，声也。从二可。古文以为歌字」，段玉裁注「声也。此义未见用者。今呼兄为哥……汉书多用哥为歌」。因为「可」可用来表示唱和、呼引，两个「可」相叠就表示唱和之声。后来「哥」用来称呼同父母或同父异母、同母异父的兄长，段玉裁所说的「今呼兄为哥」就是这个意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「哥」條；香港中文大學《漢語多功能字庫》「哥」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%93%A5（2026-11-11 查閱）"},
  "08454_商_Z_說文‧㕯部": {"headline": "把柴薪架在高台上烧，祭祀大火星。", "original_meaning": "「商」的本义是祭祀大火星。", "structure_desc": "「商」字的本义不详，朱芳圃认为字从「丙」从「辛」，「丙」象高台之形，「辛」即「薪」之省形，全字会把柴薪放到高台上燃烧，以祭祀大火星，所以本义是祭星。另外，甲金文的「商」字除一般写法外，也有在两旁加从两个或四个圆圈的（象星星之形），即表示星宿中与「参」永不相见的「商」的专字（天蝎座的主星心宿二，又名大火星，也就是《诗经．豳风．七月》中「七月流火」所指的星）。后来「商」借作商贾之「商」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「商」條；香港中文大學《漢語多功能字庫》「商」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%95%86（2026-11-11 查閱）"},
  "09457_失_Z_說文‧手部": {"headline": "手一松，东西溜走了。", "original_meaning": "「失」的本义是遗失、失去。", "structure_desc": "「失」从「手」从「乙」，「乙」作声符，「手」表意。段玉裁注说「在手而逸去为失」，所以本义是遗失、失去。《左传．成公八年》有「君命无贰，失信不立」，《墨子．鲁问》有「失天下」。后来「失」表示错过、耽误，《孟子．梁惠王上》说「鸡豚狗彘之畜，无失其时，七十者可以食肉矣」；又表示违背，《孟子．尽心上》说「故士穷不失义，达不离道」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「失」條；香港中文大學《漢語多功能字庫》「失」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%B1（2026-11-11 查閱）"},
  "09616_姐_Z_說文‧女部": {"headline": "同辈里年长的女子。", "original_meaning": "「姐」的本义是对母亲的称呼。", "structure_desc": "「姐」从「女」从「且」，「且」作声符，早期用作对母亲的称呼。《说文解字》说「姐，蜀谓母曰姐，淮南谓之社。从女，且声」。《广雅．释亲》说「姐，母也」，《广韵．马韵》说「姐，羌人呼母」。后来「姐」泛指「女兄」，即年龄比自己大的女子，宋吴曾《能改斋漫录．妇女称姐》说「近世多以女兄为姐，盖尊之也」。今天「姐姐」「二姐」都表示同胞且年龄长于自己的女子。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「姐」條；香港中文大學《漢語多功能字庫》「姐」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A7%90（2026-11-11 查閱）"},
  "10025_孩_Z_說文‧口部": {"headline": "刚出生的婴儿。", "original_meaning": "「孩」的本义是幼儿。", "structure_desc": "「孩」从「子」从「亥」，「亥」作声符，「子」表意，本义是幼儿。《广韵．咍韵》说「孩，始生小儿」。晋代诗文用其本义，郭璞《游仙诗》有「奇龄迈五龙，千岁方婴孩」，李密《陈情表》有「生孩六月，慈父见背」。后来「孩」引申为幼小，《礼记．月令》说「毋覆巢，毋杀孩虫」。「孩」另有婴儿笑之义，同「咳」，《说文．口部》说「咳，小儿笑也。孩，古文咳从子」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「咳」條（今字作「孩」）；香港中文大學《漢語多功能字庫》「孩」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%A9（2026-11-11 查閱）"},
  "10240_局_Z_說文‧口部": {"headline": "一个口，缩在尺下面。", "original_meaning": "「局」的本义是局促。", "structure_desc": "「局」从「口」在「尺」下，「尺」表示尺度，口缩在尺下，所以是局促。《说文解字》说「局，促也。从口在尺下，复局之。一曰：博所以行棋。象形」，又说它本是下棋用的棋盘。三国魏曹植《仙人篇》有「四海一何局，九州安所如」。后来「局」表示弯曲、委屈，《诗经．小雅．正月》有「谓天盖高，不敢不局」；又表示拘束、局限，以及权限、范围、官署等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「局」條；香港中文大學《漢語多功能字庫》「局」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B1%80（2026-11-11 查閱）"},
  "10691_布_Z_說文‧巾部": {"headline": "麻织成的布匹。", "original_meaning": "「布」的本义是麻织品。", "structure_desc": "「布」的金文从「巾」从「父」，「父」作声符，「巾」是形符，铭文中表示布匹，乍册睘卣有「夷白宾睘贝、布」。战国竹简的字形下不从「巾」而从「巿」，「巿」也表示「巾」的意思。后来「布」所从的「父」讹变为「𠂇」，就成了楷书的「布」。《说文解字》说「布，枲织也」，本义是麻织品。《礼记．礼运》说「治其麻丝，以为布帛」，《小尔雅．广服》说「麻、苧、葛，曰布。布，通名也」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「布」條；香港中文大學《漢語多功能字庫》「布」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B8%83（2026-11-11 查閱）"},
  "11072_往_Z_說文‧彳部": {"headline": "迈开脚步，走向那边。", "original_meaning": "「往」的本义是去、到。", "structure_desc": "「往」的初文作「㞷」，金文增「彳」旁，写作「𢓸」。「𢓸」从「彳」，「㞷」声，「彳」表意表示行走。战国楚系文字或从「辵」，与《说文》古文相同，「彳」和「辵」是义近形符。「𢓸」的声符「㞷」后来省作「主」形，隶楷书就写作「往」。《说文解字》说「往，之也。从彳，𡉚声」。后来「往」表示去、到，又表示过去的、从前的。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「往」條；香港中文大學《漢語多功能字庫》「往」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%80（2026-11-11 查閱）"},
  "11159_志_Z_說文‧心部": {"headline": "心里想着要去哪里。", "original_meaning": "「志」的本义是心意、志向。", "structure_desc": "「志」的金文从「之」从「心」，「之」者往也，所以「志」会出心之所往之意，也就是志向，因此「之」不只标声，也兼作意符。「志」字的构形与「直」或「德」等字也有异曲同工之妙。「志」字在楚简有从「之」从「心」和从「之」从「目」两种字形，不过从「之」从「目」的一字形多读为「识」，表示记忆，学者或认为这是「识」的异文，因为「志」「识」古音相近，可以通假。金文里「志」用作心意、志向之意，中山王方壶有「竭志尽忠」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「志」條；香港中文大學《漢語多功能字庫》「志」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%97（2026-11-11 查閱）"},
  "11775_房_Z_說文‧戶部": {"headline": "正屋两边，各有一间。", "original_meaning": "「房」的本义是正室左右两边的房间。", "structure_desc": "「房」从「户」从「方」，「方」作声符，「户」表意。《说文解字》说「房，室在旁也。从户，方声」，段玉裁注「凡堂之内，中为正室，左右为房，所谓东房西房也」。《释名．释宫室》说「房，旁也，在室两旁也」。据考古发掘，在岐山凤雏发现的西周建筑基址，左右两边有东西厢，各有三间「房」。后来「房」泛指房间，《汉书．赵尹韩张两王传》有「臣闻闺房之内，夫妇之私」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「房」條；香港中文大學《漢語多功能字庫》「房」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%BF（2026-11-11 查閱）"},
  "12669_施_Z_說文‧㫃部": {"headline": "旌旗在风里展开摇动。", "original_meaning": "「施」的本义是旌旗摇曳的样子。", "structure_desc": "「施」从「㫃」从「也」，「也」作声符，「㫃」象旗杆和旗子，表示旌旗摇曳之貌。《说文解字》说「施，旗皃。从㫃，也声。齐栾施字子旗，知施者旗也」。后来「施」表示旄羽珥，即旌旗竿头的饰物，《逸周书．王会》有「楼烦以星施」。又表示散布、铺陈，《易．乾》说「云行雨施，品物流形」；还表示设置、安放，以及施行、施展、给予。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「施」條；香港中文大學《漢語多功能字庫》「施」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%BD（2026-11-11 查閱）"},
  "12755_易_Z_說文‧易部": {"headline": "把东西换到别人手里。", "original_meaning": "「易」的本义是赐与，是「赐」的古字。", "structure_desc": "「易」的甲骨文和金文由「益」简化而成，「益」象器中盛水，「易」简化了所盛的三点水和器皿上供提拿的鋬（犹今语把儿、柄）。赏赐是使受赐者的财富有所增益，所以由「益」分化出「易」字（郭沫若），「易」是「赐」的古字，本义是赐与。赐与是财物由一人转移至另一人手中，所以引申有易手、易置、更易之意。引申为更抽象的一般意义之变易，号称群经之首的《周易》即以这最抽象意义的变易为课题。甲骨文表示赏赐，《合集》40073 有「易贝二朋」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「易」條；香港中文大學《漢語多功能字庫》「易」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%93（2026-11-11 查閱）"},
  "15403_火_Z_說文‧火部": {"headline": "一团火苗向上腾。", "original_meaning": "「火」的本义是火焰。", "structure_desc": "「火」的甲骨文象火焰上腾之形，比「山」字更有动态，原义是火。甲骨文的「火」与「山」字不易区分，最大分别是「火」有两点而「山」无，但「火」字也往往不加点；「山」和「火」的底部弧度也不同，「山」字一般较平，「火」字一般较弯，学者一般从其辞例判别两字。甲骨文里「火」用为本义，《合集》30774 有「火不延」，指火灾不会延续。又可用作星名，即大火星，或称心宿二。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「火」條；香港中文大學《漢語多功能字庫》「火」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%81%AB（2026-11-11 查閱）"},
  "15879_片_Z_說文‧片部": {"headline": "木头从中间劈成两半。", "original_meaning": "「片」的本义是把木头剖开。", "structure_desc": "「片」取「木」的右半字形而成，表示把木头剖开、分成两半。《说文解字》说「片，判木也。从半木」，段玉裁注「谓一分为二之木」。战国文字未见单独使用的「片」，用为偏旁时与「木」意思相同，中山王方壶的「策」写作从「竹」「𣂔」声，「𣂔」同「析」，从「片」和从「木」义同（参于豪亮）。后来「片」引申表示一半、偏，《论语．颜渊》说「片言可以析狱者」；又表示单、单个。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「片」條；香港中文大學《漢語多功能字庫》「片」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%89%87（2026-11-11 查閱）"},
  "16199_率_Z_說文‧率部": {"headline": "一根大绳索。", "original_meaning": "「率」的本义是麻绳、绳索。", "structure_desc": "「率」的甲骨文和金文从「糸」从四点，四点象素丝的光泽（何琳仪），「率」象大绳索之形（戴侗），是「𦆾」「𦆽」等字之初文（商承祚、徐中舒），本义是麻绳、绳索、丝绳。绳索可以用来牵引，所以引申为率领的「率」。《说文解字》说「率，捕鸟毕也。象丝网，上下其竿柄也」。后来「率」表示带领、统领，又表示比例、频率。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「率」條；香港中文大學《漢語多功能字庫》「率」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%8E%87（2026-11-11 查閱）"},
  "16233_玩_Z_說文‧玉部": {"headline": "手里把玩着一块玉。", "original_meaning": "「玩」的本义是戏弄、玩弄。", "structure_desc": "「玩」从「玉」从「元」，「元」作声符，本义是戏弄、玩弄。《说文解字》说「玩，弄也。从玉，元声」。《书．旅獒》说「玩人丧德」，孔传说「以人为戏弄则丧其德」。后来「玩」引申为玩赏之物，《国语．楚语下》说「若夫白珩，先王之玩也」；又引申为观赏、欣赏，《楚辞．远游》有「谁可与玩斯遗芳兮」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「玩」條；香港中文大學《漢語多功能字庫》「玩」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%8E%A9（2026-11-11 查閱）"},
  "16239_环_Z_小篆": {"headline": "一块中间有孔的圆玉。", "original_meaning": "「环」的本义是玉环、玉璧。", "structure_desc": "「环」的繁体 is「環」，西周晚期金文从「玉」从「睘」，「睘」作声符，也兼有表意作用，表示「环」是圆形的，本义是玉环、玉璧。西周早期金文写作「睘」，「睘」从「罒」从圆点从「衣」，本义是玉环；后来为了明确字义，在「睘」旁增加意符「玉」，表示以玉制成的环。《说文解字》说「环，璧也。肉好若一谓之环」，「肉」「好」分别指环的周边和中间的孔，郭璞注《尔雅》说「边、孔适等」，即玉的周边和璧孔宽度相约就称之为「环」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「環」條；香港中文大學《漢語多功能字庫》「環」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%92%B0（2026-11-11 查閱）"},
  "17787_离_Z_說文‧禸部": {"headline": "黄莺鸟在枝头鸣叫。", "original_meaning": "「离」的本义是离黄，即仓庚鸟。", "structure_desc": "「离」从「隹」从「离」，「离」作声符，「隹」表意，本义是离黄，即仓庚鸟。《说文解字》说「离，黄仓庚也，鸣则蚕生。从隹，离声」，《诗经．豳风．七月》有「春日载阳，有鸣仓庚」，毛传说「仓庚，离黄也」。《玉篇．隹部》说「离，亦作鸝，仓庚也」。后来「离」表示分开、分离，《孟子．梁惠王上》有「父母冻饿，兄弟妻子离散」；又表示离开，《广雅．释诂》说「离，去也」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「離」條；香港中文大學《漢語多功能字庫》「離」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9B%A2（2026-11-11 查閱）"},
  "19079_织_Z_小篆": {"headline": "把丝线一根根织成布。", "original_meaning": "「织」的本义是制作布帛。", "structure_desc": "「织」的繁体是「織」，金文从「糸」从「𢦏」，「𢦏」作声符，本义是制作布帛。鄂君启舟节有「织尹」，「织尹」是主管缝织绣锦的长官（参于省吾）。《说文解字》说「织，作布帛之总名也。从糸戠声」。《诗经．大雅．瞻卬》有「妇无公事，休其蚕织」。后来「织」泛指编织，《战国策．齐策六》说「将军之在即墨，坐而织篑，立则丈插」；也表示用染丝织成的丝织品。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「織」條；香港中文大學《漢語多功能字庫》「織」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B9%94（2026-11-11 查閱）"},
  "19117_续_Z_小篆": {"headline": "把断了的丝接起来。", "original_meaning": "「续」的本义是连接、接续。", "structure_desc": "「续」的繁体是「續」，从「糸」从「賣」声，「糸」表意，与丝线相接有关。《说文解字》说「续，连也。从糸賣声」，又收古文「賡」，从「庚」「貝」。因为丝线断了要接续，所以「续」的本义是连接、接续。《庄子．大宗师》说「相接而为一也者，则续矣」。后来「续」表示接续、延续，又表示继承、继续。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「續」條；香港中文大學《漢語多功能字庫》「續」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BA%8C（2026-11-11 查閱）"},
  "21637_装_Z_小篆": {"headline": "用衣服把东西裹起来。", "original_meaning": "「装」的本义是包裹、裹束。", "structure_desc": "「装」从「衣」从「壮」，「壮」作声符，「衣」表意，本义是包裹、裹束。《说文解字》说「装，裹也。从衣，壮声」。《史记．郦生陆贾列传》记「赐陆生橐中装直千金，他送亦千金」，裴骃集解引张晏说「装，裹也」。后来「装」表示衣服、服装，《文选．傅毅〈舞赋〉》有「顾形影，自整装」；也表示装饰、打扮，以及装载、假装、扮演。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「裝」條；香港中文大學《漢語多功能字庫》「裝」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A3%9D（2026-11-11 查閱）"},
  "21894_视_Z_小篆": {"headline": "一只眼睛在看。", "original_meaning": "「视」的本义是看、瞻视。", "structure_desc": "「视」的甲骨文从「目」从「人」，突出眼睛，以表视看之意。甲骨文和金文的「视」与「见」有区别，「视」的字形中眼睛更突出，表示正在看。《说文解字》说「视，瞻也。从见示」，又收古文「眎」「眡」。后来「视」表示看、观看，又表示看待、看待，还可以表示电視一类的词。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「視」條；香港中文大學《漢語多功能字庫》「視」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A6%96（2026-11-11 查閱）"},
  "22777_费_Z_小篆": {"headline": "把一贝一贝的钱财花出去。", "original_meaning": "「费」的本义是耗用钱财。", "structure_desc": "「费」从「贝」从「弗」，「弗」作声符，「贝」表意，本义是耗用钱财。《说文解字》说「费，散财用也。从贝弗声」。金文里「费」用作人名，如八年新城大令戈有「工师宋费」；《荀子．议兵》说「若是则戎甲俞众，奉养必费」。后来「费」表示费用，《庄子．庚桑楚》有「志乎期费者，唯贾人也」；也可表示耗损，宋王安石《韩子》有「可怜无补费精神」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「費」條；香港中文大學《漢語多功能字庫》「費」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B2%BB（2026-11-11 查閱）"},
  "23497_选_Z_小篆": {"headline": "恭恭敬敬地送人上路。", "original_meaning": "「选」的本义是遣送。", "structure_desc": "「选」的繁体是「選」，金文从「止」从「巽」，「巽」作声符，「巽」象顺服的跪坐人形，「止」象脚趾，有行走之意，所以本义是恭顺地遣送（许慎）。遣送与送走、舍弃义相关，选择、抉择即有取舍，所以「选」又有选择、简择之义。《说文解字》说「选，遣也。从辵、巽，巽，遣之。巽亦声。一曰：选，择也」。后来「选」表示挑选、选举。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「選」條；香港中文大學《漢語多功能字庫》「選」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%81%B8（2026-11-11 查閱）"},
  "23943_采_Z_說文‧木部": {"headline": "手伸到树上摘果子。", "original_meaning": "「采」的本义是采摘。", "structure_desc": "「采」从「木」从「爪」，甲骨文或不从「木」而从「果」，象手在树上采摘果实之形。「采」是「採」的初文，本义是采摘。《说文解字》说「采，捋取也。从木从爪」。甲骨文里「采」用作纪时名词，「大采」即日初出之时，「小采」即日落之时。金文表示采邑，中方鼎有「乍乃采」，《韩诗外传》说「古者天子为诸侯受封，谓之采地」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「采」條；香港中文大學《漢語多功能字庫》「採」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8E%A1（2026-11-11 查閱）"},
  "25087_阿_Z_說文‧阜部": {"headline": "一座大土山。", "original_meaning": "「阿」的本义是大土山，泛指山坡。", "structure_desc": "「阿」从「阜」从「可」，「可」作声符，「阜」表意。从「阜」的字多与山有关，所以「阿」的本义是大土山。《说文解字》说「阿，大陵也。一曰曲阜也。从阜，可声」。段玉裁注引《尔雅》说「大陵，丘陵」，泛指山坡。金文里「阿」用作地名，阿武戈有「阿武」，汉为侯国，属涿郡，故地在今河北省献县西北。后来「阿」多用作虚词，如「阿哥」「阿婆」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「阿」條；香港中文大學《漢語多功能字庫》「阿」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%98%BF（2026-11-11 查閱）"},
  "25657_项_Z_小篆": {"headline": "头后面那一段脖子。", "original_meaning": "「项」的本义是颈的后部，也泛指颈。", "structure_desc": "「项」从「页」从「工」，「工」作声符，「页」指头部，本义是颈的后部，也泛指颈。《说文解字》说「项，头后也。从页，工声」。《左传．成公十六年》记「王召养由基，与之两矢，使射吕锜，中项，伏弢」，说的就是射中颈项。后来「项」表示冠的后部，《仪礼．士冠礼》有「宾右手执项，左手执前进容」，贾公彦疏「冠后为项」；也表示种类、条款，还可作量词。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「項」條；香港中文大學《漢語多功能字庫》「項」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A0%85（2026-11-11 查閱）"},
};
